(function() {
    'use strict';

    var freeBox = document.getElementById('team-free-box');
    var originalBox = document.getElementById('team-original-box');

    if (freeBox) freeBox.style.display = 'none';
    if (originalBox) originalBox.style.display = 'block';

    function initFooterTeamWidget() {
        const teamPageMeta = document.querySelector('meta[name="teamPageUrl"]');
        const newTeamBand = document.getElementById('st-team-band');
        const oldTeamBand = document.querySelector('.team-work-band');

        if (!newTeamBand && !oldTeamBand) return;

        const metaExists = teamPageMeta && teamPageMeta.content && teamPageMeta.content.trim() !== "";

        if (metaExists) {
            console.log("✅ تم العثور على رابط الفريق. سيتم إظهار الأقسام.");

            if (newTeamBand) newTeamBand.style.display = 'block';
            if (oldTeamBand) oldTeamBand.style.display = 'block';

            const teamContainer = document.getElementById('st-team-container');
            if (newTeamBand && teamContainer) {
                teamContainer.style.display = 'flex';

                const meta = (name) => document.querySelector(`meta[name="${name}"]`)?.content || null;

                const chairmanName = meta('Chairman');
                const chairmanCard = document.getElementById('st-chairman-card');
                if (chairmanCard && chairmanName) {
                    document.getElementById('st-chairman-name').textContent = chairmanName;
                    const chairmanImg = document.getElementById('st-chairman-image');
                    if (chairmanImg) chairmanImg.src = meta('chairman-image') || '';
                    chairmanCard.style.display = 'flex';
                }

                const editorName = meta('Editor-in-Chief');
                const editorCard = document.getElementById('st-editor-card');
                if (editorCard && editorName) {
                    document.getElementById('st-editor-name').textContent = editorName;
                    const editorImg = document.getElementById('st-editor-image');
                    if (editorImg) editorImg.src = meta('editor-in-chief-image') || '';
                    editorCard.style.display = 'flex';
                }

                const siteName = meta('site-name') || 'الموقع';
                const titleEl = document.getElementById('st-workTeamTitle');
                if (titleEl) titleEl.textContent = 'فريق عمل ' + siteName;

                const teamLink = document.getElementById('st-view-team-link');
                if (teamLink) {
                    teamLink.href = teamPageMeta.content;
                    teamLink.textContent = 'تعرف على كامل الفريق';
                    teamLink.style.display = 'inline-block';
                }
            }
        } else {
            console.log("❌ لم يتم العثور على رابط الفريق. سيتم إخفاء جميع أقسام فريق العمل.");
            if (newTeamBand) newTeamBand.style.display = 'none';
            if (oldTeamBand) oldTeamBand.style.display = 'none';
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initFooterTeamWidget);
    } else {
        initFooterTeamWidget();
    }
})();

/* === SEOTurbo Module 08: 08-هيكل-القوائم-المنسدلة.js === */

(function() {
    'use strict';
    const blogUrl = window.location.origin;

    function injectManagementCard() {
        const originalCard = document.querySelector('.header-main .management-card');
        const stickyPlaceholder = document.getElementById('seoturbo-sticky-management-placeholder');
        if (!originalCard) return;
        const extractManagementData = () => {
            const photos = originalCard.querySelectorAll('.management-frame img');
            const roles = originalCard.querySelectorAll('.management-role span');
            const names = originalCard.querySelectorAll('.management-name');
            const data = [];
            if (photos[0] && roles[0] && names[0]) {
                data.push({ imgSrc: photos[0].src, role: roles[0].textContent.trim(), name: names[0].textContent.trim() });
            }
            if (photos[1] && roles[1] && names[1]) {
                data.push({ imgSrc: photos[1].src, role: roles[1].textContent.trim(), name: names[1].textContent.trim() });
            }
            return data;
        };
        const createCompactCard = (data) => {
            const card = document.createElement('div');
            card.className = 'management-card compact-version';
            const photosContainer = document.createElement('div');
            photosContainer.className = 'management-photos';
            data.forEach(item => {
                const managementItem = document.createElement('div');
                managementItem.className = 'management-item';
                const frame = document.createElement('div');
                frame.className = 'management-frame';
                const img = document.createElement('img');
                img.src = item.imgSrc;
                img.alt = item.name;
                img.loading = 'lazy';
                frame.appendChild(img);
                const infoWrapper = document.createElement('div');
                infoWrapper.className = 'management-info';
                const nameRoleWrapper = document.createElement('div');
                nameRoleWrapper.className = 'name-role-wrapper';
                const roleSpan = document.createElement('span');
                roleSpan.className = 'management-role';
                roleSpan.textContent = item.role;
                const nameSpan = document.createElement('span');
                nameSpan.className = 'management-name';
                nameSpan.textContent = item.name;
                nameRoleWrapper.appendChild(roleSpan);
                nameRoleWrapper.appendChild(nameSpan);
                infoWrapper.appendChild(nameRoleWrapper);
                managementItem.appendChild(frame);
                managementItem.appendChild(infoWrapper);
                photosContainer.appendChild(managementItem);
            });
            card.appendChild(photosContainer);
            return card;
        };
        const managementData = extractManagementData();
        if (managementData.length === 0) return;
        const newCard = createCompactCard(managementData);
        if (stickyPlaceholder) {
            stickyPlaceholder.innerHTML = '';
            stickyPlaceholder.appendChild(newCard.cloneNode(true));
        }
    }

    function initDynamicDropdowns() {
        var menu = document.getElementById('main-menu') || document.querySelector('.main-menu');
        if (!menu || menu.classList.contains('dropdowns-initialized')) return;
        menu.style.visibility = 'hidden'; 
        var topLevelItems = Array.from(menu.children).filter(item => item.tagName === 'LI');
        var parentItems = [], currentParent = null;
        menu.innerHTML = '';
        topLevelItems.forEach(item => {
            var link = item.querySelector('a');
            if (!link) return;
            var linkText = link.innerHTML.trim();
            if (linkText.startsWith('_')) {
                link.innerHTML = linkText.replace(/^_/, '');
                if (currentParent) {
                    var subMenu = currentParent.querySelector('ul.sub-menu');
                    if (!subMenu) {
                        subMenu = document.createElement('ul');
                        subMenu.className = 'sub-menu';
                        currentParent.appendChild(subMenu);
                        currentParent.classList.add('has-sub');
                    }
                    subMenu.appendChild(item);
                }
            } else {
                menu.appendChild(item);
                currentParent = item;
                parentItems.push(item);
            }
        });
        menu.classList.add('dropdowns-initialized');
        requestAnimationFrame(() => { menu.style.visibility = 'visible'; });
        if(typeof initHamburgerEngine === 'function') initHamburgerEngine();

        initMegaMenu();

        injectManagementCard();
    }

    function initMegaMenu() {
        if (typeof ST_PRO_LOAD_MEGA !== 'function') {
            console.log("SEOTurbo: Pro Engine not detected. Using Standard Menu.");
            return; 
        }

        document.querySelectorAll('.main-menu li a[href*="/search/label/"]').forEach(link => {
            var item = link.parentElement; 
            if (item.querySelector('.mega-menu-box, .sub-mega-menu-box')) return;
            var label = decodeURIComponent(link.getAttribute('href').split('/search/label/')[1].split('?')[0]);
            var megaBox = document.createElement('div');
            megaBox.className = item.closest('.sub-menu') ? 'sub-mega-menu-box' : 'mega-menu-box';
            item.appendChild(megaBox);

            item.addEventListener('mouseenter', () => {
                if (window.innerWidth > 992) {
                    ST_PRO_LOAD_MEGA(label, megaBox);
                }
            });
        });
    }

    function initHamburgerEngine() {
        const menuBtn = document.getElementById('seoturbo-menuHamburgerBtn'), 
              closeBtn = document.getElementById('seoturbo-closeMenuBtn'), 
              overlay = document.getElementById('seoturbo-hamburgerOverlay'), 
              menu = document.getElementById('seoturbo-hamburgerMenu'), 
              searchBtn = document.getElementById('seoturbo-searchHamburgerBtn'), 
              container = document.getElementById('seoturbo-hamburgerMenuContent'), 
              mainBar = document.getElementById('seoturbo-hamburgerContainer');
        if (!menuBtn || !menu || !container) return;
        window.addEventListener('scroll', () => { if(mainBar) mainBar.classList.toggle('is-sticky', window.scrollY > 150); }, { passive: true });
        const toggleMenu = (show) => {
            menu.classList.toggle('active', show);
            if (overlay) overlay.classList.toggle('active', show);
            document.body.style.overflow = show ? 'hidden' : '';
        };
        menuBtn.onclick = () => toggleMenu(true);
        if(closeBtn) closeBtn.onclick = () => toggleMenu(false);
        if(overlay) overlay.onclick = () => toggleMenu(false);
        if(searchBtn) searchBtn.onclick = () => { toggleMenu(false); const mainSearch = document.getElementById('seoturbo-search'); if(mainSearch) mainSearch.click(); };
        buildSmartMenu(container);
    }

    function buildSmartMenu(container) {
        let html = '';
        const socials = document.querySelectorAll('.seoturbo-topbar-social-icons a');
        if (socials.length > 0) {
            html += `<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:20px;padding-bottom:20px;border-bottom:1px solid rgba(0,0,0,0.05);">`;
            socials.forEach(s => { html += `<a href="${s.href}" target="_blank" class="social-circle" aria-label="${s.title || 'تابعنا'}">${s.innerHTML}</a>`; });
            html += `</div>`;
        }
        const sourceMenu = document.getElementById('main-menu');
        if (sourceMenu) {
            html += '<div class="seoturbo-hamburger-section-title"><svg width="14" height="14" viewBox="0 0 512 512" style="fill: currentColor;"><use href="#icon-list"/></svg> الأقسام</div>';
            Array.from(sourceMenu.children).filter(el => el.tagName === 'LI').forEach(li => {
                const parentLink = li.querySelector('a');
                if (!parentLink) return;
                let iconHtml = parentLink.querySelector('svg, i') ? parentLink.querySelector('svg, i').outerHTML : '<svg width="12" height="12" viewBox="0 0 320 512" style="fill: currentColor;"><use href="#icon-chevron-left"/></svg>';
                if (li.classList.contains('has-sub')) {
                    const subMenuUl = li.querySelector('ul.sub-menu');
                    if (subMenuUl) {
                        html += `<div class="seoturbo-hamburger-parent"><div class="seoturbo-hamburger-parent-title" data-trigger="drop"><span>${iconHtml} ${parentLink.textContent.trim()}</span><span class="arrow">▼</span></div><div class="seoturbo-hamburger-submenu">`;
                        subMenuUl.querySelectorAll('li > a').forEach(subA => {
                            let subIconHtml = subA.querySelector('svg, i') ? subA.querySelector('svg, i').outerHTML : '<svg width="8" height="8" viewBox="0 0 448 512" style="fill: currentColor;"><use href="#icon-minus"/></svg>';
                            html += `<a class="seoturbo-hamburger-link" href="${subA.getAttribute('href')}">${subIconHtml} ${subA.textContent.trim()}</a>`;
                        });
                        html += `</div></div>`;
                    }
                } else { html += `<a class="seoturbo-hamburger-link" href="${parentLink.getAttribute('href')}">${iconHtml} ${parentLink.textContent.trim()}</a>`; }
            });
        }
        const staticLinks = document.querySelectorAll('.seoturbo-compact-nav a:not([onclick])');
        if (staticLinks.length > 0) {
            html += '<div class="seoturbo-hamburger-section" style="margin-top:20px;"><div class="seoturbo-hamburger-section-title"><svg width="14" height="14" viewBox="0 0 576 512" style="fill: currentColor;"><use href="#icon-file-alt"/></svg> تعرف علينا</div>';
            staticLinks.forEach(page => { 
                let pageIconHtml = page.querySelector('svg, i') ? page.querySelector('svg, i').outerHTML : '<svg width="12" height="12" viewBox="0 0 576 512" style="fill: currentColor;"><use href="#icon-file-alt"/></svg>';
                html += `<a class="seoturbo-hamburger-link" href="${page.getAttribute('href')}">${pageIconHtml} ${page.textContent.trim()}</a>`; 
            });
            html += '</div>';
        }
        container.innerHTML = html;
        container.querySelectorAll('[data-trigger="drop"]').forEach(btn => {
            btn.onclick = (e) => {
                e.preventDefault();
                const submenu = btn.nextElementSibling, isOpen = btn.classList.contains('is-open');
                if (!isOpen) { btn.classList.add('is-open'); submenu.style.display = 'flex'; submenu.classList.add('is-open'); } 
                else { btn.classList.remove('is-open'); submenu.style.display = 'none'; submenu.classList.remove('is-open'); }
            };
        });
    }

    if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', initDynamicDropdowns); } 
    else { initDynamicDropdowns(); }
})();

/* === SEOTurbo Module 09: 09-هيكل-هامبورجر-مزامنة-الشعار-الإدارة.js === */

(function() {
    'use strict';
    function performMasterSync() {
        const vault = document.getElementById('homepage-identity-vault');
        let logoUrl = null;
        let faviconUrl = null;
        let siteName = null;
        if (vault) {
            logoUrl = vault.getAttribute('data-logo');
            faviconUrl = vault.getAttribute('data-favicon');
            siteName = vault.getAttribute('data-name');
        }
        if (!logoUrl) {
            const headerLogo = document.querySelector('#Header1_headerimg, .header-widget img, .seoturbo-site-logo img');
            logoUrl = headerLogo ? headerLogo.src : null;
        }
        if (!faviconUrl) {
            const faviconLink = document.querySelector('link[rel="icon"][href], link[rel="shortcut icon"][href]');
            faviconUrl = faviconLink ? faviconLink.href : null;
        }
        const sourceCard = document.querySelector('.management-card.desktop-version');
        let managementData = null;
        if (sourceCard) {
            const imgs = sourceCard.querySelectorAll('.management-frame img');
            const names = sourceCard.querySelectorAll('.management-name');            
            const roles = sourceCard.querySelectorAll('.management-role span');
            if (imgs.length >= 2 && names.length >= 2 && roles.length >= 2) {
                managementData = {
                    images: [imgs[0].src, imgs[1].src],
                    names: [names[0].textContent.trim(), names[1].textContent.trim()],
                    roles: [roles[0].textContent.trim(), roles[1].textContent.trim()]
                };
            }
        }
        requestAnimationFrame(() => {
            if (logoUrl) {
                const logoTargets = document.querySelectorAll('.seoturbo-hamburger-header-logo img, .seoturbo-sticky-logo-img, .seoturbo-side-nav-logo img, #seoturbo-sticky-logo, .mega-logo');
                logoTargets.forEach(img => {
                    if (img && img.src !== logoUrl) {
                        img.src = logoUrl;
                    }
                });
            }
            if (faviconUrl) {
                const favTarget = document.getElementById('mobile-favicon-target');
                if (favTarget && favTarget.src !== faviconUrl) {
                    favTarget.src = faviconUrl;
                }
                const notifIcons = document.querySelectorAll('.seoturbo-notif-icon, .notif-icon');
                notifIcons.forEach(icon => {
                    if (icon.src && icon.src !== faviconUrl) {
                        icon.src = faviconUrl;
                    }
                });
            }
            if (siteName) {
                const nameTargets = document.querySelectorAll('.seoturbo-side-nav-site-name, .seoturbo-mobile-site-name, .mega-site-info .mega-welcome span');
                nameTargets.forEach(el => {
                    if (el && el.textContent !== siteName) {
                        el.textContent = siteName;
                    }
                });
            }
            if (managementData) {
                const targetCards = document.querySelectorAll('.seoturbo-full-vertical-card');
                targetCards.forEach(card => {
                    const tImgs = card.querySelectorAll('.v-full-img img');
                    const tNames = card.querySelectorAll('.v-full-name');
                    const tRoles = card.querySelectorAll('.v-full-role'); 
                    managementData.images.forEach((src, i) => {
                        if (tImgs[i] && tImgs[i].src !== src) {
                            tImgs[i].src = src;
                        }
                    });
                    managementData.names.forEach((name, i) => {
                        if (tNames[i] && tNames[i].textContent !== name) {
                            tNames[i].textContent = name;
                        }
                    });
                    managementData.roles.forEach((role, i) => {
                        if (tRoles[i]) {
                            const icon = tRoles[i].querySelector('svg');
                            if (icon) {
                                tRoles[i].innerHTML = icon.outerHTML + ' ' + role;
                            } else {
                                tRoles[i].textContent = role;
                            }
                        }
                    });
                });
            }
        });
    }
    if ('requestIdleCallback' in window) {
        requestIdleCallback(() => {
            setTimeout(performMasterSync, 400);
            setTimeout(performMasterSync, 3000);
        });
    } else {
        window.addEventListener('load', () => {
            setTimeout(performMasterSync, 1000);
        });
    }
    window.addEventListener('seoturboDarkModeChange', () => {
        setTimeout(performMasterSync, 100);
    });
})();

/* === SEOTurbo Module 10: 10-صفحة-رئيسية-شريط-الموضوعات.js === */

(function(){
    'use strict';

    var freeContainer = document.getElementById('seoturbo-breaking-placeholder');
    var originalContainer = document.getElementById('breaking-bar-original');

    if (freeContainer) freeContainer.style.display = 'none';
    if (originalContainer) originalContainer.style.display = 'block';

    var months = ["يناير", "فبراير", "مارس", "إبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];

    var vault = document.getElementById('homepage-identity-vault');
    var blogName = (vault && vault.getAttribute('data-name')) ? vault.getAttribute('data-name') : "";

    function getArDate(dStr) {
        var d = new Date(dStr);
        return d.getUTCDate() + ' ' + months[d.getUTCMonth()] + ' ' + d.getUTCFullYear();
    }

    function generateTooltipText(title, category, date) {
        var cleanCategory = category.replace(/<[^>]*>/g, '').trim();
        return '📰 ' + title + '\n📁 القسم: ' + cleanCategory + '\n📅 النشر: ' + date;
    }

    function getMappedCategory(label) {
        var cleanLabel = decodeURIComponent(label).toLowerCase().trim();
        if (window.seoturbo_label_dictionary && window.seoturbo_label_dictionary[cleanLabel]) {
            return window.seoturbo_label_dictionary[cleanLabel];
        }
        var menuLinks = document.querySelectorAll('#main-menu a[href*="/search/label/"], .sub-menu a[href*="/search/label/"]');
        for (var i = 0; i < menuLinks.length; i++) {
            var href = decodeURIComponent(menuLinks[i].getAttribute('href'));
            var slugInMenu = href.substring(href.lastIndexOf('/') + 1).split('?')[0].toLowerCase().trim();
            if (slugInMenu === cleanLabel) {
                return menuLinks[i].textContent.trim().replace(/^_/, '');
            }
        }
        return label;
    }

    function initBreakingBar() {
        var barArea = document.getElementById('single_seoterbobar_area'); 
        if (!barArea) return;

        if (window.ST_MASTER_PROMISE) {
            window.ST_MASTER_PROMISE.then(function(d) {
                if (!d || !d.feed.entry) return;
                var entries = d.feed.entry.slice(9, 19);
                var seoterboHtml = entries.map(function(e) {
                    var t = e.title.$t;
                    var link = e.link.find(function(l){return l.rel === 'alternate'}).href;
                    var rawCat = (e.category && e.category.length > 0) ? e.category[0].term : 'موضوعات';
                    var mappedCat = getMappedCategory(rawCat);
                    var dateStr = getArDate(e.published.$t);
                    var tooltipText = generateTooltipText(t, mappedCat, dateStr);

                    return '<a class="single-seoterbobar-item" href="' + link + '" style="cursor: pointer;" title="' + tooltipText + '">' +
                           '<span class="single-seoterbobar-source" style="cursor: pointer;" title="' + mappedCat + '">من موضوعاتنا</span> ' + t + '</a>';
                }).join('');
                barArea.innerHTML = seoterboHtml;
            });
        }
    }

    setTimeout(initBreakingBar, 3000);
})();

/* === SEOTurbo Module 12: 12-صفحة-رئيسية-سلايدر-نبض-الصدارة.js === */

(function(){
    'use strict';
    var months = ["يناير", "فبراير", "مارس", "إبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
    var defaultAuthorImg = 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiayFqZQb-C_QKZf9LtsQLGCL2V_DucX9ex335dtsQ8ISn7jC3XFwWaXB2gHRqTF7Ng_48_TiUTgbLkXlMfhbHa3wGwvjPfB5YCKI2AqYue1cwIWtvPZNeCrqRl-ufBpqoGe2N5Dr13SOQ46-U__Xmb6C4keVLoNqSiUEMojk3MFVnQhOkA1yfnByshdRQB/w159-h200-rw/user.webp';
    var allEntries = [];
    var shownCount = 0;
    function getArDate(dStr) {
        var d = new Date(dStr);
        if (isNaN(d)) return '';
        return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear();
    }
    function cleanHtmlFast(html) {
        if (!html) return '';
        return html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    }
    function extractFirstRealParagraph(content, isFeatured) {
        if (!content) return '';
        var text = cleanHtmlFast(content);
        var sentences = text.split(/[.!?؟!]\s+/);
        var maxLength = isFeatured ? 500 : 250;
        for (var i = 0; i < sentences.length; i++) {
            var sentence = sentences[i].trim();
            if (sentence.length > 35) {
                if (sentence.length > maxLength) {
                    sentence = sentence.substring(0, maxLength);
                }
                return sentence + '...';
            }
        }
        if (text.length > 35) {
            var result = text.substring(0, maxLength);
            return result + '...';
        }
        return '';
    }
    function cleanText(html) {
        if (!html) return '';
        var tempDiv = document.createElement('div');
        tempDiv.innerHTML = html.replace(/^_/, '').trim();
        tempDiv.querySelectorAll('i, svg, img, span').forEach(function(el) { el.remove(); });
        return tempDiv.textContent.replace(/\s+/g, ' ').trim();
    }
    function getMappedCategory(label) {
        var cleanLabel = decodeURIComponent(label).toLowerCase().trim();
        if (window.seoturbo_label_dictionary && window.seoturbo_label_dictionary[cleanLabel]) {
            return window.seoturbo_label_dictionary[cleanLabel];
        }
        var menuLinks = document.querySelectorAll('#main-menu a[href*="/search/label/"]');
        for (var i = 0; i < menuLinks.length; i++) {
            var href = decodeURIComponent(menuLinks[i].getAttribute('href'));
            var slugInMenu = href.substring(href.lastIndexOf('/') + 1).split('?')[0].toLowerCase().trim();
            if (slugInMenu === cleanLabel) {
                return cleanText(menuLinks[i].innerHTML);
            }
        }
        return label;
    }
    function getAuthorImageFromPost(entry) {
        if (entry.author && entry.author[0] && entry.author[0].gd$image && entry.author[0].gd$image.src) {
            return entry.author[0].gd$image.src.replace(/\/(s\d+|w\d+-h\d+|w\d+)(-[^/]*)*\//, '/s30-c/');
        }
        return null;
    }
    function formatLCPImage(url, isFeatured) {
        if (!url) return '';

        if (url.includes('img.youtube.com') || url.includes('ytimg.com')) {
            return url.replace('default.jpg', isFeatured ? 'maxresdefault.jpg' : 'hqdefault.jpg');
        }
        var imgSize = isFeatured ? 'w800-h450-c' : 'w600-h338-c';

        if (url.includes('=')) {
            return url.split('=')[0] + '=' + (isFeatured ? 'w800-h450-c' : 'w600-h338-c');
        }
        return url.replace(/\/s\d+(-[^\/]*)?\//, '/' + imgSize + '/');
    }
    function populateArticleData(article, e, i) {
        if (!article) return;
        var title = e.title.$t;
        var link = e.link.find(function(u){return u.rel==='alternate'}).href;
        var img = e.media$thumbnail ? formatLCPImage(e.media$thumbnail.url, i === 0) : '';
        if (i === 0 && window.ST_LCP_IMG) {
            img = window.ST_LCP_IMG.indexOf('-rw') === -1 ? window.ST_LCP_IMG.replace(/(w\d+-h\d+-p-k-no-nu)([/])/, '$1-rw/') : window.ST_LCP_IMG;
        }
        var rawCat = (e.category && e.category.length > 0) ? e.category[0].term : 'موضوعات';
        var mappedCat = getMappedCategory(rawCat);
        var dateStr = getArDate(e.published.$t);
        var snippet = '';
        if (e.summary && e.summary.$t) {
            snippet = extractFirstRealParagraph(e.summary.$t, i === 0);
        }
        var postId = e.id.$t.split('post-')[1] || i;
        var cleanTitle = title.replace(/"/g, '&quot;');
        var cleanImg = img.replace(/"/g, '&quot;');
        var cleanSnippet = snippet ? snippet.replace(/"/g, '&quot;') : '';
        var authorName = (e.author && e.author[0] && e.author[0].name && e.author[0].name.$t) ? e.author[0].name.$t : 'تحرير';
        var authorImg = getAuthorImageFromPost(e);
        if (!authorImg) authorImg = defaultAuthorImg;
        var thumbLink = article.querySelector('.seoturbo-main-tool-thumb a') || article.querySelector('.thumb');
        if (thumbLink) thumbLink.href = link;
        var catSpan = article.querySelector('.postcat');
        if (catSpan) catSpan.textContent = mappedCat;
        var thumbImg = article.querySelector('.seoturbo-main-tool-thumb img') || article.querySelector('.thumb img');
        if (thumbImg) {
            thumbImg.src = img;
            thumbImg.alt = title;
            if (i === 0) {
                thumbImg.setAttribute('fetchpriority', 'high');
                thumbImg.setAttribute('loading', 'eager');
                thumbImg.setAttribute('decoding', 'sync');
            } else {
                thumbImg.setAttribute('loading', 'lazy');
                thumbImg.setAttribute('decoding', 'async');
            }
        }
        var titleLink = article.querySelector('.seoturbo-main-tool-title-card a') || article.querySelector('.rnav-title a');
        if (titleLink) {
            titleLink.href = link;
            titleLink.textContent = title;
        }
        var snippetDiv = article.querySelector('.leadership-snippet');
        if (snippetDiv) snippetDiv.textContent = cleanSnippet || '';
        var authorImgSmall = article.querySelector('.author-img-small');
        if (authorImgSmall) {
            authorImgSmall.src = authorImg;
            authorImgSmall.alt = authorName;
        }
        var authorNameSpan = article.querySelector('.name') || article.querySelector('.author-name-small');
        if (authorNameSpan) authorNameSpan.textContent = authorName;
        var dateBadge = article.querySelector('.post-date-badge');
        if (dateBadge) dateBadge.innerHTML = '📅 ' + dateStr;
        var readMore = article.querySelector('.seoturbo-main-tool-read-more') || article.querySelector('.read-more-btn');
        if (readMore) readMore.href = link;
        var favBtn = article.querySelector('.seoturbo-post-add-fav');
        if (favBtn) {
            favBtn.setAttribute('data-id', postId);
            favBtn.setAttribute('data-title', cleanTitle);
            favBtn.setAttribute('data-url', link);
            favBtn.setAttribute('data-img', cleanImg);
        }
    }
    function generateDynamicPostHTML(e, i) {
        var title = e.title.$t;
        var link = e.link.find(function(u){return u.rel==='alternate'}).href;
        var img = e.media$thumbnail ? formatLCPImage(e.media$thumbnail.url, false) : '';
        var rawCat = (e.category && e.category.length > 0) ? e.category[0].term : 'موضوعات';
        var mappedCat = getMappedCategory(rawCat);
        var dateStr = getArDate(e.published.$t);
        var snippet = '';
        if (e.summary && e.summary.$t) {
            snippet = extractFirstRealParagraph(e.summary.$t, false);
        }
        var postId = e.id.$t.split('post-')[1] || i;
        var cleanTitle = title.replace(/"/g, '&quot;');
        var cleanImg = img.replace(/"/g, '&quot;');
        var cleanSnippet = snippet ? snippet.replace(/"/g, '&quot;') : '';
        var authorName = (e.author && e.author[0] && e.author[0].name && e.author[0].name.$t) ? e.author[0].name.$t : 'تحرير';
        var authorImg = getAuthorImageFromPost(e);
        if (!authorImg) authorImg = defaultAuthorImg;
        var catClass = 'catnum' + (i % 5);
        return `
        <article class="posts postnum${i}">
            <a class="thumb" href="${link}">
                <span class="postcat ${catClass}">${mappedCat}</span>
                <img alt="${cleanTitle}" class="post-thumb" height="158" loading="lazy" decoding="async" src="${img}" width="280"/>
                <div class="seoturbo-fav-btn seoturbo-post-add-fav" data-id="${postId}" data-title="${cleanTitle}" data-url="${link}" data-img="${cleanImg}">
                    <svg><use href="#icon-fav-empty"/></svg>
                    <span class="seoturbo-fav-text">حفظ</span>
                </div>
            </a>
            <div class="cont">
                <h3 class="rnav-title"><a href="${link}">${title}</a></h3>
                <div class="leadership-snippet">${cleanSnippet}</div>
                <div class="post-meta-bar">
                    <div class="author-info-wrap">
                        <img alt="${authorName}" class="author-img-small" height="20" loading="lazy" src="${authorImg}" width="20"/>
                        <span class="author-name-small">${authorName}</span>
                    </div>
                    <div class="post-date-badge">📅 ${dateStr}</div>
                </div>
            </div>
        </article>`;
    }
    function loadMoreProcess() {
        var slider = document.getElementById('seoturbo-leadership-slider');
        if (!slider || allEntries.length === 0) return;
        if (shownCount === 0) {
            var limit = Math.min(9, allEntries.length);
            for (var i = 0; i < limit; i++) {
                var article = slider.querySelector('.posts.postnum' + i);
                if (article) {
                    populateArticleData(article, allEntries[i], i);
                }
            }
            shownCount = limit;
        }
    }
    var sliderInterval = null;
    var sliderIdx = 1;
    function rotateFeatured() {}
    function startSliderRotation() {}
    function initLeadershipSlider() {
        if (window.ST_MASTER_PROMISE) {
            window.ST_MASTER_PROMISE.then(function(d) {
                if (!d || !d.feed || !d.feed.entry) return;
                allEntries = d.feed.entry; 
                shownCount = 0;
                loadMoreProcess();
                setTimeout(startSliderRotation, 2000);
            });
        }
    }
    initLeadershipSlider();
})();

/* === SEOTurbo Module 13: 13-صفحة-رئيسية-سلايدر-الأقسام-أرشيف-الريادة.js === */

(function(){
    'use strict';
    var freeContainer = document.getElementById('seoturbo-sections-placeholder');
    var originalContainer = document.getElementById('sections-grid-original');
    if (freeContainer) freeContainer.style.display = 'none';
    if (originalContainer) originalContainer.style.display = 'block';
    var months = ["يناير", "فبراير", "مارس", "إبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
    var vault = document.getElementById('homepage-identity-vault');
    var blogName = (vault && vault.getAttribute('data-name')) ? vault.getAttribute('data-name') : "";
    function getArDate(dStr) {
        var d = new Date(dStr);
        return d.getUTCDate() + ' ' + months[d.getUTCMonth()] + ' ' + d.getUTCFullYear();
    }
    function generateTooltipText(title, category, date) {
        var cleanCategory = category.replace(/<[^>]*>/g, '').trim();
        return '📰 ' + title + '\n📁 القسم: ' + cleanCategory + '\n📅 النشر: ' + date;
    }
    function cleanText(html) {
        if (!html) return '';
        return html.replace(/^_+/, '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
    }
    var cachedMenuLinks = null;
    function getMenuLinks() {
        if (!cachedMenuLinks) cachedMenuLinks = Array.from(document.querySelectorAll('#main-menu a[href*="/search/label/"], .sub-menu a[href*="/search/label/"]'));
        return cachedMenuLinks;
    }
    function getMappedCategory(label) {
        var cleanLabel = decodeURIComponent(label).toLowerCase().trim();
        if (window.seoturbo_label_dictionary && window.seoturbo_label_dictionary[cleanLabel]) {
            return window.seoturbo_label_dictionary[cleanLabel];
        }
        var menuLinks = getMenuLinks();
        for (var i = 0; i < menuLinks.length; i++) {
            var href = decodeURIComponent(menuLinks[i].getAttribute('href'));
            var slugInMenu = href.substring(href.lastIndexOf('/') + 1).split('?')[0].toLowerCase().trim();
            if (slugInMenu === cleanLabel) {
                return cleanText(menuLinks[i].innerHTML);
            }
        }
        return label;
    }
    function optimizeSectionImage(url) {
        if (!url) return '';
        if (url.includes('img.youtube.com') || url.includes('ytimg.com')) {
            return url.replace('default.jpg', 'hqdefault.jpg');
        }
        if (url.includes('=')) {
            return url.split('=')[0] + '=w150-h150-c';
        }
        return url.replace(/\/s\d+(-[^\/]*)?\//, '/w150-h150-c/');
    }
    function initSectionsGrid() {
        var secGrid = document.getElementById('sections-grid-container');
        if (!secGrid) return;
        var menuLinks = getMenuLinks();
        var blogSecs = [];
        var seenLabels = {};
        menuLinks.forEach(l => {
            var linkText = l.textContent.trim();
            if (linkText.indexOf('تحميل') !== -1) return;
            var labelPart = l.getAttribute('href').split('/search/label/')[1];
            if (labelPart) {
                var label = decodeURIComponent(labelPart.split(/[?#]/)[0]);
                if (!seenLabels[label]) {
                    seenLabels[label] = true;
                    blogSecs.push({ label: label, name: l.innerHTML, cleanName: cleanText(l.innerHTML) });
                }
            }
        });
        if (blogSecs.length === 0) return;
        var colors = ['#b71c1c', '#0d47a1', '#1a252f', '#1b5e20', '#6a1b9a', '#006064', '#4a148c', '#004d40', '#bf360c', '#3e2723', '#263238', '#880e4f'];
        var skeletonItem = '<div class="section-post-item"><div class="section-post-thumb" style="background:var(--border-color);"></div><div class="section-post-info"><div style="height:14px;background:var(--border-color);width:80%;margin-bottom:8px"></div><div style="height:10px;background:var(--border-color);width:40%"></div></div></div>';
        blogSecs.forEach((s, j) => {
            var card = document.createElement('div');
            card.className = 'section-card';
            card.setAttribute('data-label', s.label);
            card.id = 'sec-card-' + j;
            card.style.cursor = "pointer";
            var sectionTooltip = '📂 قسم ' + s.cleanName + '\n📊 أحدث المقالات المنشورة في هذا القسم\n🔍 اضغط للمزيد';
            card.innerHTML = '<h2 class="section-header" style="background: ' + colors[j % colors.length] + '; cursor: pointer;" title="' + sectionTooltip + '">' + s.name + '</h2>' +
                '<div class="section-posts-list" id="sec-posts-' + j + '" style="cursor: pointer;">' + skeletonItem + skeletonItem + skeletonItem + '</div>' +
                '<div class="section-footer" style="cursor: pointer;">' +
                '<a href="/search/label/' + encodeURIComponent(s.label) + '" style="cursor: pointer;" title="استكشاف المزيد من مقالات قسم ' + s.cleanName + '">المزيد من هذا القسم</a></div>';
            secGrid.appendChild(card);
        });
        var secObserver = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    var card = entry.target;
                    fetchSectionData(card.getAttribute('data-label'), card.id.replace('sec-card-', ''));
                    observer.unobserve(card);
                }
            });
        }, { rootMargin: '400px' });
        document.querySelectorAll('.section-card').forEach(card => secObserver.observe(card));
    }
    function fetchSectionData(label, index) {
        fetch('/feeds/posts/summary/-/' + encodeURIComponent(label) + '?alt=json&max-results=3')
        .then(res => res.json())
        .then(data => {
            var listContainer = document.getElementById('sec-posts-' + index);
            if (data.feed.entry) {
                var html = '';
                data.feed.entry.forEach(e => {
                    var title = e.title.$t;
                    var link = e.link.find(u => u.rel === 'alternate').href;
                    var img = optimizeSectionImage(e.media$thumbnail ? e.media$thumbnail.url : '');
                    var dateStr = getArDate(e.published.$t);
                    var rawCategory = (e.category && e.category.length > 0) ? e.category[0].term : label;
                    var mappedCategory = getMappedCategory(rawCategory);
                    var tooltipText = generateTooltipText(title, mappedCategory, dateStr);
                    html += '<div class="section-post-item" style="cursor: pointer;" title="' + tooltipText + '">' +
                            '<a class="section-post-thumb" href="' + link + '" style="cursor: pointer;" title="' + tooltipText + '">' +
                                '<img src="' + img + '" alt="' + title + '" loading="lazy" style="cursor: pointer;" title="' + tooltipText + '">' +
                            '</a>' +
                            '<div class="section-post-info" style="cursor: pointer;">' +
                                '<h3 class="section-post-title" style="cursor: pointer;">' +
                                    '<a href="' + link + '" style="cursor: pointer;" title="' + tooltipText + '">' + title + '</a>' +
                                '</h3>' +
                                '<div class="section-post-date" style="cursor: pointer;" title="' + tooltipText + '">' +
                                    '<svg width="10" height="10" viewBox="0 0 512 512" style="fill: currentColor;"><use href="#icon-clock"/></svg> ' + dateStr +
                                '</div>' +
                            '</div>' +
                        '</div>';
                });
                listContainer.innerHTML = html;
            }
        });
    }
    setTimeout(initSectionsGrid, 1500);
})();

/* === SEOTurbo Module 14: 14-صفحة-رئيسية-سلايدر-المستجدات-والحصريات.js === */

(function() {
    'use strict';
    const gridContainer = document.getElementById('seoturbo-main-tool-grid');
    if (!gridContainer) return;
    let allPosts = [];
    const months = ['يناير', 'فبراير', 'مارس', 'إبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
    function cleanHtmlFast(html) {
        if (!html) return '';
        return html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    }
    function formatDate(dateStr) {
        const d = new Date(dateStr);
        if (isNaN(d)) return '';
        return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear();
    }
    function getSiteLogo() {
        const headerImg = document.querySelector('#Header1_headerimg, .header-widget img, .seoturbo-site-logo img');
        if (headerImg && headerImg.src) return headerImg.src;
        const favicon = document.querySelector('link[rel="icon"], link[rel="shortcut icon"]');
        if (favicon && favicon.href) return favicon.href;
        return 'https://www.blogger.com/favicon.ico';
    }
    const defaultAuthorImg = 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiayFqZQb-C_QKZf9LtsQLGCL2V_DucX9ex335dtsQ8ISn7jC3XFwWaXB2gHRqTF7Ng_48_TiUTgbLkXlMfhbHa3wGwvjPfB5YCKI2AqYue1cwIWtvPZNeCrqRl-ufBpqoGe2N5Dr13SOQ46-U__Xmb6C4keVLoNqSiUEMojk3MFVnQhOkA1yfnByshdRQB/w159-h200-rw/user.webp';

    function translateCategory(category) {
        if (!category) return 'موضوعات';
        if (window.seoturbo_label_dictionary && window.seoturbo_label_dictionary[category.toLowerCase()]) {
            return window.seoturbo_label_dictionary[category.toLowerCase()];
        }
        return category;
    }
    function getCategoryIcon(categoryName) {
        const menuLinks = document.querySelectorAll('#main-menu a[href*="/search/label/"], .sub-menu a[href*="/search/label/"]');
        for (const link of menuLinks) {
            const href = decodeURIComponent(link.getAttribute('href'));
            const slug = href.split('/search/label/')[1]?.split(/[?#]/)[0];
            if (slug && slug.toLowerCase() === categoryName.toLowerCase()) {
                const icon = link.querySelector('svg, i');
                if (icon) return icon.cloneNode(true).outerHTML;
            }
        }
        return '<svg width="12" height="12" viewBox="0 0 576 512" style="fill:currentColor;"><use href="#icon-folder-open"/></svg>';
    }
    function getCategoryColorIndex(categoryName) {
        const menuLinks = document.querySelectorAll('#main-menu a[href*="/search/label/"], .sub-menu a[href*="/search/label/"]');
        let index = 0;
        for (const link of menuLinks) {
            const href = decodeURIComponent(link.getAttribute('href'));
            const slug = href.split('/search/label/')[1]?.split(/[?#]/)[0];
            if (slug && slug.toLowerCase() === categoryName.toLowerCase()) return index % 16;
            index++;
        }
        return categoryName.length % 16;
    }
    function getAuthorImage(post) {
        if (post.author?.[0]?.gd$image?.src) {
            return post.author[0].gd$image.src.replace(/\/(s\d+|w\d+-h\d+|w\d+)(-[^/]*)*\//, '/s40-c/');
        }
        return null;
    }
    function seoturboOptimizeImage(url) {
        if (!url) return '';
        if (url.includes('img.youtube.com') || url.includes('ytimg.com')) {
            return url.replace('default.jpg', 'hqdefault.jpg');
        }
        if (url.includes('=')) {
            return url.split('=')[0] + '=w500-h281-c';
        }
        return url.replace(/\/s\d+(-[^\/]*)?\//, '/w500-h281-c-rw-l30/');
    }
    function processPostFromCache(entry) {
        if (!entry) return null;
        const title = entry.title?.$t || 'بدون عنوان';
        const link = entry.link?.find(l => l.rel === 'alternate')?.href || '#';
        let img = entry.media$thumbnail?.url;
        const fallbackImg = getSiteLogo();
        const authorName = entry.author?.[0]?.name?.$t || 'تحرير';
        const dateFormatted = formatDate(entry.published?.$t);
        let authorImg = getAuthorImage(entry);
        if (!authorImg) authorImg = defaultAuthorImg;
        const category = entry.category?.[0]?.term || 'موضوعات';
        const translatedCat = translateCategory(category);
        const categoryIcon = getCategoryIcon(category);
        const colorIndex = getCategoryColorIndex(category);
        const catColorClass = 'seoturbo-catnum' + (colorIndex % 16);
        let snippet = '';
        if (entry.summary?.$t) {
            snippet = cleanHtmlFast(entry.summary.$t);
            if (snippet.length > 250) snippet = snippet.substring(0, 250) + '...';
        }
        if (!snippet && title) {
            snippet = title.length > 100 ? title.substring(0, 100) + '...' : title;
        }
        if (!snippet) snippet = 'اضغط لقراءة المزيد من التفاصيل...';
        return {
            id: entry.id?.$t?.split('post-')[1] || link,
            title, link, snippet,
            img: img ? seoturboOptimizeImage(img) : fallbackImg,
            authorName, authorImg, dateFormatted, category, translatedCat, categoryIcon, catColorClass
        };
    }
    function shuffleArray(array) {
        let currentIndex = array.length, randomIndex;
        while (currentIndex !== 0) {
            randomIndex = Math.floor(Math.random() * currentIndex);
            currentIndex--;
            [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
        }
        return array;
    }
    function renderCard(post, isFirstPost) {
        const imgLoadingAttr = isFirstPost ? 'fetchpriority="high" loading="eager" decoding="sync"' : 'loading="lazy" decoding="async"';
        const postId = post.id || ('post_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6));
        const escTitle = post.title.replace(/"/g, '&quot;').replace(/</g, '&lt;');
        const escSnippet = post.snippet ? post.snippet.replace(/</g, '&lt;').replace(/>/g, '&gt;') : '';
        const escAuthor = post.authorName.replace(/</g, '&lt;');
        const escCat = post.translatedCat.replace(/</g, '&lt;');
        return `
            <div class="seoturbo-main-tool-card" data-post-id="${postId}">
                <div class="seoturbo-main-tool-thumb">
                    <a href="${post.link}" title="${escTitle}">
                        <img src="${post.img}" alt="${escTitle}" width="340" height="191" ${imgLoadingAttr} onerror="this.src='${getSiteLogo()}'">
                    </a>
                    <span class="seoturbo-main-tool-badge ${post.catColorClass}">
                        ${post.categoryIcon} ${escCat}
                    </span>
                </div>
                <div class="seoturbo-main-tool-content">
                    <h3 class="seoturbo-main-tool-title-card">
                        <a href="${post.link}" title="${escTitle}">${escTitle}</a>
                    </h3>
                    ${post.snippet ? `<p class="seoturbo-main-tool-snippet">${escSnippet}</p>` : ''}
                    <div class="seoturbo-main-tool-footer">
                        <div class="seoturbo-main-tool-author-meta">
                            <img src="${post.authorImg}" alt="${escAuthor}" width="36" height="36" loading="lazy" onerror="this.src='${defaultAuthorImg}'">
                            <div class="seoturbo-main-tool-author-info">
                                <span class="name">${escAuthor}</span>
                                <span>📅 ${post.dateFormatted}</span>
                            </div>
                        </div>
                        <div class="seoturbo-main-tool-post-actions">
                            <a href="${post.link}" class="seoturbo-main-tool-read-more" title="${escTitle}">قراءة المزيد</a>
                            <div class="seoturbo-main-tool-fav-btn seoturbo-post-add-fav" data-id="${postId}" data-title="${escTitle}" data-url="${post.link}" data-img="${post.img}">
                                <svg width="44" height="44" viewBox="0 0 24 24"><use href="#icon-fav-empty"/></svg>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `;
    }
    function renderGrid() {
        if (!allPosts.length) {
            gridContainer.innerHTML = '<div class="seoturbo-main-tool-skeleton">⚠️ لا توجد مقالات</div>';
            return;
        }
        let html = '';
        allPosts.forEach((post, idx) => {
            html += renderCard(post, false);
        });
        gridContainer.innerHTML = html;
    }
    async function init() {
        if (!window.ST_MASTER_PROMISE) {
            gridContainer.innerHTML = '<div class="seoturbo-main-tool-skeleton">⚠️ النظام غير جاهز</div>';
            return;
        }
        try {
            const data = await window.ST_MASTER_PROMISE;
            if (data?.feed?.entry?.length) {
                const remainingEntries = data.feed.entry.slice(9);
                const shuffledEntries = shuffleArray(remainingEntries);
                allPosts = shuffledEntries.slice(0, 8).map(processPostFromCache).filter(Boolean);
                renderGrid();
            } else {
                gridContainer.innerHTML = '<div class="seoturbo-main-tool-skeleton">⚠️ لا توجد مقالات</div>';
            }
        } catch(e) {
            console.warn('SEOTurbo Main Tool Error:', e);
            gridContainer.innerHTML = '<div class="seoturbo-main-tool-skeleton">⚠️ حدث خطأ في تحميل البيانات</div>';
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/* === SEOTurbo Module 14: 14.5-نظام-إحصائيات-البطاقات-المؤشر-والمشاركة === */

(function() {
    'use strict';
    function injectStatsBars() {
        var cards = document.querySelectorAll('#seoturbo-leadership-slider article.posts, .Posts-byCategory article.posts, .seoturbo-main-tool-card');
        cards.forEach(function(card) {
            if (card.querySelector('.seoturbo-slider-stats-bar, .seoturbo-main-tool-stats')) return;
            var isMainTool = card.classList.contains('seoturbo-main-tool-card');
            var html = isMainTool ? '<div class="seoturbo-main-tool-stats"><div class="seoturbo-main-tool-active-badge"><div class="seoturbo-pulse-dot" style="margin-left:4px"></div><span>يقرأ الآن: <b class="stats-active">0</b></span></div><div class="seoturbo-main-tool-view-badge">👁️ <span>مشاهدات: <b class="stats-views">0</b></span></div><button class="seoturbo-main-tool-share-btn" type="button"><svg height="12" style="fill:var(--blogcolor);margin-left:4px" viewBox="0 0 512 512" width="12"><use href="#icon-share"/></svg><span>مشاركات: <b class="stats-shares">0</b></span></button></div>' : '<div class="seoturbo-slider-stats-bar"><div class="seoturbo-slider-active-badge"><div class="seoturbo-pulse-dot" style="margin-left:5px"></div><span>يقرأ الآن: <b class="stats-active">0</b></span></div><div class="seoturbo-slider-view-badge">👁️ <span>مشاهدات: <b class="stats-views">0</b></span></div><button class="seoturbo-slider-share-btn" type="button"><svg height="14" style="fill:var(--blogcolor);margin-left:5px" viewBox="0 0 512 512" width="14"><use href="#icon-share"/></svg><span>مشاركات: <b class="stats-shares">0</b></span></button></div>';
            var footer = card.querySelector('.seoturbo-main-tool-footer, .post-footer');
            if (footer) {
                footer.parentNode.insertBefore(htmlToDom(html), footer.nextSibling);
            } else {
                card.insertAdjacentHTML('beforeend', html);
            }
        });
    }
    function htmlToDom(html) {
        var d = document.createElement('div');
        d.innerHTML = html;
        return d.firstElementChild;
    }
    function populateStats() {
        if (!window.ST_StatsEngine) { setTimeout(populateStats, 100); return; }
        var items = document.querySelectorAll('.seoturbo-slider-stats-bar, .seoturbo-main-tool-stats');
        items.forEach(function(bar) {
            if (bar.classList.contains('is-active')) return;
            var card = bar.closest('article, .seoturbo-main-tool-card');
            if (!card) return;
            var id = card.getAttribute('data-id') || (card.querySelector('[data-id]') && card.querySelector('[data-id]').getAttribute('data-id'));
            var title = card.getAttribute('data-title') || (card.querySelector('.seoturbo-main-tool-title-card a, .rnav-title a') && card.querySelector('.seoturbo-main-tool-title-card a, .rnav-title a').textContent) || '';
            var pubEl = card.querySelector('.post-date-badge, [data-pub]');
            var pub = pubEl ? (pubEl.getAttribute('data-pub') || pubEl.textContent.replace(/[^0-9\-T:]/g,'').slice(0,10)) : '';
            if (!id || !title) return;
            var stats = window.ST_StatsEngine.getStats(id, title, pub);
            var activeEl = bar.querySelector('.stats-active');
            var viewsEl = bar.querySelector('.stats-views');
            var sharesEl = bar.querySelector('.stats-shares');
            if (activeEl) activeEl.textContent = stats.activeNow;
            if (viewsEl) viewsEl.textContent = stats.formattedViews;
            if (sharesEl) sharesEl.textContent = stats.formattedShares;
            bar.classList.add('is-active');
            var shareBtn = bar.querySelector('.seoturbo-slider-share-btn, .seoturbo-main-tool-share-btn');
            if (shareBtn) {
                var a = card.querySelector('.seoturbo-main-tool-title-card a, .rnav-title a, .post-title a');
                var link = a ? a.href : '';
                var img = card.querySelector('.post-thumb img, img.post-thumb');
                shareBtn.setAttribute('data-url', link);
                shareBtn.setAttribute('data-title', title);
                shareBtn.setAttribute('data-img', img ? img.src : '');
            }
        });
    }
    document.addEventListener('click', function(e) {
        var btn = e.target.closest('.seoturbo-slider-share-btn, .seoturbo-main-tool-share-btn');
        if (btn) {
            e.preventDefault(); e.stopPropagation();
            var url = btn.getAttribute('data-url');
            var title = btn.getAttribute('data-title');
            var shareModal = document.getElementById('seoturbo-share-modal');
            if (shareModal) {
                var input = document.getElementById('seoturbo-share-url-input');
                if (input) input.value = url;
                shareModal.classList.add('active');
                document.body.style.overflow = 'hidden';
            } else {
                if (navigator.share) { navigator.share({ title: title, url: url }); }
                else { prompt('رابط المقال:', url); }
            }
        }
    });
    function init() {
        injectStatsBars();
        setTimeout(populateStats, 200);
        setTimeout(populateStats, 800);
        setTimeout(function(){ injectStatsBars(); populateStats(); }, 1500);
        setTimeout(function(){ injectStatsBars(); populateStats(); }, 3000);
    }
    if (document.readyState === 'complete') init();
    else window.addEventListener('load', init);
})();

/* === SEOTurbo Module 15: 15-صفحة-مقال-محتويات-قد-يهمك-موضوعات-مرتبطة.js === */

(function() {
    'use strict';

    var freeContainer = document.getElementById('seoturbo-dual-placeholder');
    if(freeContainer) freeContainer.remove();

    const pb = document.querySelector('.post-body');
    if(!pb) return;

    function initTOC() {
        const headings = pb.querySelectorAll('h2, h3, h4');
        if(headings.length > 1) {
            let tocHTML = `<div class="topcs7v closed" id="tocDiv" title="فهرس التنقل الذكي">
                <div class="toctitle" style="cursor: pointer;" title="انقر لفتح أو إغلاق الفهرس">
                    <div class="toc-row-1">
                        <h2 title="قائمة أقسام المقال">جدول المحتويات</h2>
                    </div>
                    <div class="toc-row-2">
                        <span class="toc-icon" title="أيقونة الحالة"></span>
                        <span class="toc-toggle-btn" title="تبديل العرض">عرض</span>
                    </div>
                </div>
                <ul id="tocList" style="max-height: 400px; overflow-y: auto;">`;

            headings.forEach((h, i) => {
                const id = 'section-' + i;
                h.id = id;
                const text = h.textContent.trim();
                tocHTML += `<li class="toc-${h.tagName.toLowerCase()}" title="القفز إلى: ${text}">
                    <span class="bullet"></span>
                    <a href="#${id}" title="انقر للذهاب إلى: ${text}">${(i + 1)}. ${text}</a>
                    </li>`;
            });
            tocHTML += '</ul></div>';

            const titleBox = document.querySelector('.seoterbo-title-posttitle-box');
            const qualityBox = document.querySelector('.seoturbo-quality-container');

            const target = qualityBox || titleBox;

            if (target) {
                target.insertAdjacentHTML('afterend', tocHTML);
                const tDiv = document.getElementById('tocDiv');
                if (tDiv) {
                    tDiv.querySelector('.toctitle').onclick = () => {
                        tDiv.classList.toggle('closed');
                        tDiv.querySelector('.toc-toggle-btn').textContent = tDiv.classList.contains('closed') ? 'عرض' : 'إخفاء';
                    };
                }
            }
        }
    }

    function renderLinkedModules(entries) {
        const currentUrl = window.location.href.split('?')[0];
        const filtered = entries.filter(e => e.link.find(l => l.rel === 'alternate').href.split('?')[0] !== currentUrl);
        const rPl = document.getElementById('Linked-blogs-Related-Placeholder');
        const mPl = document.getElementById('Linked-blogs-Recommended-Placeholder');

        if (rPl) {
            let relH = '<span class="seoturbo-Linked-blogs-Related-Title" title="مواضيع متعلقة بسياق القراءة">موضوعات مرتبطة</span><div class="seoturbo-Linked-blogs-Related-Items">';
            filtered.slice(0, 4).forEach(e => {
                const t = e.title.$t, l = e.link.find(u=>u.rel==='alternate').href;
                relH += `<a class="seoturbo-Linked-blogs-Related-Item" href="${l}" title="متابعة قراءة: ${t}">
                    <span class="seoturbo-Linked-blogs-Related-Thumb" title="صورة: ${t}">
                    <img src="${window.optimizeImage(e.media$thumbnail?e.media$thumbnail.url:'','related')}" loading="lazy" alt="${t}"></span>
                    <span class="seoturbo-Linked-blogs-Related-Item-Title">${t}</span></a>`;
            });
            rPl.innerHTML = relH + '</div>';
        }
        if (mPl) {
            let recH = '<span class="seoturbo-Linked-blogs-Recommended-Title" title="ترشيحات مختارة لك">قد يهمك</span><div class="seoturbo-Linked-blogs-Recommended-Items">';
            filtered.slice(4, 8).forEach(e => {
                const t = e.title.$t, l = e.link.find(u=>u.rel==='alternate').href;
                recH += `<a class="seoturbo-Linked-blogs-Recommended-Item" href="${l}" title="فتح المقال: ${t}">
                    <span class="seoturbo-Linked-blogs-Recommended-Item-Title">${t}</span></a>`;
            });
            mPl.innerHTML = recH + '</div>';
        }
    }

    function initDualModules() {
        const placeholder = document.getElementById('linked-blogs-dual-placeholder');
        if (!placeholder || placeholder.hasAttribute('data-loaded')) return;
        placeholder.setAttribute('data-loaded', 'true');

        placeholder.innerHTML = `<div class="seoturbo-Linked-blogs-Dual-Module-Container" title="مركز التوصيات الذكية"><div id="Linked-blogs-Recommended-Placeholder" class="seoturbo-Linked-blogs-Recommended-Module"></div><div id="Linked-blogs-Related-Placeholder" class="seoturbo-Linked-blogs-Related-Module"></div></div>`;
        placeholder.style.display = 'block';

        const currentLabel = (window.postLabels && window.postLabels.length > 0) ? window.postLabels[0] : "موضوعات";

        if (window.ST_MASTER_PROMISE) {
            window.ST_MASTER_PROMISE.then(data => {
                if (data && data.feed && data.feed.entry) {
                    const matched = data.feed.entry.filter(e => e.category && e.category.some(c => c.term === currentLabel));
                    if (matched.length >= 4) {
                        renderLinkedModules(matched);
                    } else {
                        fetch(`/feeds/posts/summary/-/${encodeURIComponent(currentLabel)}?alt=json&max-results=9`)
                        .then(r => r.json()).then(j => { if(j.feed.entry) renderLinkedModules(j.feed.entry); });
                    }
                }
            });
        }
    }

    initTOC();

    const observer = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) {
            initDualModules();
            observer.disconnect();
        }
    }, { rootMargin: '300px' });

    const dualTarget = document.getElementById('linked-blogs-dual-placeholder');
    if (dualTarget) observer.observe(dualTarget);

})();

/* === SEOTurbo Module 16: 16-صفحة-مقال-إقرأ-أيضا.js === */

(function() {
    'use strict';

    var freeContainer = document.getElementById('seoturbo-reading-placeholder');
    var originalContainer = document.getElementById('reading-also-original');

    if (freeContainer) freeContainer.style.display = 'none';
    if (originalContainer) originalContainer.style.display = 'block';

    const numberOfPosts = 6;
    let isInitialized = false;

    function renderReadingAlso(posts) {
        const container = document.getElementById('reading-also-container');
        if (!container || posts.length === 0) return;

        const months = ["يناير", "فبراير", "مارس", "إبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
        let html = '';

        posts.slice(0, numberOfPosts).forEach(e => {
            const t = e.title.$t;
            const l = e.link.find(link => link.rel === 'alternate').href;
            const date = new Date(e.published.$t);
            const dateStr = `${date.getUTCDate()} ${months[date.getUTCMonth()]} ${date.getUTCFullYear()}`;
            const img = e.media$thumbnail ? e.media$thumbnail.url.replace(/\/s\d+(-[^\/]*)?\//, '/s400/') : 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEi7Ml848_trMe4J1co6ImpiKh7XcXn2ZsRTk85hy4oWOlBvvOIyHTSxoC1nvNwlZ0-PvMwjQFVEcqhA0H2dGcz-fWO9il9RlsmpXX8I7RLYt6y7kPb9cE2fKnBqdD7gvbSTfLfoSjCZs_brqPRiw335YfX5qGHS8iNYIHCBNUo1npNK3o8Oxtob-KxZeBk/s16000-rw/rbka-news300-100.webp';

            html += `<a class="related-thumb" href="${l}">
                        <img src="${img}" alt="${t}" loading="lazy">
                    </a>`;
        });
        container.innerHTML = html;
    }

    function initReadingAlsoEngine() {
        if (isInitialized) return;
        isInitialized = true;

        const currentUrl = window.location.href.split('?')[0];
        const currentLabel = (window.postLabels && window.postLabels.length > 0) ? window.postLabels[0] : "موضوعات";

        if (window.ST_MASTER_PROMISE) {
            window.ST_MASTER_PROMISE.then(data => {
                if (data && data.feed && data.feed.entry) {
                    let filtered = data.feed.entry.filter(e => {
                        let link = e.link.find(l => l.rel === 'alternate').href.split('?')[0];
                        return link !== currentUrl && e.category && e.category.some(c => c.term === currentLabel);
                    });

                    if (filtered.length >= numberOfPosts) {
                        console.log('🚀 SEOTurbo: تم ملء "مواضيع ذات صلة" من الذاكرة العالمية');
                        renderReadingAlso(filtered);
                    } else {
                        console.log('📡 SEOTurbo: جلب بيانات تكميلية لقسم "مواضيع ذات صلة"');
                        fetch(`/feeds/posts/summary/-/${encodeURIComponent(currentLabel)}?alt=json&max-results=12`)
                        .then(res => res.json()).then(j => {
                            if(j.feed.entry) {
                                let combined = j.feed.entry.filter(e => e.link.find(l => l.rel === 'alternate').href.split('?')[0] !== currentUrl);
                                renderReadingAlso(combined);
                            }
                        });
                    }
                }
            });
        }
    }

    const container = document.getElementById('reading-also-container');
    if (container) {
        const observer = new IntersectionObserver((entries) => {
            if (entries[0].isIntersecting) {
                initReadingAlsoEngine();
                observer.unobserve(container);
            }
        }, { rootMargin: '400px' }); 
        observer.observe(container);
    }

})();

/* === SEOTurbo Module 17: 17-صفحة-تحويل-الروابط.js === */

(function() {
    'use strict';
    function encodeBase64(str) { try { return btoa(encodeURIComponent(str)); } catch(e) { return encodeURIComponent(str); } }

    function initImperialLinkConverter() {
        if (!window.ST_REDIRECT_SYSTEM_ACTIVE) return;
        if (window.location.pathname.includes('/404') || window.location.search.includes('url=')) return;

        const currentDomain = window.location.hostname;
        const redirectBase = window.location.origin + "/404?url=";
        const containers = document.querySelectorAll('.post-body, .entry-content, .static-page-body');

        containers.forEach(container => {
            const links = container.getElementsByTagName('a');
            for (let i = 0; i < links.length; i++) {
                let link = links[i];
                let href = link.href;
                if (href && href.indexOf('http') === 0 && href.indexOf(currentDomain) === -1 && !href.startsWith('#') && href.indexOf('javascript') === -1) {
                    link.href = redirectBase + encodeBase64(href);
                    link.target = "_blank";
                    link.rel = "noopener noreferrer";
                }
            }
        });
    }
    if (window.requestIdleCallback) { requestIdleCallback(initImperialLinkConverter); } 
    else { window.addEventListener('load', initImperialLinkConverter); }
})();

/* === SEOTurbo Module ??:  === */

(function() {
    'use strict';

    function injectAds() {
        var tSrc = document.querySelector('#HTML991 .widget-content');
        var bSrc = document.querySelector('#HTML992 .widget-content');
        var tTrg = document.getElementById('redirect-ad-top-target');
        var bTrg = document.getElementById('redirect-ad-bottom-target');

        if (tSrc && tTrg) tTrg.innerHTML = tSrc.innerHTML;
        if (bSrc && bTrg) bTrg.innerHTML = bSrc.innerHTML;
    }

    function getDynamicSiteLogo() {
        var headerLogo = document.querySelector('#Header1_headerimg, .seoturbo-site-logo img, .header-widget img');
        if (headerLogo && headerLogo.src) return headerLogo.src;
        var favicon = document.querySelector('link[rel*="icon"]');
        return favicon ? favicon.href : '';
    }

    function startTimer(seconds, onComplete) {
        var time = seconds;
        var timerNum = document.getElementById('seoturbo-redirect-timer-num');
        var progress = document.getElementById('seoturbo-redirect-progress-bar');

        if (timerNum) timerNum.textContent = time;

        var interval = setInterval(function() {
            time--;
            if (timerNum) timerNum.textContent = time;

            if (progress) {
                var offset = 408 - ((seconds - time) / seconds * 408);
                progress.style.strokeDashoffset = offset;
            }

            if (time <= 0) {
                clearInterval(interval);
                if (onComplete) onComplete();
            }
        }, 1000);
    }

    function decodeRedirectUrl(encodedUrl) {
        try {
            var base64Decoded = atob(encodedUrl);
            return decodeURIComponent(base64Decoded);
        } catch (e) {
            try {
                return decodeURIComponent(encodedUrl);
            } catch(e2) {
                return encodedUrl;
            }
        }
    }

    function loadSuggestions() {
        var container = document.getElementById('seoturbo-redirect-404-posts-container');
        if (!container) return;

        var fallbackLogo = getDynamicSiteLogo();

        if (window.ST_MASTER_PROMISE) {
            window.ST_MASTER_PROMISE.then(function(data) {
                if (!data || !data.feed || !data.feed.entry) return;

                var html = '';
                var entries = data.feed.entry.slice(0, 4);

                for (var i = 0; i < entries.length; i++) {
                    var e = entries[i];
                    var title = e.title.$t;
                    var link = '';
                    var links = e.link;
                    for (var j = 0; j < links.length; j++) {
                        if (links[j].rel === 'alternate') {
                            link = links[j].href;
                            break;
                        }
                    }
                    var rawImg = (e.media$thumbnail && e.media$thumbnail.url) ? e.media$thumbnail.url : fallbackLogo;
                    var img = window.optimizeImage ? window.optimizeImage(rawImg, 'related') : rawImg.replace(/\/s\d+(-c)?\//, '/s400/');

                    html += '<div class="seoturbo-redirect-404-post">' +
                            '<a href="' + link + '">' +
                            '<img src="' + img + '" alt="' + title + '">' +
                            '<h4>' + title + '</h4>' +
                            '</a>' +
                            '</div>';
                }
                container.innerHTML = html;
            });
        }
    }

    function init() {
        var query = window.location.search;
        var engineUI = document.getElementById('seoturbo-redirect-engine');
        var errorUI = document.getElementById('seoturbo-redirect-404-error-view');
        var statusText = document.getElementById('seoturbo-redirect-status-text');
        var finalBtnArea = document.getElementById('seoturbo-redirect-btn-container');
        var timerNum = document.getElementById('seoturbo-redirect-timer-num');
        var progress = document.getElementById('seoturbo-redirect-progress-bar');

        injectAds();

        if (query.indexOf('url=') !== -1) {
            if (errorUI) errorUI.style.display = 'none';
            if (engineUI) engineUI.style.display = 'block';

            var encodedUrl = query.split('url=')[1];
            var decodedUrl = decodeRedirectUrl(encodedUrl);

            startTimer(10, function() {
                if (timerNum) timerNum.textContent = '✓';
                if (statusText) statusText.textContent = 'تم تأمين الرابط بنجاح';
                if (progress) progress.style.stroke = '#1e8e3e';
                if (finalBtnArea) finalBtnArea.style.display = 'block';

                var finalLink = document.getElementById('seoturbo-redirect-final-link');
                if (finalLink) {
                    var url = decodedUrl;
                    if (url.indexOf('http') !== 0 && url.indexOf('https') !== 0) {
                        url = 'https://' + url;
                    }
                    finalLink.href = url;
                }
            });
        } 
        else {
            if (errorUI) errorUI.style.display = 'none';
            if (engineUI) engineUI.style.display = 'block';
            if (statusText) statusText.textContent = 'جاري فحص قاعدة بيانات الموقع...';

            startTimer(10, function() {
                if (engineUI) {
                    engineUI.style.opacity = '0';
                    engineUI.style.transition = 'opacity 0.5s ease';
                }

                setTimeout(function() {
                    if (engineUI) engineUI.style.display = 'none';
                    if (errorUI) {
                        errorUI.style.display = 'block';
                        errorUI.style.opacity = '0';

                        requestAnimationFrame(function() {
                            errorUI.style.transition = 'opacity 0.5s ease';
                            errorUI.style.opacity = '1';
                        });
                    }
                    loadSuggestions();
                }, 500);
            });
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

/* === SEOTurbo Module 19: 19-ذكي-فتات-الخبز-ترجمة.js === */

(function() {
  'use strict';

  if (window._breadcrumbProcessed) return;

  const runTurboEngine = () => {
    const dict = window.seoturbo_label_dictionary || {};

    if (Object.keys(dict).length === 0) {
      setTimeout(runTurboEngine, 500);
      return;
    }

    if (window._breadcrumbProcessed) return;
    window._breadcrumbProcessed = true;

    const bcTarget = document.querySelector('.label-to-map');
    if (bcTarget && !bcTarget.hasAttribute('data-breadcrumb-translated')) {
      const raw = bcTarget.getAttribute('data-label')?.trim().toLowerCase();
      if (raw && dict[raw]) {
        const translated = dict[raw];
        if (bcTarget.innerHTML !== translated) {
          bcTarget.innerHTML = translated;
        }
        const plainName = bcTarget.textContent.trim();
        bcTarget.setAttribute('title', 'تصفح جميع مقالات قسم ' + plainName);
        bcTarget.setAttribute('data-breadcrumb-translated', 'true');

        const scriptTag = document.getElementById('breadcrumbData');
        if (scriptTag) {
          try {
            const jsonData = JSON.parse(scriptTag.textContent);
            if (jsonData.itemListElement && jsonData.itemListElement[1]) {
              jsonData.itemListElement[1].name = plainName;
              scriptTag.textContent = JSON.stringify(jsonData);
            }
          } catch(e) {}
        }
      }
    }

    document.querySelectorAll('.postcat:not([data-translated])').forEach(el => {
      const raw = el.textContent.trim().toLowerCase();
      if (dict[raw]) {
        const translated = dict[raw];
        if (el.innerHTML !== translated) {
          el.innerHTML = translated;
        }
        el.setAttribute('data-translated', 'true');
      }
    });
  };

  const execute = () => {
    setTimeout(runTurboEngine, 300);
  };

  if ('requestIdleCallback' in window) {
    requestIdleCallback(execute, { timeout: 3000 });
  } else {
    setTimeout(execute, 800);
  }
})();

/* === SEOTurbo Module 20: 20-ذكي-إطار-الصور-الفيديو.js === */

document.addEventListener('DOMContentLoaded', function() {
    'use strict';

    let cachedCategoryInfo = null;
    const pendingElements = new Set();
    let isProcessing = false;

    const IGNORED_IFRAME_CLASSES = ['BLOG_object_iframe', 'blogger-iframe-colorize', 'blogger-comment-from-post'];

    function getCategoryIconFromMenu(labelSlug) {
        const menuLinks = document.querySelectorAll('#main-menu a[href*="/search/label/"]');
        for (let link of menuLinks) {
            try {
                const href = decodeURIComponent(link.getAttribute('href'));
                if (href.includes('/' + labelSlug)) {
                    const icon = link.querySelector('svg, i');
                    if (icon) return icon.outerHTML;
                }
            } catch(e) {}
        }
        return '';
    }

    function getCategoryInfo() {
        if (cachedCategoryInfo) return cachedCategoryInfo;
        const dict = window.seoturbo_label_dictionary || {};
        const active = document.querySelector('.seoturbo-breadcrumbs-list a.label-to-map, .post-labels a');
        if (active) {
            try {
                const key = decodeURIComponent(active.href).split('/search/label/')[1].split(/[?#]/)[0].trim().toLowerCase();
                cachedCategoryInfo = { 
                    name: dict[key] || active.textContent.trim(), 
                    icon: getCategoryIconFromMenu(key), 
                    url: active.href 
                };
                return cachedCategoryInfo;
            } catch(e) {}
        }
        return { name: 'موضوعات', icon: '', url: '#' };
    }

    function getSourceInfo(el) {
        const info = ((el.alt || '') + (el.title || '') + (el.src || '')).toLowerCase();
        const isAI = ['ai', 'ذكاء', 'مولدة', 'generated'].some(word => info.includes(word));
        return isAI ? 
            { label: 'صورة أرشيفية', emoji: '<svg width="12" height="12" viewBox="0 0 640 512" style="fill:currentColor;"><use href="#icon-robot"/></svg>' } :
            { label: 'تصوير آخرون', emoji: '<svg width="12" height="12" viewBox="0 0 512 512" style="fill:currentColor;"><use href="#icon-camera"/></svg>' };
    }

    function shouldIgnoreIframe(iframeElement) {
        if (!iframeElement) return false;
        for (let className of IGNORED_IFRAME_CLASSES) {
            if (iframeElement.classList && iframeElement.classList.contains(className)) {
                return true;
            }
        }
        const src = iframeElement.src || '';
        return src.includes('/share-widget') || (src.includes('blogger.com') && src.includes('comment'));
    }

    function getVisualWidth(imgElement) {
        if (!imgElement) return 0;
        return imgElement.naturalWidth || imgElement.width || 0;
    }

    function isSmallOrThumbnailImage(imgElement) {
        if (!imgElement) return false;
        return !!imgElement.closest('.team-grid-table, .team-grid, .seoturbo-dep-members-list, .seoturbo-member-tag, .v-full-img, .management-frame, .seoterbo-title-writer-img');
    }

    function processFrameQueue() {
        if (pendingElements.size === 0) { isProcessing = false; return; }
        isProcessing = true;

        const frameTasks = [];
        const cat = getCategoryInfo();
        const favicon = document.querySelector('link[rel*="icon"]')?.href || '';

        pendingElements.forEach(media => {
            if (!media || media.closest('.seoterbo-frame-root-container')) return;

            const isVideo = ['iframe', 'video'].includes(media.tagName.toLowerCase());
            if (isVideo && shouldIgnoreIframe(media)) return;

            const insideDesc = isVideo ? (media.title || '') : (media.alt || media.title || '');
            const bloggerCaption = media.closest('.tr-caption-container')?.querySelector('.tr-caption') || 
                                   media.parentElement?.querySelector('.tr-caption');

            frameTasks.push({
                media,
                isVideo,
                insideDesc,
                outsideCaption: bloggerCaption ? bloggerCaption.textContent.trim() : "",
                srcInfo: getSourceInfo(media),
                elementToReplace: media.closest('.tr-caption-container') || media
            });
        });

        pendingElements.clear();

        requestAnimationFrame(() => {
            frameTasks.forEach(task => {
                const frameHTML = `
                    <div class="seoterbo-frame-root-container ${task.insideDesc ? 'has-internal-desc' : ''}">
                        <div class="seoterbo-frame-container">
                            <div class="seoterbo-frame-wrapper">
                                ${favicon ? `<div class="seoterbo-frame-logo"><img src="${favicon}" alt="Logo"></div>` : ''}
                                <a href="${cat.url}" class="seoterbo-frame-category-button">
                                    ${cat.icon || '<svg width="12" height="12" viewBox="0 0 576 512" style="fill:currentColor;"><use href="#icon-folder-open"/></svg>'} <span>${cat.name}</span>
                                </a>
                                <div class="seoterbo-frame-photo-credit"><span>${task.srcInfo.label}</span> <span class="frame-icon-emoji">${task.srcInfo.emoji}</span></div>
                                <div class="media-inner-holder"></div>
                                ${task.insideDesc ? `<div class="image-caption-overlay">${task.insideDesc}</div>` : ''}
                            </div>
                            ${task.outsideCaption ? `<div class="seoterbo-frame-caption">${task.outsideCaption}</div>` : ''}
                        </div>
                    </div>`;

                const container = document.createElement('div');
                container.innerHTML = frameHTML;
                const finalFrame = container.firstElementChild;
                const holder = finalFrame.querySelector('.media-inner-holder');

                if (task.isVideo) {
                    const vBox = document.createElement('div');
                    vBox.className = 'video-aspect-ratio-box';
                    vBox.style.paddingBottom = '56.25%';
                    const vContent = document.createElement('div');
                    vContent.className = 'video-aspect-ratio-content';
                    vContent.appendChild(task.media.cloneNode(true));
                    vBox.appendChild(vContent);
                    holder.appendChild(vBox);
                } else {
                    const processedImg = task.media.cloneNode(true);
                    processedImg.className = 'seoterbo-frame-img';
                    holder.appendChild(processedImg);
                }

                if (task.elementToReplace.parentNode) {
                    task.elementToReplace.parentNode.replaceChild(finalFrame, task.elementToReplace);
                    requestAnimationFrame(() => finalFrame.classList.add('is-visible'));
                }
            });
            isProcessing = false;
        });
    }

    const frameObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const el = entry.target;
                const isImg = el.tagName.toLowerCase() === 'img';

                if (isImg && isSmallOrThumbnailImage(el)) {
                    frameObserver.unobserve(el);
                    return;
                }

                const triggerProcess = () => {
                    if (getVisualWidth(el) > 300 || !isImg) {
                        pendingElements.add(el);
                        if (!isProcessing) processFrameQueue();
                    }
                };

                if (!isImg) {
                    triggerProcess();
                } else if (el.complete) {
                    triggerProcess();
                } else {
                    el.onload = triggerProcess;
                }
                frameObserver.unobserve(el);
            }
        });
    }, { rootMargin: '300px' });

    const body = document.querySelector('.post-body.entry-content, .static-page-body, .page-body, .post-body');
    if (body) {
        body.querySelectorAll('img, iframe, video').forEach(el => frameObserver.observe(el));
    }
});

/* === SEOTurbo Module 21: 21-ذكي-كلمة-مفتاحية-صندوق-المقال.js === */

(function() {
    'use strict';
    function translateKeyword(keyword) {
        if (!keyword) return keyword;
        try {
            if (window.seoturbo_label_dictionary) {
                var lowerKeyword = keyword.toLowerCase().trim();
                if (window.seoturbo_label_dictionary[lowerKeyword]) {
                    return window.seoturbo_label_dictionary[lowerKeyword];
                }
            }
        } catch(e) {}
        return keyword;
    }
    function initKeywordBadge() {
        var keywordBadge = document.getElementById('keyword-badge-target');
        if (!keywordBadge) return;
        var postBody = document.querySelector('.post-body, .entry-content');
        var finalKeyword = "";
        if (postBody) {
            var manualScript = postBody.querySelector('script#manual-keywords');
            if (manualScript) {
                try {
                    var json = JSON.parse(manualScript.textContent);
                    if (json && json.keywords) {
                        finalKeyword = json.keywords.split(',')[0].trim();
                    }
                } catch (e) {}
            }
        }
        if (!finalKeyword) {
            var metaKeywords = document.querySelector('meta[name="keywords"]');
            if (metaKeywords && metaKeywords.getAttribute('content')) {
                finalKeyword = metaKeywords.getAttribute('content').split(',')[0].trim();
            }
        }
        if (!finalKeyword) {
            var vault = document.getElementById('seoturbo-data-vault');
            if (vault && vault.getAttribute('data-label')) {
                finalKeyword = vault.getAttribute('data-label');
            }
        }
        if (!finalKeyword || finalKeyword === "موضوع") {
            var originalText = keywordBadge.textContent.trim();
            if (originalText && originalText !== "") finalKeyword = originalText;
        }
        if (!finalKeyword || finalKeyword === "") {
            finalKeyword = "موضوع";
        }
        var translated = translateKeyword(finalKeyword);
        translated = translated.replace(/^_+/, '').replace(/\s+/g, ' ').trim();
        keywordBadge.innerHTML = '<span>' + translated + '</span>';
        keywordBadge.href = '/search?q=' + encodeURIComponent(translated);
        if (!keywordBadge.querySelector('svg')) {
            var iconSvg = '<svg class="keyword-badge-icon" width="14" height="14" viewBox="0 0 512 512" style="fill:currentColor;margin-left:8px;"><path d="M0 252.118V48C0 21.49 21.49 0 48 0h204.118a48 48 0 0 1 33.941 14.059l211.882 211.882c18.745 18.745 18.745 49.137 0 67.882L293.823 497.941c-18.745 18.745-49.137 18.745-67.882 0L14.059 286.059A48 48 0 0 1 0 252.118zM112 64a48 48 0 1 0 0 96 48 48 0 0 0 0-96z"/></svg>';
            keywordBadge.insertAdjacentHTML('afterbegin', iconSvg);
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initKeywordBadge);
    } else {
        initKeywordBadge();
    }
})();

/* === SEOTurbo Module 22: 22-ذكي-إعلان-وسط-المقال.js === */

window.addEventListener('load', function() {
    var ad = document.getElementById('ST_Main_Ad_2'),
        post = document.querySelector('.post-body.entry-content');
    if (ad && post) {
        var elements = Array.from(post.children).filter(function(el) {
            return ['P', 'SECTION', 'TABLE', 'UL', 'OL', 'H3', 'H4'].includes(el.tagName);
        });
        if (elements.length > 2) {
            var mid = Math.floor(elements.length / 2);
            var target = elements[mid];
            ad.style.display = 'block';
            ad.style.margin = '30px auto';
            ad.style.textAlign = 'center';
            ad.style.clear = 'both';
            target.parentNode.insertBefore(ad, target.nextSibling);
        }
    }
});

/* === SEOTurbo Module 23: 23-ذكي-أزرار-المشاركة-والنسخ.js === */

(function() {
    'use strict';
    var freeContainer = document.getElementById('seoturbo-share-placeholder');
    if(freeContainer) freeContainer.remove();
    if (!window.location.pathname.includes('/20')) return;
    function hideToast() {
        var nativeToast = document.getElementById('seoturbo-ux-toast');
        if (nativeToast) {
            nativeToast.classList.remove('seoturbo-show');
            nativeToast.classList.remove('seoturbo-multiline-toast');
        }
        var fallbackToast = document.querySelector('.seoturbo-share-local-toast');
        if (fallbackToast) {
            fallbackToast.classList.remove('seoturbo-show-toast');
            setTimeout(function() {
                if (fallbackToast.parentNode) fallbackToast.parentNode.removeChild(fallbackToast);
            }, 300);
        }
        document.removeEventListener('click', documentDismissHandler);
    }
    function documentDismissHandler(e) {
        var nativeToast = document.getElementById('seoturbo-ux-toast');
        var fallbackToast = document.querySelector('.seoturbo-share-local-toast');
        var copyBtn = document.querySelector('.copy-link');
        if (copyBtn && copyBtn.contains(e.target)) {
            return;
        }
        if (nativeToast && nativeToast.contains(e.target)) {
            return;
        }
        if (fallbackToast && fallbackToast.contains(e.target)) {
            return;
        }

        hideToast();
    }
    function showToast(message, copiedUrl) {
        hideToast();
        var finalContent = '<div>' + message + '</div>';
        if (copiedUrl) {
            finalContent += '<div class="seoturbo-toast-url-block" title="' + copiedUrl + '">' + copiedUrl + '</div>';
        }
        var nativeToast = document.getElementById('seoturbo-ux-toast');
        if (nativeToast) {
            nativeToast.innerHTML = finalContent;
            nativeToast.classList.add('seoturbo-multiline-toast');
            nativeToast.classList.add('seoturbo-show');
        } else {
            var toast = document.createElement('div');
            toast.className = 'seoturbo-share-local-toast';
            toast.innerHTML = finalContent;
            document.body.appendChild(toast);
            requestAnimationFrame(function() {
                toast.classList.add('seoturbo-show-toast');
            });
        }
        setTimeout(function() {
            document.addEventListener('click', documentDismissHandler);
        }, 50);
    }
    function executeCopy(url) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(url).then(function() {
                showToast('<svg width="14" height="14" viewBox="0 0 512 512" style="fill: currentColor; margin-left: 5px; vertical-align: middle;"><use href="#icon-check-circle"/></svg> تم نسخ الرابط بنجاح ومشاركته جاهزة!', url);
            }).catch(function() {
                fallbackCopy(url);
            });
        } else {
            fallbackCopy(url);
        }
    }
    function fallbackCopy(url) {
        var tempInput = document.createElement('input');
        tempInput.value = url;
        document.body.appendChild(tempInput);
        tempInput.select();
        try {
            document.execCommand('copy');
            showToast('<svg width="14" height="14" viewBox="0 0 512 512" style="fill: currentColor; margin-left: 5px; vertical-align: middle;"><use href="#icon-check-circle"/></svg> تم نسخ الرابط بنجاح ومشاركته جاهزة!', url);
        } catch (err) {
            console.error('فشل النسخ:', err);
        }
        document.body.removeChild(tempInput);
    }
    function enhanceShareButtons() {
        var container = document.querySelector('.share-buttons-container');
        if (!container) return;
        var cleanUrl = window.location.href.split('?')[0].split('#')[0];
        var copyBtn = container.querySelector('.copy-link');
        if (copyBtn) {
            copyBtn.removeAttribute('onclick');
            copyBtn.addEventListener('click', function(e) {
                e.preventDefault();
                executeCopy(cleanUrl);
            });
        } else {
            copyBtn = document.createElement('button');
            copyBtn.className = 'share-button copy-link';
            copyBtn.setAttribute('title', 'نسخ الرابط المباشر');
            copyBtn.setAttribute('aria-label', 'نسخ الرابط المباشر');
            copyBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 512 512" style="fill: currentColor;"><use href="#icon-link"/></svg>';
            copyBtn.addEventListener('click', function(e) {
                e.preventDefault();
                executeCopy(cleanUrl);
            });
            container.appendChild(copyBtn);
        }
        var printBtn = container.querySelector('.print');
        if (printBtn) {
            printBtn.removeAttribute('onclick');
            printBtn.addEventListener('click', function(e) {
                e.preventDefault();
                window.print();
            });
        } else {
            printBtn = document.createElement('button');
            printBtn.className = 'share-button print';
            printBtn.setAttribute('title', 'طباعة المقال ورقيّاً أو حفظ كـ PDF');
            printBtn.setAttribute('aria-label', 'طباعة المقال ورقيّاً أو حفظ كـ PDF');
            printBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 512 512" style="fill: currentColor;"><use href="#icon-print"/></svg>';
            printBtn.addEventListener('click', function(e) {
                e.preventDefault();
                window.print();
            });
            container.appendChild(printBtn);
        }
        container.querySelectorAll('a.share-button').forEach(function(btn) {
            var originalHref = btn.getAttribute('href');
            if (originalHref && originalHref !== '#' && originalHref !== 'javascript:;') {
                btn.addEventListener('click', function(e) {
                    e.preventDefault();
                    var width = 600;
                    var height = 400;
                    var left = (screen.width - width) / 2;
                    var top = (screen.height - height) / 2;

                    window.open(
                        this.href,
                        'share-popup',
                        'width=' + width + ',height=' + height + ',top=' + top + ',left=' + left + ',resizable=yes,scrollbars=yes'
                    );
                });
            }
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', enhanceShareButtons);
    } else {
        enhanceShareButtons();
    }

})();

/* === SEOTurbo Module 24: 24-ذكي-موضوعات-ذات-صلة.js === */

(function() {
    'use strict';
    if (!window.location.pathname.includes('/20')) return;

    var placeholder = document.getElementById('seoturbo-related-placeholder');
    if(placeholder) placeholder.remove();

    let isInjected = false;

    function injectInternalLinks(entries) {
        if (isInjected) return;
        const pb = document.querySelector('.post-body.entry-content') || document.querySelector('.post-body');
        if (!pb || !entries || entries.length < 2) return;

        const paragraphs = Array.from(pb.children).filter(el => {
            return el.tagName === 'P' && el.innerText.trim().length > 40;
        });

        if (paragraphs.length < 2) return;

        const currentUrl = window.location.href.split('?')[0];
        const filtered = entries.filter(e => e.link.find(l => l.rel === 'alternate').href.split('?')[0] !== currentUrl).slice(0, 2);

        filtered.forEach((post, index) => {
            const pos = Math.floor(paragraphs.length * (index + 1) / (filtered.length + 1));
            const t = post.title.$t;
            const l = post.link.find(u => u.rel === 'alternate').href;

            const boxHTML = `
            <div class="seoturbo-related-link-box" title="توصية قراءة مرتبطة بهذا الجزء من الموضوع">
                <div class="seoturbo-related-icon" title="رابط توثيقي"><svg width="16" height="16" viewBox="0 0 512 512" style="fill: currentColor;"><use href="#icon-link"/></svg></div>
                <div class="seoturbo-related-content">
                    <span class="seoturbo-related-label" title="محتوى من نفس التصنيف">موضوعات ذات صلة</span>
                    <a href="${l}" class="seoturbo-related-title" title="انقر للانتقال وقراءة: ${t}">${t}</a>
                </div>
            </div>`;

            if (paragraphs[pos]) {
                paragraphs[pos].insertAdjacentHTML('afterend', boxHTML);
                isInjected = true;
            }
        });
    }

    function initInternalEngine() {
        const currentLabel = (window.postLabels && window.postLabels.length > 0) ? window.postLabels[0] : null;

        if (window.ST_MASTER_PROMISE) {
            window.ST_MASTER_PROMISE.then(data => {
                if (data && data.feed && data.feed.entry) {
                    let relatedFromCache = data.feed.entry.filter(e => currentLabel && e.category && e.category.some(c => c.term === currentLabel));

                    if (relatedFromCache.length >= 2) {
                        injectInternalLinks(relatedFromCache);
                    } else {
                        setTimeout(() => {
                            let apiUrl = `/feeds/posts/summary${currentLabel ? '/-/' + encodeURIComponent(currentLabel) : ''}?alt=json&max-results=6`;
                            fetch(apiUrl).then(r => r.json()).then(j => { if(j.feed.entry) injectInternalLinks(j.feed.entry); });
                        }, 4500);
                    }
                }
            });
        }
    }

    if ('requestIdleCallback' in window) {
        requestIdleCallback(initInternalEngine, { timeout: 3000 });
    } else {
        window.addEventListener('load', () => setTimeout(initInternalEngine, 2000));
    }
})();

/* === SEOTurbo Module 25: 25-ذكي-كلمات-مفتاحية-وروابط-تلقائية.js === */

(function() {
    'use strict';

    var freeContainer = document.getElementById('seoturbo-keywords-placeholder');
    if(freeContainer) freeContainer.remove();

    const runFast = window.requestIdleCallback || function(cb) { setTimeout(cb, 2000); };

    runFast(function() {
        const postBody = document.querySelector('.post-body.entry-content') || document.querySelector('.post-body');
        if (!postBody) return;

        const getMeta = (n) => document.querySelector(`meta[name="${n}"], meta[property="${n}"]`)?.content || "";
        const articleHeadline = document.querySelector('h1.seoterbo-title-main-headline')?.textContent.trim() || getMeta('og:site_name');

        function getManualKeywords() {
            const manual = document.getElementById('manual-keywords');
            if (!manual) return [];
            try {
                const data = JSON.parse(manual.textContent);
                return data.keywords ? data.keywords.split(',').map(k => k.trim()).filter(k => k.length > 0) : [];
            } catch (e) {
                console.warn("Manual Keywords Parse Error:", e);
                return [];
            }
        }

        function getCleanText(container) {
            const temp = document.createElement('div');
            temp.innerHTML = container.innerHTML;
            temp.querySelectorAll('script, style, textarea, .post-tags-container').forEach(el => el.remove());
            return temp.textContent || temp.innerText || "";
        }

        function gatherKeywords(text, manualList) {
            const stopWords = new Set(['في', 'على', 'عن', 'إلى', 'من', 'حتى', 'بين', 'أمام', 'خلف', 'تحت', 'فوق', 'عند', 'لدى', 'نحو', 'إلا', 'ال', 'هذا', 'هذه', 'هؤلاء', 'ذلك', 'تلك', 'أنا', 'أنت', 'هو', 'هي', 'نحن', 'أنتم', 'هم', 'و', 'أو', 'لكن', 'ثم', 'أم', 'الذي', 'التي', 'الذين', 'حيث', 'إذا', 'إن', 'إذ', 'كان', 'يكون', 'أصبح', 'صار', 'فقط', 'أيضا', 'قد', 'لقد', 'سوف', 'مع', 'قبل', 'بعد', 'جدا']);
            const freq = {};

            manualList.forEach(k => { freq[k.toLowerCase()] = 1000; });

            const words = text.split(/\s+/).filter(w => w.length > 3);
            words.forEach(w => {
                const normalized = w.replace(/[^\u0600-\u06FF\w]/g, '').toLowerCase();
                if (normalized.length > 3 && !stopWords.has(normalized)) {
                    freq[normalized] = (freq[normalized] || 0) + 1;
                }
            });

            return Object.keys(freq).sort((a, b) => freq[b] - freq[freq.hasOwnProperty(a) ? a : '']);
        }

        const manualKws = getManualKeywords();
        const cleanText = getCleanText(postBody);
        const allKeywords = gatherKeywords(cleanText, manualKws);

        requestAnimationFrame(() => {
            postBody.querySelectorAll('img').forEach((img, i) => {
                if (i === 0) img.setAttribute('fetchpriority', 'high');
                if (!img.alt) img.alt = articleHeadline;
                if (img.src.includes('bp.blogspot.com') && !img.src.includes('w1200')) {
                    img.src = img.src.replace(/\/(s\d+|w\d+-h\d+|w\d+)(-[^/]*)*\//, '/w1200-h630-p-k-no-nu-rw-l50/');
                }
            });

            const searchUrl = window.location.origin + '/search?q=';
            const walker = document.createTreeWalker(postBody, NodeFilter.SHOW_TEXT, {
                acceptNode: function(node) {
                    const p = node.parentElement;
                    if (!p || p.closest('script, style, a, h1, h2, h3, h4, table, .post-tags-container, .seoterbo-frame-root-container')) return NodeFilter.FILTER_REJECT;
                    return NodeFilter.FILTER_ACCEPT;
                }
            });

            let node, count = 0, linked = new Set();
            while ((node = walker.nextNode()) && count < 10) {
                for (const kw of allKeywords.slice(0, 20)) {
                    if (linked.has(kw)) continue;
                    const idx = node.nodeValue.indexOf(kw);
                    if (idx !== -1) {
                        const range = document.createRange();
                        range.setStart(node, idx);
                        range.setEnd(node, idx + kw.length);
                        const link = document.createElement('a');
                        link.href = searchUrl + encodeURIComponent(kw);
                        link.className = 'auto-internal-link';
                        link.textContent = kw;
                        range.surroundContents(link);
                        linked.add(kw);
                        count++;
                        break;
                    }
                }
            }

            const tagContainer = document.getElementById('keywords-section-placeholder');
            if (tagContainer && allKeywords.length > 0) {
                const tagsHTML = allKeywords.slice(0, 10).map(k => `<a href="${searchUrl}${encodeURIComponent(k)}" rel="tag">${k}</a>`).join('');
                tagContainer.innerHTML = `<div class="post-tags-container"><div class="post-tags-title"><svg width="14" height="14" viewBox="0 0 512 512" style="fill:currentColor;"><use href="#icon-tag"/></svg><span>الكلمات المفتاحية</span></div><div class="post-tags-list">${tagsHTML}</div></div>`;
                tagContainer.style.display = 'block';
            }
        });
    }, { timeout: 3000 });
})();

/* === SEOTurbo Module 26: 26-سيو-سكيما-عناكب-الرئيسية-الذكي.js === */

function processHomepageFeed(json) {
    if (json && json.feed && json.feed.entry && json.feed.entry.length > 0) {

        var vault = document.getElementById('homepage-identity-vault');
        var blogName = (vault && vault.getAttribute('data-name')) ? vault.getAttribute('data-name') : "إسم الموقع";

        var siteUrl = window.location.origin;

        var headerImg = document.querySelector('.header-widget img, #Header1_headerimg, .seoturbo-site-logo img, .seoturbo-site-management img');
        var publisherLogoUrl = headerImg ? headerImg.src : "";

        var logoWidth = 300, logoHeight = 100;
        if (headerImg && headerImg.naturalWidth > 0) {
            logoWidth = headerImg.naturalWidth;
            logoHeight = headerImg.naturalHeight;
        } else if (headerImg && headerImg.width) {
            logoWidth = headerImg.width;
            logoHeight = headerImg.height;
        }

        var siteTypeMeta = document.querySelector('meta[name="site-type"]');
        var rawSiteType = (siteTypeMeta && siteTypeMeta.content.trim() !== "") ? siteTypeMeta.content.trim() : "Organization";
        var publisherType = (rawSiteType === "NewsMediaOrganization") ? "NewsMediaOrganization" : "Organization";

        var SNIPPET_MAX_LENGTH = 310;

        function optimizeBloggerImage(currentSrc) {
            if (currentSrc && (currentSrc.indexOf('bp.blogspot.com') > -1 || currentSrc.indexOf('googleusercontent.com') > -1)) {
                return currentSrc.replace(/\/(s\d+|w\d+-h\d+|w\d+)(-[^/]*)*\//, '/w1200-h630-p-k-no-nu-rw-l50/').replace(/\.(jpe?g|png|gif|bmp)(\?.*)?$/i, '.webp');
            }
            return currentSrc;
        }

        function convertToCustomISO(dateString) {
            try { var date = new Date(dateString); return date.toISOString().replace(/(\.\d{3})?Z$/, '+02:00'); } catch (e) { return new Date().toISOString(); }
        }

        function getRealAboutMe(postId, blogTitle) {
            var authorBio = document.querySelector('.author-desc')?.textContent?.trim();
            if (authorBio && authorBio !== "") return authorBio;
            if (window.authorBios && window.authorBios[postId] && window.authorBios[postId] !== "") return window.authorBios[postId];
            return "كاتب ومحرر في موقع " + blogTitle + " | شغوف بمشاركة المعرفة وتقديم محتوى متميز يضيف قيمة حقيقية للقارئ.";
        }

        function extractQAFromSchema(rawContent) {
            var tempDiv = document.createElement('div');
            tempDiv.innerHTML = rawContent;
            var qaScript = tempDiv.querySelector('#qaData');
            if (!qaScript) return "";
            try {
                var qaData = JSON.parse(qaScript.textContent);
                var qaText = "\n\nأسئلة متعلقة بالموضوع:\n";
                var questions = (qaData.hasPart || []).concat(qaData.mainEntity ? [qaData.mainEntity] : []);
                questions.forEach(function(q) {
                    if (q.text) qaText += "سؤال: " + q.text.trim() + "\nجواب: " + (q.acceptedAnswer?.text || "") + "\n\n";
                });
                return qaText.trim();
            } catch (e) { return ""; }
        }

        function getArticleBodyFromContent(rawContent) {
            if (!rawContent) return "";
            var tempDiv = document.createElement('div');
            tempDiv.innerHTML = rawContent;
            tempDiv.querySelectorAll('svg, script, style, i, img').forEach(function(el) { el.remove(); });

            var unwanted = '.author-posts, .seoterbo-frame-container, .post-share-section, .seoturbo-Linked-blogs-Dual-Module-Container, .cooking-table, .HowTo-table, .author-pro-box, .post-labels, .post-tages-names, .seoturbo-related-link-box, .topcs7v, .commentsection, .seoturbo-readingalso, .seoturbo-posts1, .seoturbo-admin-tool, .post-actions-row, .seoturbo-breadcrumb-wrapper';

            var bodyText = '';
            var contentElements = tempDiv.querySelectorAll('p, h2, h3, h4, h5, h6, li, blockquote, table');

            for (var i = 0; i < contentElements.length; i++) {
                if (!contentElements[i].closest(unwanted)) {
                    var text = contentElements[i].textContent.trim();
                    if (text) bodyText += text + '\n\n';
                }
            }

            var qaText = extractQAFromSchema(rawContent);
            if (qaText) {
                bodyText += "\n\n" + qaText;
            }

            return bodyText.trim().replace(/\n\n+/g, '\n\n');
        }

        function getFinalKeywords(rawContent, articleSectionValue) {
            if (!rawContent) return articleSectionValue;
            var tempDiv = document.createElement('div');
            tempDiv.innerHTML = rawContent;

            var manualScript = tempDiv.querySelector('script#manual-keywords');
            if (manualScript) { 
                try { 
                    var kwData = JSON.parse(manualScript.textContent); 
                    if (kwData && kwData.keywords) return kwData.keywords.trim(); 
                } catch (e) {} 
            }

            var internalMeta = tempDiv.querySelector('meta[name="keywords"]');
            if (internalMeta) { 
                var metaContent = internalMeta.getAttribute('content'); 
                if (metaContent) return metaContent.trim(); 
            }

            return articleSectionValue;
        }

        function extractVideoDataFromPost(postBodyDiv, datePublished, articleHeadline, articleDescription) {
            if (!postBodyDiv) return null;
            var youtubeIframe = postBodyDiv.querySelector('iframe[src*="youtube.com/embed/"]');
            if (youtubeIframe) {
                var vIdMatch = youtubeIframe.getAttribute('src').match(/embed\/([^?]+)/);
                if (vIdMatch && vIdMatch[1]) {
                    return { 
                        "@type": "VideoObject", 
                        "name": youtubeIframe.getAttribute('title') || articleHeadline, 
                        "description": articleDescription.substring(0,150), 
                        "thumbnailUrl": "https://i.ytimg.com/vi/" + vIdMatch[1] + "/maxresdefault.jpg", 
                        "contentUrl": "https://www.youtube.com/watch?v=" + vIdMatch[1], 
                        "embedUrl": youtubeIframe.getAttribute('src'), 
                        "uploadDate": datePublished 
                    };
                }
            }
            return null;
        }

        function extractRecipeData(postBodyDiv, cleanUrl, finalImage) {
            var details = { recipeYield: "4 أشخاص", recipeIngredients: [], recipeInstructions: [], recipePrepTime: "15", recipeCookTime: "30", recipeCalories: null };
            if (!postBodyDiv) return details;

            postBodyDiv.querySelectorAll('.main-table, .cooking-table, .HowTo-table, table').forEach(function(table) {
                var headerText = table.querySelector('thead')?.textContent || "";

                if (headerText.indexOf('المكون') > -1 || headerText.indexOf('المقادير') > -1) { 
                    table.querySelectorAll('tbody tr').forEach(row => { 
                        var cells = row.querySelectorAll('td'); 
                        if (cells.length >= 2) {
                            var ingredient = cells[0].textContent.trim() + ' - ' + cells[1].textContent.trim();
                            if (ingredient && !ingredient.includes('---')) {
                                details.recipeIngredients.push(ingredient);
                            }
                        }
                    });
                } 
                else if (headerText.indexOf('الشرح') > -1 || headerText.indexOf('الطريقة') > -1) { 
                    table.querySelectorAll('tbody tr').forEach((row, index) => { 
                        var cells = row.querySelectorAll('td'); 
                        if (cells.length >= 3) {
                            var stepName = cells[1]?.textContent?.trim() || 'الخطوة ' + (index + 1);
                            var stepText = cells[2]?.textContent?.trim() || cells[1]?.textContent?.trim() || '';
                            if (stepText) {
                                details.recipeInstructions.push({ 
                                    "@type": "HowToStep", 
                                    "name": stepName, 
                                    "text": stepText, 
                                    "url": cleanUrl + '#step' + (index + 1), 
                                    "image": finalImage 
                                });
                            }
                        } else if (cells.length >= 2) {
                            details.recipeInstructions.push({ 
                                "@type": "HowToStep", 
                                "name": 'الخطوة ' + (index + 1), 
                                "text": cells[0].textContent.trim() + ' - ' + cells[1].textContent.trim(), 
                                "url": cleanUrl + '#step' + (index + 1), 
                                "image": finalImage 
                            });
                        }
                    });
                }
                else if (headerText.indexOf('المدة') > -1 || headerText.indexOf('الوقت') > -1) {
                    table.querySelectorAll('tbody tr').forEach(row => {
                        var cells = row.querySelectorAll('td');
                        if (cells.length >= 2) {
                            if (cells[0].textContent.includes('تحضير')) {
                                var prepMatch = cells[1].textContent.match(/\d+/);
                                if (prepMatch) details.recipePrepTime = prepMatch[0];
                            }
                            if (cells[0].textContent.includes('طهي') || cells[0].textContent.includes('طبخ')) {
                                var cookMatch = cells[1].textContent.match(/\d+/);
                                if (cookMatch) details.recipeCookTime = cookMatch[0];
                            }
                        }
                    });
                }
                else if (headerText.indexOf('السعرات') > -1) {
                    table.querySelectorAll('tbody tr').forEach(row => {
                        var cells = row.querySelectorAll('td');
                        if (cells.length >= 2 && cells[0].textContent.includes('السعرات')) {
                            details.recipeCalories = cells[1].textContent.trim();
                        }
                    });
                }
            });

            return details;
        }

        function extractHowToData(postBodyDiv) {
            var steps = [];
            if (!postBodyDiv) return null;
            var howToTable = postBodyDiv.querySelector('.HowTo-table');
            if (howToTable) {
                howToTable.querySelectorAll('tbody tr').forEach(function(row) {
                    var cell = row.querySelector('td:first-child');
                    if (cell) steps.push({ "@type": "HowToStep", "text": cell.textContent.trim() });
                });
                if (steps.length > 0) return { "@type": "HowTo", "step": steps, "aggregateRating": { "@type": "AggregateRating", "ratingValue": 3.8, "ratingCount": 15 } };
            }
            return null;
        }

        function extractSpeakableText(articleBodyText) {
            if (!articleBodyText || articleBodyText.length < 100) return '';

            var sentences = articleBodyText.split(/[.!?؟!]\s+/);
            var extractedText = '';
            var wordCount = 0;
            var maxWords = 200;
            var maxSentences = 5;

            for (var s = 0; s < Math.min(sentences.length, maxSentences * 2); s++) {
                var sentence = sentences[s].trim();
                if (sentence.length < 20) continue;

                var sentenceWords = sentence.split(/\s+/).length;
                if (wordCount + sentenceWords <= maxWords) {
                    extractedText += sentence + '. ';
                    wordCount += sentenceWords;
                } else {
                    var remaining = maxWords - wordCount;
                    if (remaining > 5) {
                        var truncatedWords = sentence.split(/\s+/).slice(0, remaining).join(' ');
                        extractedText += truncatedWords + '... ';
                    }
                    break;
                }
                if (s + 1 >= maxSentences && wordCount > 80) break;
            }

            return extractedText.length > 0 ? extractedText.substring(0, 2000) : '';
        }

        var schemaObjects = [];

        json.feed.entry.forEach(function(item) {
            var headline = item.title ? item.title.$t : blogName;
            var postUrl = item.link.find(function(link) { return link.rel === 'alternate'; })?.href;
            if (!postUrl) return;

            var postId = item.id.$t.split('post-')[1];
            var rawContent = item.content ? item.content.$t : '';
            var articleBody = getArticleBodyFromContent(rawContent);
            var wordCount = articleBody.split(/\s+/).length;
            var summary = articleBody.substring(0, SNIPPET_MAX_LENGTH) + '...';
            var postBodyDiv = document.createElement('div'); postBodyDiv.innerHTML = rawContent;

            var datePublished = convertToCustomISO(item.published.$t);
            var dateModified = convertToCustomISO(item.updated.$t);

            var authorName = item.author[0].name.$t;
            var authorUri = item.author[0].uri ? item.author[0].uri.$t : siteUrl;
            var fullBio = getRealAboutMe(postId, blogName);
            var jobTitle = "كاتب ومحرر محتوى", bioDesc = fullBio;
            if (fullBio.indexOf('|') > -1) { var parts = fullBio.split('|'); jobTitle = parts[0].trim(); bioDesc = parts[1].trim(); }

            var authorObject = { "@type": "Person", "name": authorName, "url": authorUri, "jobTitle": jobTitle, "description": bioDesc };

            var rawCategory = item.category ? item.category[0].term : 'موضوعات';
            var translatedCategory = window.seoturbo_translate_label ? window.seoturbo_translate_label(rawCategory) : rawCategory;
            var articleSection = translatedCategory;
            var schemaKeywords = getFinalKeywords(rawContent, articleSection);

            var imageUrl = item.media$thumbnail ? optimizeBloggerImage(item.media$thumbnail.url) : publisherLogoUrl;
            var videoObject = extractVideoDataFromPost(postBodyDiv, datePublished, headline, summary);

            var isRecipe = rawContent.includes('cooking-table');

            var articleType = 'BlogPosting'; 
            if (isRecipe) {
                articleType = 'Recipe';
            } else if (rawSiteType === 'TechnologyOrganization') {
                articleType = 'TechArticle';
            } else if (rawSiteType === 'NewsMediaOrganization') {
                articleType = 'NewsArticle';
            }

            var schemaData;

            if (articleType === 'Recipe') {
                var r = extractRecipeData(postBodyDiv, postUrl, imageUrl);
                schemaData = {
                    "@type": "Recipe", 
                    "name": headline, 
                    "headline": headline, 
                    "url": postUrl, 
                    "image": imageUrl,
                    "datePublished": datePublished, 
                    "dateModified": dateModified, 
                    "description": summary,
                    "author": authorObject, 
                    "recipeCategory": translatedCategory, 
                    "recipeCuisine": translatedCategory,
                    "recipeYield": r.recipeYield || "تكفي لعدة أشخاص", 
                    "keywords": schemaKeywords,
                    "prepTime": "PT" + (parseInt(r.recipePrepTime) || 15) + "M", 
                    "cookTime": "PT" + (parseInt(r.recipeCookTime) || 30) + "M",
                    "recipeIngredient": r.recipeIngredients.length > 0 ? r.recipeIngredients : ["انظر رابط الوصفة للمكونات"],
                    "recipeInstructions": r.recipeInstructions.length > 0 ? r.recipeInstructions : [{"@type":"HowToStep","name":"التحضير","text":"اتبع الخطوات في المقال"}],
                    "nutrition": { "@type": "NutritionInformation", "calories": r.recipeCalories || "250 kcal" },
                    "aggregateRating": { "@type": "AggregateRating", "ratingValue": 3.8, "ratingCount": 15 },
                    "video": videoObject || { 
                        "@type": "VideoObject", 
                        "name": headline, 
                        "description": summary, 
                        "thumbnailUrl": "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEj-hHIGluqSFnzzMB0MjtZalZl8azhcmY8kAJ06bBYTZzMLme38sT0igdo2-aWCE2ChKUEVI7ja6DK9BfGYlOQhqrQMRkDQuocWLMPCeQwyg-IbpWPuHXJGIBGo9z2_j1hADi924RPo6AJhpJry065PFl0Nt_rqJd4YsNihj5hW9qg4ENvyovw5nuEJCLK/s16000-rw/kitchen-bngr-recipes.webp", 
                        "contentUrl": "https://www.youtube.com/watch?v=0d930p5uPog", 
                        "embedUrl": "https://www.youtube.com/embed/0d930p5uPog", 
                        "uploadDate": datePublished, 
                        "duration": "PT1M10S" 
                    },
                    "publisher": { 
                        "@type": publisherType, 
                        "name": blogName, 
                        "logo": { 
                            "@type": "ImageObject", 
                            "url": publisherLogoUrl, 
                            "width": logoWidth, 
                            "height": logoHeight 
                        } 
                    }
                };
            } else {
                schemaData = {
                    "@type": articleType, 
                    "headline": headline, 
                    "url": postUrl, 
                    "image": [imageUrl],
                    "datePublished": datePublished, 
                    "dateModified": dateModified, 
                    "description": summary,
                    "articleBody": articleBody, 
                    "wordCount": wordCount, 
                    "articleSection": translatedCategory, 
                    "keywords": schemaKeywords,
                    "author": authorObject,
                    "publisher": { 
                        "@type": publisherType, 
                        "name": blogName, 
                        "logo": { 
                            "@type": "ImageObject", 
                            "url": publisherLogoUrl, 
                            "width": logoWidth, 
                            "height": logoHeight 
                        } 
                    }
                };
                if (videoObject) schemaData.video = videoObject;
                var howTo = extractHowToData(postBodyDiv);
                if (howTo) { 
                    howTo.name = headline; 
                    howTo.description = summary; 
                    howTo.image = imageUrl; 
                    schemaData.mainEntity = howTo; 
                }

                var speakableTextValue = extractSpeakableText(articleBody);
                if (speakableTextValue && speakableTextValue.length > 0) {
                    schemaData.speakable = {
                        "@type": "SpeakableSpecification",
                        "xpath": [
                            "/html/head/meta[@name='description']/@content"
                        ],
                        "value": speakableTextValue
                    };
                }
            }
            schemaData.mainEntityOfPage = { "@type": "WebPage", "@id": postUrl };

            schemaObjects.push(schemaData);
        });

        if (schemaObjects.length > 0) {
            var script = document.createElement('script');
            script.type = 'application/ld+json';
            script.text = JSON.stringify({ "@context": "https://schema.org", "@graph": schemaObjects });
            document.head.appendChild(script);
        }
    }
}
document.addEventListener('DOMContentLoaded', function() {
    var feedUrl = window.location.origin + '/feeds/posts/default?alt=json-in-script&max-results=10&callback=processHomepageFeed';
    var script = document.createElement('script'); 
    script.src = feedUrl; 
    document.body.appendChild(script);
});

/* === SEOTurbo Module 27: 27-سيو-سكيما-عناكب-الوصفات-الذكي.js === */

(function() {
    'use strict';

    document.addEventListener('DOMContentLoaded', function() {

        function isRecipePage() {
            var postBody = document.querySelector('.post-body');
            if (!postBody) return false;

            var hasCookingTable = postBody.querySelector('.cooking-table') !== null;
            var postText = postBody.textContent || postBody.innerText;
            var hasIngredientsTable = postText.includes('جدول المقادير');

            if (!hasCookingTable && !hasIngredientsTable) {
                return false;
            }
            return true;
        }

        if (!isRecipePage()) {
            return;
        }

        var identityVault = document.getElementById('homepage-identity-vault');
        var blogName = (identityVault && identityVault.getAttribute('data-name')) ? 
                       identityVault.getAttribute('data-name') : "إسم الموقع";

        var postVault = document.getElementById('seoturbo-data-vault');
        if (!postVault) {
            return;
        }

        var datePublished = postVault.getAttribute('data-pub') || new Date().toISOString();
        var dateModified = postVault.getAttribute('data-mod') || datePublished;
        var rawTitle = postVault.getAttribute('data-title') || document.title;
        var rawLabel = postVault.getAttribute('data-label') || "وصفات";

        var translatedLabel = window.seoturbo_translate_label ? window.seoturbo_translate_label(rawLabel) : rawLabel;

        var siteUrl = window.location.origin;
        var postUrl = window.location.href.split(/[?#]/)[0];

        var headerImg = document.querySelector('.header-widget img, #Header1_headerimg, .seoturbo-site-logo img, .seoturbo-site-management img');
        var publisherLogoUrl = headerImg ? headerImg.src : "";

        function optimizeBloggerImage(currentSrc) {
            if (currentSrc && (currentSrc.indexOf('bp.blogspot.com') > -1 || currentSrc.indexOf('googleusercontent.com') > -1)) {
                return currentSrc.replace(/\/(s\d+|w\d+-h\d+|w\d+)(-[^/]*)*\//, '/w1200-h630-p-k-no-nu-rw-l50/').replace(/\.(jpe?g|png|gif|bmp)(\?.*)?$/i, '.webp');
            }
            return currentSrc;
        }
        publisherLogoUrl = optimizeBloggerImage(publisherLogoUrl);

        var logoWidth = 300, logoHeight = 100;
        if (headerImg && headerImg.naturalWidth > 0) {
            logoWidth = headerImg.naturalWidth;
            logoHeight = headerImg.naturalHeight;
        }

        var siteTypeMeta = document.querySelector('meta[name="site-type"]');
        var rawSiteType = (siteTypeMeta && siteTypeMeta.content.trim() !== "") ? siteTypeMeta.content.trim() : "Organization";
        var publisherType = (rawSiteType === "NewsMediaOrganization") ? "NewsMediaOrganization" : "Organization";

        function convertToCustomISO(dateString) {
            try { var date = new Date(dateString); return date.toISOString().replace(/(\.\d{3})?Z$/, '+02:00'); } catch (e) { return new Date().toISOString(); }
        }
        datePublished = convertToCustomISO(datePublished);
        dateModified = convertToCustomISO(dateModified);

        function getRealAboutMe() {
            var descEl = document.querySelector('.author-desc, .author-pro-box .description');
            var authorDesc = descEl ? (descEl.textContent || descEl.innerText || '').trim() : '';
            if (authorDesc) return authorDesc;
            return "كاتب ومحرر في موقع " + blogName + " | شغوف بمشاركة المعرفة وتقديم محتوى متميز يضيف قيمة حقيقية للقارئ في مختلف المجالات.";
        }

        function buildAuthorObject() {
            var nameEl = document.querySelector('.seoterbo-title-writer-name, .author-name, .post-author');
            var authorName = nameEl ? (nameEl.textContent || nameEl.innerText || '').trim() : blogName;
            var uriEl = document.querySelector('.authornameurl a, .author-profile a');
            var authorUri = uriEl ? uriEl.href : siteUrl;
            var fullBio = getRealAboutMe();
            var jobTitle = "كاتب ومحرر محتوى", bioDesc = fullBio;
            if (fullBio.indexOf('|') > -1) { var parts = fullBio.split('|'); jobTitle = parts[0].trim(); bioDesc = parts[1].trim(); }

            var authorObject = { "@type": "Person", "name": authorName, "url": authorUri, "jobTitle": jobTitle, "description": bioDesc };
            var authImg = document.querySelector('.seoterbo-title-writer-img, .author-avatar img');
            if (authImg && authImg.src) authorObject.image = optimizeBloggerImage(authImg.src);
            return authorObject;
        }

        function getMainImage() {
            var postImg = document.querySelector('.post-body img:not(.seoterbo-frame-img):not(.author-img)');
            if (postImg && postImg.src) return optimizeBloggerImage(postImg.src);
            return publisherLogoUrl;
        }

        function extractVideoData() {
            var postBody = document.querySelector('.post-body');
            if (!postBody) return null;
            var youtubeIframe = postBody.querySelector('iframe[src*="youtube.com/embed/"]');
            if (youtubeIframe) {
                var vIdMatch = youtubeIframe.getAttribute('src').match(/embed\/([^?]+)/);
                if (vIdMatch && vIdMatch[1]) {
                    return { 
                        "@type": "VideoObject", 
                        "name": youtubeIframe.getAttribute('title') || rawTitle, 
                        "description": rawTitle, 
                        "thumbnailUrl": "https://i.ytimg.com/vi/" + vIdMatch[1] + "/maxresdefault.jpg", 
                        "contentUrl": "https://www.youtube.com/watch?v=" + vIdMatch[1], 
                        "embedUrl": youtubeIframe.getAttribute('src'), 
                        "uploadDate": datePublished 
                    };
                }
            }
            return null;
        }

        function extractRecipeData(finalImage) {
            var details = { 
                recipeYield: "4 أشخاص", 
                recipeIngredients: [], 
                recipeInstructions: [], 
                recipePrepTime: "15", 
                recipeCookTime: "30", 
                recipeCalories: "250 kcal" 
            };

            var postBody = document.querySelector('.post-body');
            if (!postBody) return details;

            postBody.querySelectorAll('.main-table, .cooking-table, .HowTo-table, table').forEach(function(table) {
                var headerText = table.querySelector('thead')?.textContent || "";

                if (headerText.indexOf('المكون') > -1 || headerText.indexOf('المقادير') > -1) { 
                    table.querySelectorAll('tbody tr').forEach(row => { 
                        var cells = row.querySelectorAll('td'); 
                        if (cells.length >= 2) {
                            var ingredient = cells[0].textContent.trim() + ' - ' + cells[1].textContent.trim();
                            if (ingredient && !ingredient.includes('---')) {
                                details.recipeIngredients.push(ingredient);
                            }
                        }
                    });
                } 
                else if (headerText.indexOf('الشرح') > -1 || headerText.indexOf('الطريقة') > -1) { 
                    table.querySelectorAll('tbody tr').forEach((row, index) => { 
                        var cells = row.querySelectorAll('td'); 
                        if (cells.length >= 3) {
                            var stepName = cells[1]?.textContent?.trim() || 'الخطوة ' + (index + 1);
                            var stepText = cells[2]?.textContent?.trim() || cells[1]?.textContent?.trim() || '';
                            if (stepText) {
                                details.recipeInstructions.push({ 
                                    "@type": "HowToStep", 
                                    "name": stepName, 
                                    "text": stepText, 
                                    "url": postUrl + '#step' + (index + 1), 
                                    "image": finalImage 
                                });
                            }
                        } else if (cells.length >= 2) {
                            details.recipeInstructions.push({ 
                                "@type": "HowToStep", 
                                "name": 'الخطوة ' + (index + 1), 
                                "text": cells[0].textContent.trim() + ' - ' + cells[1].textContent.trim(), 
                                "url": postUrl + '#step' + (index + 1), 
                                "image": finalImage 
                            });
                        }
                    });
                }
                else if (headerText.indexOf('المدة') > -1 || headerText.indexOf('الوقت') > -1) {
                    table.querySelectorAll('tbody tr').forEach(row => {
                        var cells = row.querySelectorAll('td');
                        if (cells.length >= 2) {
                            if (cells[0].textContent.includes('تحضير')) {
                                var prepMatch = cells[1].textContent.match(/\d+/);
                                if (prepMatch) details.recipePrepTime = prepMatch[0];
                            }
                            if (cells[0].textContent.includes('طهي') || cells[0].textContent.includes('طبخ')) {
                                var cookMatch = cells[1].textContent.match(/\d+/);
                                if (cookMatch) details.recipeCookTime = cookMatch[0];
                            }
                        }
                    });
                }
                else if (headerText.indexOf('السعرات') > -1) {
                    table.querySelectorAll('tbody tr').forEach(row => {
                        var cells = row.querySelectorAll('td');
                        if (cells.length >= 2 && cells[0].textContent.includes('السعرات')) {
                            details.recipeCalories = cells[1].textContent.trim();
                        }
                    });
                }
            });

            if (details.recipeIngredients.length === 0) {
                var ingredientElements = postBody.querySelectorAll('h3, h4, p strong');
                ingredientElements.forEach(function(el) {
                    if (el.textContent.includes('المكونات') || el.textContent.includes('المقادير')) {
                        var nextEl = el.nextElementSibling;
                        if (nextEl && nextEl.tagName === 'UL') {
                            nextEl.querySelectorAll('li').forEach(function(li) {
                                details.recipeIngredients.push(li.textContent.trim());
                            });
                        }
                    }
                });
            }

            return details;
        }

        var mainImage = getMainImage();
        var videoObject = extractVideoData();
        var recipeDetails = extractRecipeData(mainImage);
        var totalTime = parseInt(recipeDetails.recipePrepTime || 15) + parseInt(recipeDetails.recipeCookTime || 30);
        var authorObject = buildAuthorObject();

        var schemaData = {
            "@context": "https://schema.org",
            "@type": "Recipe",
            "name": rawTitle,
            "headline": rawTitle,
            "url": postUrl,
            "image": mainImage,
            "datePublished": datePublished,
            "dateModified": dateModified,
            "description": rawTitle + " - وصفة شهية وسهلة التحضير",
            "author": authorObject,
            "recipeCategory": translatedLabel,
            "recipeCuisine": translatedLabel,
            "recipeYield": recipeDetails.recipeYield || "تكفي لعدة أشخاص",
            "keywords": translatedLabel + "، وصفة، طبخ، مطبخ، طعام",
            "prepTime": "PT" + (parseInt(recipeDetails.recipePrepTime) || 15) + "M",
            "cookTime": "PT" + (parseInt(recipeDetails.recipeCookTime) || 30) + "M",
            "totalTime": "PT" + (totalTime || 45) + "M",
            "recipeIngredient": recipeDetails.recipeIngredients.length > 0 ? recipeDetails.recipeIngredients : ["انظر رابط الوصفة للمكونات"],
            "recipeInstructions": recipeDetails.recipeInstructions.length > 0 ? recipeDetails.recipeInstructions : [{"@type":"HowToStep","name":"التحضير","text":"اتبع الخطوات في المقال","url": postUrl + '#step1',"image": mainImage}],
            "nutrition": { 
                "@type": "NutritionInformation", 
                "calories": recipeDetails.recipeCalories || "250 kcal" 
            },
            "aggregateRating": { 
                "@type": "AggregateRating", 
                "ratingValue": 3.8, 
                "ratingCount": 15 
            },
            "video": videoObject || { 
                "@type": "VideoObject", 
                "name": rawTitle, 
                "description": rawTitle, 
                "thumbnailUrl": "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEj-hHIGluqSFnzzMB0MjtZalZl8azhcmY8kAJ06bBYTZzMLme38sT0igdo2-aWCE2ChKUEVI7ja6DK9BfGYlOQhqrQMRkDQuocWLMPCeQwyg-IbpWPuHXJGIBGo9z2_j1hADi924RPo6AJhpJry065PFl0Nt_rqJd4YsNihj5hW9qg4ENvyovw5nuEJCLK/s16000-rw/kitchen-bngr-recipes.webp", 
                "contentUrl": "https://www.youtube.com/watch?v=0d930p5uPog", 
                "embedUrl": "https://www.youtube.com/embed/0d930p5uPog", 
                "uploadDate": datePublished,
                "duration": "PT1M10S"
            },
            "publisher": { 
                "@type": publisherType, 
                "name": blogName, 
                "logo": { 
                    "@type": "ImageObject", 
                    "url": publisherLogoUrl, 
                    "width": logoWidth, 
                    "height": logoHeight 
                } 
            },
            "mainEntityOfPage": { 
                "@type": "WebPage", 
                "@id": postUrl 
            }
        };

        var script = document.createElement('script');
        script.type = 'application/ld+json';
        script.text = JSON.stringify(schemaData);
        document.head.appendChild(script);
    });
})();

/* === SEOTurbo Module 28: 28-سيو-سكيما-عناكب-المقالات-الذكي.js === */

(function() {
    'use strict';

    function buildTranslationDictionary() {
        if (window.seoturbo_label_dictionary && Object.keys(window.seoturbo_label_dictionary).length > 0) {
            return;
        }
        window.seoturbo_label_dictionary = {};
        const menuLinks = document.querySelectorAll('#main-menu a[href*="/search/label/"], .main-menu a[href*="/search/label/"]');
        menuLinks.forEach(link => {
            try {
                const href = decodeURIComponent(link.getAttribute('href'));
                const match = href.match(/\/search\/label\/([^\/?#]+)/);
                if (match) {
                    const slug = match[1].toLowerCase().trim();
                    const tempDiv = document.createElement('div');
                    tempDiv.innerHTML = link.innerHTML.replace(/^_/, '').trim();
                    tempDiv.querySelectorAll('i, svg, img, span').forEach(el => el.remove());
                    const cleanText = tempDiv.textContent.trim();
                    if (slug && cleanText) {
                        window.seoturbo_label_dictionary[slug] = cleanText;
                    }
                }
            } catch(e) {}
        });
    }

    function translateLabel(label) {
        if (!label) return "موضوعات";
        const searchKey = label.toLowerCase().trim();
        if (window.seoturbo_label_dictionary && window.seoturbo_label_dictionary[searchKey]) {
            return window.seoturbo_label_dictionary[searchKey];
        }
        return label;
    }

    document.addEventListener('DOMContentLoaded', function() {

        function isRecipePage() {
            var postBody = document.querySelector('.post-body');
            if (!postBody) return false;
            if (postBody.querySelector('.cooking-table')) return true;
            var postText = postBody.textContent || postBody.innerText;
            if (postText.includes('جدول المقادير')) return true;
            return false;
        }

        if (isRecipePage()) {
            return;
        }

        buildTranslationDictionary();

        var vault = document.getElementById('homepage-identity-vault');
        var blogName = (vault && vault.getAttribute('data-name')) ? vault.getAttribute('data-name') : "إسم الموقع";

        var postVault = document.getElementById('seoturbo-data-vault');
        if (!postVault) return;

        var datePublished = postVault.getAttribute('data-pub') || new Date().toISOString();
        var dateModified = postVault.getAttribute('data-mod') || datePublished;
        var rawTitle = postVault.getAttribute('data-title') || document.title;
        var rawLabel = postVault.getAttribute('data-label') || "موضوعات";
        var authorUrl = postVault.getAttribute('data-author-url') || "";

        var translatedLabel = translateLabel(rawLabel);

        var siteUrl = window.location.origin;
        var postUrl = window.location.href.split(/[?#]/)[0];

        var headerImg = document.querySelector('.header-widget img, #Header1_headerimg, .seoturbo-site-logo img');
        var publisherLogoUrl = headerImg ? headerImg.src : "";

        var logoWidth = 300, logoHeight = 100;
        if (headerImg && headerImg.naturalWidth > 0) {
            logoWidth = headerImg.naturalWidth;
            logoHeight = headerImg.naturalHeight;
        } else if (headerImg && headerImg.width) {
            logoWidth = headerImg.width;
            logoHeight = headerImg.height;
        }

        var siteTypeMeta = document.querySelector('meta[name="site-type"]');
        var rawSiteType = (siteTypeMeta && siteTypeMeta.content.trim() !== "") ? siteTypeMeta.content.trim() : "Organization";
        var publisherType = (rawSiteType === "NewsMediaOrganization") ? "NewsMediaOrganization" : "Organization";

        var SNIPPET_MAX_LENGTH = 310;

        function optimizeBloggerImage(currentSrc) {
            if (currentSrc && (currentSrc.indexOf('bp.blogspot.com') > -1 || currentSrc.indexOf('googleusercontent.com') > -1)) {
                return currentSrc.replace(/\/(s\d+|w\d+-h\d+|w\d+)(-[^/]*)*\//, '/w1200-h630-p-k-no-nu-rw-l50/').replace(/\.(jpe?g|png|gif|bmp)(\?.*)?$/i, '.webp');
            }
            return currentSrc;
        }

        function convertToCustomISO(dateString) {
            try { var date = new Date(dateString); return date.toISOString().replace(/(\.\d{3})?Z$/, '+02:00'); } catch (e) { return new Date().toISOString(); }
        }
        datePublished = convertToCustomISO(datePublished);
        dateModified = convertToCustomISO(dateModified);

        function extractQAFromSchema() {
            var qaScript = document.getElementById('qaData');
            if (!qaScript) return "";
            try {
                var qaData = JSON.parse(qaScript.textContent);
                var qaText = "\n\nأسئلة متعلقة بالموضوع:\n";
                var questions = (qaData.hasPart || []).concat(qaData.mainEntity ? [qaData.mainEntity] : []);
                questions.forEach(function(q) {
                    if (q.text) qaText += "سؤال: " + q.text.trim() + "\nجواب: " + (q.acceptedAnswer?.text || "") + "\n\n";
                });
                return qaText.trim();
            } catch (e) { return ""; }
        }

        function getRealAboutMe() {
            var authorDesc = document.querySelector('.author-desc, .author-pro-box .description')?.textContent?.trim();
            if (authorDesc && authorDesc !== "") {
                return authorDesc;
            }
            return "كاتب ومحرر في موقع " + blogName + " | شغوف بمشاركة المعرفة وتقديم محتوى متميز يضيف قيمة حقيقية للقارئ في مختلف المجالات.";
        }

        function buildAuthorObject() {
            var authorName = document.querySelector('.seoterbo-title-writer-name, .author-name, .post-author')?.textContent?.trim() || blogName;

            var authorUri = authorUrl || siteUrl;

            var fullBio = getRealAboutMe();
            var jobTitle = "كاتب ومحرر محتوى", bioDesc = fullBio;
            if (fullBio.indexOf('|') > -1) { 
                var parts = fullBio.split('|'); 
                jobTitle = parts[0].trim(); 
                bioDesc = parts[1].trim(); 
            }

            var authorObject = { "@type": "Person", "name": authorName, "url": authorUri, "jobTitle": jobTitle, "description": bioDesc };
            var authImg = document.querySelector('.seoterbo-title-writer-img, .author-avatar img');
            if (authImg && authImg.src) authorObject.image = optimizeBloggerImage(authImg.src);
            return authorObject;
        }

        function getMainImage() {
            var postImg = document.querySelector('.post-body img:not(.seoterbo-frame-img):not(.author-img)');
            if (postImg && postImg.src) return optimizeBloggerImage(postImg.src);
            return publisherLogoUrl;
        }

        function getArticleBodyFromContent() {
            var postBody = document.querySelector('.post-body');
            if (!postBody) return "";

            var tempDiv = document.createElement('div');
            tempDiv.innerHTML = postBody.innerHTML;
            tempDiv.querySelectorAll('svg, script, style, i, img').forEach(function(el) { el.remove(); });

            var unwanted = '.author-posts, .seoterbo-frame-container, .post-share-section, .seoturbo-Linked-blogs-Dual-Module-Container, .cooking-table, .HowTo-table, .author-pro-box, .post-labels, .post-tages-names, .seoturbo-related-link-box, .topcs7v, .commentsection, .seoturbo-readingalso, .seoturbo-posts1, .seoturbo-admin-tool, .post-actions-row, .seoturbo-breadcrumb-wrapper';

            var bodyText = '';
            var contentElements = tempDiv.querySelectorAll('p, h2, h3, h4, h5, h6, li, blockquote, table');

            for (var i = 0; i < contentElements.length; i++) {
                if (!contentElements[i].closest(unwanted)) {
                    var text = contentElements[i].textContent.trim();
                    if (text) bodyText += text + '\n\n';
                }
            }

            var qaText = extractQAFromSchema();
            if (qaText) {
                bodyText += "\n\n" + qaText;
            }

            return bodyText.trim().replace(/\n\n+/g, '\n\n');
        }

        function extractVideoData() {
            var postBody = document.querySelector('.post-body');
            if (!postBody) return null;
            var youtubeIframe = postBody.querySelector('iframe[src*="youtube.com/embed/"]');
            if (youtubeIframe) {
                var vIdMatch = youtubeIframe.getAttribute('src').match(/embed\/([^?]+)/);
                if (vIdMatch && vIdMatch[1]) {
                    return { 
                        "@type": "VideoObject", 
                        "name": youtubeIframe.getAttribute('title') || rawTitle, 
                        "description": rawTitle.substring(0,150), 
                        "thumbnailUrl": "https://i.ytimg.com/vi/" + vIdMatch[1] + "/maxresdefault.jpg", 
                        "contentUrl": "https://www.youtube.com/watch?v=" + vIdMatch[1], 
                        "embedUrl": youtubeIframe.getAttribute('src'), 
                        "uploadDate": datePublished 
                    };
                }
            }
            return null;
        }

        function extractHowToData() {
            var steps = [];
            var postBody = document.querySelector('.post-body');
            if (!postBody) return null;

            var howToTable = postBody.querySelector('.HowTo-table');
            if (howToTable) {
                howToTable.querySelectorAll('tbody tr').forEach(function(row) {
                    var cell = row.querySelector('td:first-child');
                    if (cell) {
                        steps.push({ 
                            "@type": "HowToStep", 
                            "text": cell.textContent.trim() 
                        });
                    }
                });

                if (steps.length > 0) {
                    return { 
                        "@type": "HowTo", 
                        "step": steps, 
                        "aggregateRating": { 
                            "@type": "AggregateRating", 
                            "ratingValue": 3.8, 
                            "ratingCount": 15 
                        } 
                    };
                }
            }
            return null;
        }

        function getFinalKeywords() {
            var postBody = document.querySelector('.post-body');
            if (!postBody) return translatedLabel;

            var tempDiv = document.createElement('div');
            tempDiv.innerHTML = postBody.innerHTML;

            var manualScript = tempDiv.querySelector('script#manual-keywords');
            if (manualScript) { 
                try { 
                    var kwData = JSON.parse(manualScript.textContent); 
                    if (kwData && kwData.keywords) return kwData.keywords.trim(); 
                } catch (e) {} 
            }

            var internalMeta = tempDiv.querySelector('meta[name="keywords"]');
            if (internalMeta) { 
                var metaContent = internalMeta.getAttribute('content'); 
                if (metaContent) return metaContent.trim(); 
            }

            return translatedLabel;
        }

        var mainImage = getMainImage();
        var articleBody = getArticleBodyFromContent();
        var wordCount = articleBody.split(/\s+/).length;
        var summary = articleBody.substring(0, SNIPPET_MAX_LENGTH) + '...';
        var videoObject = extractVideoData();
        var authorObject = buildAuthorObject();
        var finalKeywords = getFinalKeywords();

        var articleType = 'BlogPosting'; 
        if (rawSiteType === 'TechnologyOrganization') {
            articleType = 'TechArticle';
        } else if (rawSiteType === 'NewsMediaOrganization') {
            articleType = 'NewsArticle';
        }

        var schemaData = {
            "@context": "https://schema.org",
            "@type": articleType,
            "headline": rawTitle,
            "url": postUrl,
            "image": [mainImage],
            "datePublished": datePublished,
            "dateModified": dateModified,
            "description": summary,
            "articleBody": articleBody,
            "wordCount": wordCount,
            "articleSection": translatedLabel,
            "keywords": finalKeywords,
            "author": authorObject,
            "publisher": { 
                "@type": publisherType, 
                "name": blogName, 
                "logo": { 
                    "@type": "ImageObject", 
                    "url": publisherLogoUrl, 
                    "width": logoWidth, 
                    "height": logoHeight 
                } 
            },
            "mainEntityOfPage": { 
                "@type": "WebPage", 
                "@id": postUrl 
            }
        };

        if (videoObject) {
            schemaData.video = videoObject;
        }

        var howToData = extractHowToData();
        if (howToData) {
            howToData.name = rawTitle;
            howToData.description = summary;
            howToData.image = mainImage;
            schemaData.mainEntity = howToData;
        }

        var oldScript = document.querySelector('script[data-st-article-schema]');
        if (oldScript) oldScript.remove();

        var script = document.createElement('script');
        script.type = 'application/ld+json';
        script.setAttribute('data-st-article-schema', 'true');
        script.text = JSON.stringify(schemaData);
        document.head.appendChild(script);
    });
})();

/* === SEOTurbo Module 29: 29-سيو-سكيما-أسئلة-شائعة-الرئيسية.js === */

document.addEventListener('DOMContentLoaded', function() {
    function convertToISO8601(dateString) {
        if (!dateString) return null;
        try {
            var date = new Date(dateString);
            if (isNaN(date)) return null;
            var offset = 2 * 60 * 60 * 1000;
            var adjusted = new Date(date.getTime() + offset);
            return adjusted.toISOString().replace(/\.000Z$/, '+02:00');
        } catch (e) { return null; }
    }
    const identityVault = document.getElementById('homepage-identity-vault');
    const siteName = identityVault ? identityVault.getAttribute('data-name') : document.title.split(' - ')[0];
    const homepageUrl = window.location.origin;
    const headerLogo = document.querySelector('#Header1_headerimg, .header-widget img, .seoturbo-site-logo img');
    let logoUrl = headerLogo ? headerLogo.src : (document.querySelector('link[rel="icon"]')?.href || "");

    const rawSiteType = document.querySelector("meta[name='site-type']")?.getAttribute('content') || "Organization";
    const publisherType = (rawSiteType === "NewsMediaOrganization") ? "NewsMediaOrganization" : "Organization";
    const editorName = document.querySelector("meta[name='Editor-in-Chief']")?.getAttribute('content') || siteName;
    const editorUrl = document.querySelector("meta[name='Editor-in-Chief-url']")?.getAttribute('content') || homepageUrl;
    const pageDesc = document.querySelector("meta[name='description']")?.getAttribute('content') || ("اجابات الاسئلة الشائعة حول موقع " + siteName);
    const ogImage = document.querySelector("meta[property='og:image']")?.getAttribute('content') || logoUrl;
    const creationDateMeta = document.querySelector("meta[name='creationDate']")?.getAttribute('content');
    const finalDate = creationDateMeta ? convertToISO8601(creationDateMeta) : new Date().toISOString();

    const rawQuestions = [
      { q: "ما هي الخدمات التي يقدمها موقع " + siteName + "؟", a: "يقدم موقع " + siteName + " محتوى متنوع ومفيد في مجاله مع الحرص على تقديم معلومات دقيقة وحصرية للزوار" },
      { q: "هل المحتوى المنشور في " + siteName + " موثوق؟", a: "نعم نحن في " + siteName + " نحرص دائماً على التحقق من صحة المعلومات والمصادر لضمان تقديم أفضل تجربة للمستخدم" },
      { q: "هل تصفح موقع " + siteName + " مجاني؟", a: "نعم جميع الخدمات والمقالات المتوفرة على موقع " + siteName + " متاحة للزوار بشكل مجاني تماماً" },
      { q: "هل يدعم موقع " + siteName + " التصفح عبر الهاتف؟", a: "نعم تم تصميم موقع " + siteName + " ليكون متوافقاً مع جميع الأجهزة الذكية والهواتف المحمولة لتجربة تصفح سلسة" },
      { q: "كيف يمكنني التواصل مع إدارة " + siteName + "؟", a: "يمكنك التواصل معنا بسهولة عبر صفحة اتصل بنا الموجودة في الموقع لأي استفسارات أو اقتراحات" },
      { q: "هل يمكنني مشاركة المحتوى من " + siteName + "؟", a: "بالطبع ندعم ونشجع مشاركة المقالات والمحتوى المميز من " + siteName + " عبر منصات التواصل الاجتماعي المختلفة" }
    ];
    const mainEntityData = rawQuestions.map(item => ({
      "@type": "Question",
      "name": item.q,
      "acceptedAnswer": { "@type": "Answer", "text": item.a }
    }));
    const faqDataset = {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "@id": homepageUrl + "#faqpage",
      "headline": "أسئلة شائعة حول موقع " + siteName,
      "name": "صفحة الأسئلة المتكررة لموقع " + siteName,
      "description": pageDesc,
      "datePublished": finalDate,
      "dateModified": finalDate,
      "image": { "@type": "ImageObject", "url": ogImage, "width": 1000, "height": 1000 },
      "author": {
        "@type": "Person",
        "name": editorName,
        "url": editorUrl
      },
      "publisher": {
        "@type": publisherType,
        "name": siteName,
        "url": homepageUrl,
        "logo": { "@type": "ImageObject", "url": logoUrl, "width": 300, "height": 100 }
      },
      "mainEntityOfPage": { "@type": "WebPage", "@id": homepageUrl },
      "mainEntity": mainEntityData
    };
    const script = document.createElement('script');
    script.type = 'application/ld+json';
    script.id = 'seoturbo-faq-schema';
    const oldScript = document.getElementById('seoturbo-faq-schema');
    if (oldScript) { oldScript.remove(); }
    script.textContent = JSON.stringify(faqDataset);
    document.head.appendChild(script);
});

/* === SEOTurbo Module 30: 30- سيو-سكيما-المحتوى-المسموع-الذكي === */

(function() {
    'use strict';        
    function optimizeBloggerImage(currentSrc) {
        if (currentSrc && (currentSrc.indexOf('bp.blogspot.com') > -1 || currentSrc.indexOf('googleusercontent.com') > -1)) {
            return currentSrc.replace(/\/(s\d+|w\d+-h\d+|w\d+)(-[^/]*)*\//, '/w1200-h630-p-k-no-nu-rw-l50/').replace(/\.(jpe?g|png|gif|bmp)(\?.*)?$/i, '.webp');
        }
        return currentSrc;
    }

    function convertToCustomISO(dateString) {
        try { 
            var date = new Date(dateString); 
            return date.toISOString().replace(/(\.\d{3})?Z$/, '+02:00'); 
        } catch (e) { 
            return new Date().toISOString(); 
        }
    }

    function isRecipePage() {
        var postBody = document.querySelector('.post-body');
        if (!postBody) return false;

        if (postBody.querySelector('.cooking-table')) return true;

        var postText = postBody.textContent || postBody.innerText;
        if (postText.includes('جدول المقادير')) return true;

        return false;
    }

    function extractVideoData(datePublished, rawTitle) {
        var postBody = document.querySelector('.post-body');
        if (!postBody) return null;

        var youtubeIframe = postBody.querySelector('iframe[src*="youtube.com/embed/"]');
        if (youtubeIframe) {
            var vIdMatch = youtubeIframe.getAttribute('src').match(/embed\/([^?]+)/);
            if (vIdMatch && vIdMatch[1]) {
                return { 
                    "@type": "VideoObject", 
                    "name": youtubeIframe.getAttribute('title') || rawTitle, 
                    "description": rawTitle.substring(0,150), 
                    "thumbnailUrl": "https://i.ytimg.com/vi/" + vIdMatch[1] + "/maxresdefault.jpg", 
                    "contentUrl": "https://www.youtube.com/watch?v=" + vIdMatch[1], 
                    "embedUrl": youtubeIframe.getAttribute('src'), 
                    "uploadDate": datePublished,
                    "duration": "PT1M10S"
                };
            }
        }

        return null;
    }

    function getArticleBodyFromContent() {
        var postBody = document.querySelector('.post-body');
        if (!postBody) return "";
        var html = postBody.innerHTML;
        var tempDiv = document.createElement('div');
        tempDiv.innerHTML = html;

        tempDiv.querySelectorAll('svg, script, style, i, img').forEach(function(el) { el.remove(); });

        var unwanted = '.author-posts, .seoterbo-frame-container, .post-share-section, .seoturbo-Linked-blogs-Dual-Module-Container, .cooking-table, .HowTo-table, .author-pro-box, .post-labels, .post-tages-names, .seoturbo-related-link-box, .topcs7v, .commentsection, .seoturbo-readingalso, .seoturbo-posts1, .seoturbo-admin-tool, .post-actions-row, .seoturbo-breadcrumb-wrapper';

        var bodyText = '';
        var contentElements = tempDiv.querySelectorAll('p, h2, h3, h4, h5, h6, li, blockquote');

        for (var i = 0; i < contentElements.length; i++) {
            if (!contentElements[i].closest(unwanted)) {
                var text = contentElements[i].textContent.trim();
                if (text) bodyText += text + '\n\n';
            }
        }

        return bodyText.trim().replace(/\n\n+/g, '\n\n');
    }

    function extractSpeakableText() {
        var fullArticleBody = getArticleBodyFromContent();

        if (!fullArticleBody || fullArticleBody.length < 100) {
            return '';
        }

        var sentences = fullArticleBody.split(/[.!?؟!]\s+/);
        var speakableText = '';
        var wordCount = 0;
        var maxWords = 400;
        var maxSentences = 8;

        for (var i = 0; i < Math.min(sentences.length, maxSentences * 2); i++) {
            var sentence = sentences[i].trim();
            if (sentence.length < 20) continue;

            var sentenceWords = sentence.split(/\s+/).length;
            if (wordCount + sentenceWords <= maxWords) {
                speakableText += sentence + '. ';
                wordCount += sentenceWords;
            } else {
                var remaining = maxWords - wordCount;
                if (remaining > 5) {
                    var truncatedWords = sentence.split(/\s+/).slice(0, remaining).join(' ');
                    speakableText += truncatedWords + '... ';
                }
                break;
            }

            if (i + 1 >= maxSentences && wordCount > 150) break;
        }

        speakableText = speakableText
            .replace(/\s+/g, ' ')
            .replace(/[^\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFFa-zA-Z0-9\s.,!?;:()\-]/g, '')
            .trim();

        if (speakableText.length < 100) {
            var words = fullArticleBody.split(/\s+/);
            if (words.length > 0) {
                speakableText = words.slice(0, Math.min(400, words.length)).join(' ');
            }
        }

        return speakableText.substring(0, 2800);
    }

    function getArticleTypeAndPublisher() {
        var siteTypeMeta = document.querySelector('meta[name="site-type"]');
        var rawSiteType = (siteTypeMeta && siteTypeMeta.content.trim() !== "") ? siteTypeMeta.content.trim() : "Organization";
        var publisherType = (rawSiteType === "NewsMediaOrganization") ? "NewsMediaOrganization" : "Organization";

        var articleType = 'BlogPosting';

        if (rawSiteType === 'TechnologyOrganization') {
            articleType = 'TechArticle';
            console.log('💻 SEOTurbo: تقني - النوع = TechArticle');
        } else if (rawSiteType === 'NewsMediaOrganization') {
            articleType = 'NewsArticle';
            console.log('📰 SEOTurbo: إخباري - النوع = NewsArticle');
        } else {
            console.log('📄 SEOTurbo: مقال عادي - النوع = BlogPosting');
        }

        return { articleType: articleType, publisherType: publisherType };
    }

    function getPublisherData() {
        var vault = document.getElementById('homepage-identity-vault');
        var blogName = (vault && vault.getAttribute('data-name')) ? vault.getAttribute('data-name') : document.title.split(' - ')[0];

        var headerImg = document.querySelector('.header-widget img, #Header1_headerimg, .seoturbo-site-logo img');
        var publisherLogoUrl = headerImg ? optimizeBloggerImage(headerImg.src) : "";

        var logoWidth = 300, logoHeight = 100;
        if (headerImg && headerImg.naturalWidth > 0) {
            logoWidth = headerImg.naturalWidth;
            logoHeight = headerImg.naturalHeight;
        }

        return {
            name: blogName,
            logo: { "@type": "ImageObject", "url": publisherLogoUrl, "width": logoWidth, "height": logoHeight }
        };
    }

    function getAuthorData() {
        var authorName = document.querySelector('.seoterbo-title-writer-name, .author-name, .post-author')?.textContent?.trim() || 'الموقع';
        var authorUri = document.querySelector('.authornameurl a, .author-profile a')?.href || window.location.origin;

        var fullBio = document.querySelector('.author-desc, .author-pro-box .description')?.textContent?.trim();
        var jobTitle = "كاتب ومحرر محتوى", bioDesc = fullBio || "كاتب ومحرر في الموقع";
        if (fullBio && fullBio.indexOf('|') > -1) { 
            var parts = fullBio.split('|'); 
            jobTitle = parts[0].trim(); 
            bioDesc = parts[1].trim(); 
        }

        var authorObject = { 
            "@type": "Person", 
            "name": authorName, 
            "url": authorUri, 
            "jobTitle": jobTitle, 
            "description": bioDesc 
        };

        var authImg = document.querySelector('.seoterbo-title-writer-img, .author-avatar img');
        if (authImg && authImg.src) authorObject.image = optimizeBloggerImage(authImg.src);

        return authorObject;
    }

    function injectSpeakableSchema() {
        if (!document.querySelector('.post-body')) return;

        if (isRecipePage()) {
            console.log('🍳 SEOTurbo: وصفة - يتم تخطي Speakable Schema (غير مدعوم للوصفات)');
            return;
        }

        var speakableText = extractSpeakableText();

        if (speakableText.length < 100) {
            console.log('⚠️ SEOTurbo: Speakable Schema - لا يوجد محتوى كافٍ للنطق');
            return;
        }

        var dataVault = document.getElementById('seoturbo-data-vault');
        var postTitle = dataVault?.getAttribute('data-title') || document.title.split(' - ')[0];
        var postUrl = window.location.href.split(/[?#]/)[0];
        var rawLabel = dataVault?.getAttribute('data-label') || 'موضوعات';

        var translatedLabel = (window.seoturbo_label_dictionary && window.seoturbo_label_dictionary[rawLabel.toLowerCase()]) || rawLabel;

        var datePublished = dataVault?.getAttribute('data-pub') || new Date().toISOString();
        var dateModified = dataVault?.getAttribute('data-mod') || datePublished;
        datePublished = convertToCustomISO(datePublished);
        dateModified = convertToCustomISO(dateModified);

        var types = getArticleTypeAndPublisher();
        var publisherData = getPublisherData();
        var authorData = getAuthorData();

        var description = document.querySelector('meta[name="description"]')?.content || 
                         (speakableText.length > 200 ? speakableText.substring(0, 200) + '...' : speakableText);

        var mainImage = '';
        var postImg = document.querySelector('.post-body img:not(.seoterbo-frame-img):not(.author-img)');
        if (postImg && postImg.src) mainImage = optimizeBloggerImage(postImg.src);
        if (!mainImage) mainImage = publisherData.logo.url;

        var videoObject = extractVideoData(datePublished, postTitle);

        var mainEntity = {
            "@type": types.articleType,
            "headline": "المحتوى المسموع لمقالة: " + postTitle,
            "url": postUrl,
            "image": [mainImage],
            "datePublished": datePublished,
            "dateModified": dateModified,
            "description": description,
            "articleSection": translatedLabel,
            "keywords": translatedLabel,
            "author": authorData,
            "publisher": {
                "@type": types.publisherType,
                "name": publisherData.name,
                "logo": publisherData.logo
            },
            "mainEntityOfPage": {
                "@type": "WebPage",
                "@id": postUrl
            },
            "speakable": {
                "@type": "SpeakableSpecification",
                "cssSelector": [
                    ".seoterbo-title-main-headline",
                    ".seoterbo-title-headline-container",
                    ".post-body p:first-of-type"
                ],
                "xpath": [
                    "/html/head/meta[@name='description']/@content"
                ]
            }
        };

        if (videoObject) {
            mainEntity.video = videoObject;
        }

        var schemaGraph = [mainEntity];

        var speakableSchema = {
            "@context": "https://schema.org",
            "@graph": schemaGraph
        };

        var script = document.createElement('script');
        script.type = 'application/ld+json';
        script.id = 'seoturbo-speakable-schema';

        var oldScript = document.getElementById('seoturbo-speakable-schema');
        if (oldScript) oldScript.remove();

        script.textContent = JSON.stringify(speakableSchema, null, 2);
        document.head.appendChild(script);

        console.log('✅ SEOTurbo: Speakable Schema تم إنشاؤه');
        console.log('📢 النوع: ' + types.articleType);
    }

    function initSpeakableSystem() {
        if (document.readyState === 'complete') {
            setTimeout(injectSpeakableSchema, 800);
        } else {
            window.addEventListener('load', function() {
                setTimeout(injectSpeakableSchema, 1000);
            });
        }

        setTimeout(function() {
            if (!document.getElementById('seoturbo-speakable-schema')) {
                injectSpeakableSchema();
            }
        }, 3500);
    }

    initSpeakableSystem();

})();

/* === SEOTurbo Module 31: 31-سيو-سكيما-أسئلة-أجوبة.js === */

(function() {
    'use strict';

    var freeContainer = document.getElementById('seoturbo-qa-placeholder');
    if(freeContainer) freeContainer.remove();

    document.addEventListener('DOMContentLoaded', function() {
        const postBody = document.querySelector('.post-body.entry-content');
        if (!postBody) return;

        const dataVault = document.getElementById('seoturbo-data-vault');

        const getArticleInfo = () => {
            const headline = dataVault?.getAttribute('data-title') || document.title;
            const url = dataVault?.getAttribute('data-url') || window.location.href;
            const datePublished = dataVault?.getAttribute('data-pub') || new Date().toISOString();
            const dateModified = dataVault?.getAttribute('data-mod') || datePublished;
            const authorUrlFromVault = dataVault?.getAttribute('data-author-url') || '';

            const authorNameEl = document.querySelector('.seoterbo-title-writer-name');
            const authorRoleEl = document.querySelector('.seoterbo-title-writer-role');

            const authorName = authorNameEl?.textContent.trim() || 'تحرير الموقع';
            const authorUrl = authorUrlFromVault || window.location.origin;
            const authorJobTitle = authorRoleEl?.textContent.trim() || 'كاتب ومحرر محتوى';

            return { headline, url, datePublished, dateModified, author: { name: authorName, url: authorUrl, jobTitle: authorJobTitle } };
        };

        const populateAndGetQAData = () => {
            const qaScript = document.getElementById('qaData');
            if (!qaScript) return null;

            try {
                const articleData = getArticleInfo();
                let schemaString = qaScript.textContent;

                schemaString = schemaString.split('"__POST_DATE__"').join(JSON.stringify(articleData.datePublished));
                schemaString = schemaString.split('"__POST_MODIFIED_DATE__"').join(JSON.stringify(articleData.dateModified));
                schemaString = schemaString.split('"__AUTHOR_NAME__"').join(JSON.stringify(articleData.author.name.replace(/"/g, '\\"')));
                schemaString = schemaString.split('"__AUTHOR_URL__"').join(JSON.stringify(articleData.author.url));
                schemaString = schemaString.split('"__POST_URL__"').join(JSON.stringify(articleData.url));
                schemaString = schemaString.split('"لاتكتب فيها شئ يتم توليدها ديناميكيا"').join(JSON.stringify('أسئلة وأجوبة توثيقية عن: ' + articleData.headline));

                const qaData = JSON.parse(schemaString);

                const updateDetails = (entity) => {
                    if (entity) {
                        if (entity.author) {
                            entity.author['@type'] = 'Person';
                            entity.author.url = articleData.author.url;
                            if (!entity.author.jobTitle) entity.author.jobTitle = articleData.author.jobTitle;
                        }
                        if (entity.acceptedAnswer) {
                            entity.acceptedAnswer['@type'] = 'Answer';
                            entity.acceptedAnswer.url = articleData.url;
                            if (entity.acceptedAnswer.author) {
                                entity.acceptedAnswer.author['@type'] = 'Person';
                                entity.acceptedAnswer.author.url = articleData.author.url;
                            }
                            if (window.SeoTurboVotes && typeof window.SeoTurboVotes.generate === 'function') {
                                const voteId = (entity.text || articleData.headline) + articleData.url;
                                entity.acceptedAnswer.upvoteCount = window.SeoTurboVotes.generate(voteId, articleData.datePublished);
                            }
                        }
                    }
                };

                if (qaData.mainEntity) updateDetails(qaData.mainEntity);
                if (qaData.hasPart && Array.isArray(qaData.hasPart)) {
                    qaData.hasPart.forEach(part => updateDetails(part));
                }

                qaScript.textContent = JSON.stringify(qaData, null, 2);
                return qaData;
            } catch (e) {
                console.warn('QA Schema Error:', e);
                return null;
            }
        };

        const insertQAContainerIntoPlaceholder = () => {
            const qaData = populateAndGetQAData();
            if (!qaData) return;

            const questionsToDisplay = [];
            if (qaData.mainEntity?.text && qaData.mainEntity.acceptedAnswer?.text) {
                questionsToDisplay.push({
                    question: qaData.mainEntity.text,
                    answer: qaData.mainEntity.acceptedAnswer.text,
                    votes: qaData.mainEntity.acceptedAnswer.upvoteCount
                });
            }
            if (qaData.hasPart && Array.isArray(qaData.hasPart)) {
                qaData.hasPart.forEach(part => {
                    if (part['@type'] === 'Question' && part.text && part.acceptedAnswer?.text) {
                        questionsToDisplay.push({ 
                            question: part.text, 
                            answer: part.acceptedAnswer.text,
                            votes: part.acceptedAnswer.upvoteCount
                        });
                    }
                });
            }

            if (questionsToDisplay.length === 0) return;

            const placeholder = document.getElementById('qa-section-placeholder');
            if (!placeholder) return;

            const titleElement = document.createElement('h3');
            titleElement.className = 'qa-section-title';
            titleElement.textContent = 'الأسئلة الشائعة والمعلومات الموثقة';

            const qaContainer = document.createElement('div');
            qaContainer.className = 'qa-container-wrapper';

            const listElement = document.createElement('ul');
            listElement.className = 'qa-list';

            questionsToDisplay.forEach(item => {
                const listItem = document.createElement('li');
                listItem.className = 'qa-list-item';
                const questionDiv = document.createElement('div');
                questionDiv.className = 'qa-question';

                if (item.votes !== undefined && item.votes !== null && window.SeoTurboVotes) {
                    questionDiv.innerHTML = `<span>${item.question}</span> <small class="qa-vote-badge" style="display: inline-flex; align-items: center; font-size: 13px; color: #155f26; font-weight: bold; float: left; background: #f2f8f5; padding: 4px 12px; border-radius: 12px; border: 1px solid #c3e6cb; margin-top: 2px;">${item.votes} تصويت</small>`;
                } else {
                    questionDiv.innerHTML = `<span>${item.question}</span>`;
                }

                const answerDiv = document.createElement('div');
                answerDiv.className = 'qa-answer';
                answerDiv.innerHTML = item.answer;
                listItem.appendChild(questionDiv);
                listItem.appendChild(answerDiv);
                listElement.appendChild(listItem);
            });

            qaContainer.appendChild(listElement);
            placeholder.appendChild(titleElement);
            placeholder.appendChild(qaContainer);
            placeholder.style.display = 'block';
        };

        if ('requestIdleCallback' in window) {
            requestIdleCallback(insertQAContainerIntoPlaceholder, { timeout: 1000 });
        } else {
            setTimeout(insertQAContainerIntoPlaceholder, 500);
        }
    });
})();

/* === SEOTurbo Module 32: 32-سيو-سكيما-بيانات-الموقع.js === */

(function() {
    'use strict';

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initDatasetSchema);
    } else {
        initDatasetSchema();
    }

    function initDatasetSchema() {
        let siteName = '';

        const vaultElement = document.getElementById('homepage-identity-vault');
        if (vaultElement && vaultElement.getAttribute('data-name')) {
            siteName = vaultElement.getAttribute('data-name');
        }

        if (!siteName) {
            const metaSiteName = document.querySelector('meta[name="site-name"]');
            if (metaSiteName && metaSiteName.getAttribute('content')) {
                siteName = metaSiteName.getAttribute('content');
            }
        }

        if (!siteName) {
            const homeTitle = document.querySelector('.site-title a, .site-title');
            if (homeTitle) {
                siteName = homeTitle.textContent.trim();
            }
        }

        if (!siteName) {
            const ogSiteName = document.querySelector('meta[property="og:site_name"]');
            if (ogSiteName && ogSiteName.getAttribute('content')) {
                siteName = ogSiteName.getAttribute('content');
            }
        }

        if (!siteName) {
            siteName = 'الموقع الرسمي';
        }

        let logoUrl = '';
        const logoImg = document.querySelector('#Header1_headerimg, .header-widget img');
        if (logoImg && logoImg.src) {
            logoUrl = logoImg.src;
        }

        if (!logoUrl) {
            const favicon = document.querySelector('link[rel*="icon"]');
            if (favicon && favicon.href) {
                logoUrl = favicon.href;
            }
        }

        const homepageUrl = window.location.origin;
        const licenseUrl = homepageUrl + '/p/privacy-policy.html';

        const categoryMetas = document.querySelectorAll("meta[name='category']");
        const generatedDatasets = [];

        if (logoUrl && siteName) {
            categoryMetas.forEach(function(meta) {
                const content = meta.getAttribute('content');
                if (content) {
                    const parts = content.split(' | ');
                    if (parts.length === 2) {
                        const name = parts[0].trim();
                        let description = parts[1].trim();

                        if (description.length < 60) {
                            description = description + " - تصفح مجموعة بيانات ومعلومات شاملة ومحدثة حول " + name + " مقدمة حصرياً من فريق " + siteName;
                        }

                        const catUrl = homepageUrl + "/search/label/" + encodeURIComponent(name);

                        const dataset = {
                            "@context": "https://schema.org",
                            "@type": "Dataset",
                            "name": "مجموعة بيانات قسم " + name,
                            "description": description,
                            "url": catUrl,
                            "disambiguatingDescription": "بيانات تفصيلية ومقالات حول " + name,
                            "creator": { 
                                "@type": "Organization", 
                                "name": "فريق " + siteName, 
                                "url": homepageUrl 
                            },
                            "keywords": [name],
                            "author": { 
                                "@type": "Organization", 
                                "name": "فريق " + siteName, 
                                "url": homepageUrl 
                            },
                            "publisher": {
                                "@type": "Organization",
                                "name": siteName,
                                "url": homepageUrl,
                                "logo": {
                                    "@type": "ImageObject",
                                    "name": "شعار " + siteName,
                                    "url": logoUrl,
                                    "encodingFormat": "image/webp",
                                    "width": 120,
                                    "height": 120
                                }
                            },
                            "license": licenseUrl,
                            "isAccessibleForFree": true,
                            "inLanguage": "ar"
                        };
                        generatedDatasets.push(dataset);
                    }
                }
            });

            if (generatedDatasets.length > 0) {
                const oldScript = document.getElementById('datasetSchema');
                if (oldScript) {
                    oldScript.remove();
                }

                const schemaScript = document.createElement('script');
                schemaScript.type = 'application/ld+json';
                schemaScript.id = 'datasetSchema';
                schemaScript.textContent = JSON.stringify(generatedDatasets, null, 2);
                document.head.appendChild(schemaScript);

                console.log('✅ Datasets Schema تم إنشاؤه بنجاح لـ ' + generatedDatasets.length + ' قسم');
            }
        }
    }
})();

/* === SEOTurbo Module 33: 33-سيو-سكيما-منصات-قوائم.js === */

(function() {
    'use strict';

    function initItemListSchema() {
        const isHomepage = "<data:view.isHomepage/>" === "true";
        const isLabel = "<data:view.isLabelSearch/>" === "true";
        const isSearch = "<data:view.isSearch/>" === "true";
        const isArchivePage = window.location.pathname.includes('/p/archive.html');
        const isImageSitemap = window.location.pathname.includes('/p/sitemap-images.html');

        const idVault = document.getElementById('homepage-identity-vault');
        const blogName = idVault ? idVault.getAttribute('data-name') : document.title;

        let displayName = document.title.split(' - ')[0];
        let finalDescription = "";
        let labelSlug = "";

        if (isImageSitemap) {
            displayName = "معرض الصور - " + blogName;
            finalDescription = "تصفح أحدث الصور والتقارير المصورة والحصرية المنشورة في بوابة " + blogName;
            console.log("📸 معرض الصور: تم تفعيل سكيما منصة العرض.");
        }
        else if (isArchivePage) {
            displayName = "أرشيف المقالات";
            finalDescription = "تصفح الأرشيف الكامل لجميع المقالات والتقارير المنشورة في " + blogName;
        }
        else if (isHomepage) {
            displayName = blogName;
            const longDescVault = document.getElementById('header-desc-source');
            finalDescription = (longDescVault && longDescVault.textContent.trim() !== "") ? longDescVault.textContent.trim() : "";
        } 
        else if (isLabel) {
            const pathParts = window.location.pathname.split('/search/label/');
            if (pathParts[1]) {
                labelSlug = decodeURIComponent(pathParts[1].split(/[?#]/)[0]);
            }
            const bcTarget = document.querySelector('.seoturbo-breadcrumbs-current');
            if (bcTarget && bcTarget.textContent.trim() !== "") {
                displayName = bcTarget.textContent.trim();
            }

            const categoryMetas = document.querySelectorAll('meta[name="category"]');
            categoryMetas.forEach(meta => {
                const content = meta.getAttribute('content');
                if (content && content.includes('|')) {
                    const parts = content.split('|');
                    if (parts[0].trim() === displayName || parts[0].trim() === labelSlug) {
                        finalDescription = parts[1].trim();
                    }
                }
            });
        }

        if (!finalDescription) {
            finalDescription = document.querySelector('meta[name="description"]')?.getAttribute('content') || blogName;
        }

        let feedUrl = "/feeds/posts/default?alt=json-in-script&max-results=12";
        if (isLabel && labelSlug) {
            feedUrl = "/feeds/posts/default/-/" + encodeURIComponent(labelSlug) + "?alt=json-in-script&max-results=12";
        } else if (isSearch) {
            const q = new URLSearchParams(window.location.search).get('q');
            if (q) feedUrl = "/feeds/posts/default?q=" + encodeURIComponent(q) + "&alt=json-in-script&max-results=12";
        }

        window.processItemList = function(json) {
            if (!json || !json.feed || !json.feed.entry) return;

            const items = json.feed.entry.map((entry, index) => {
                const url = (entry.link.find(l => l.rel === 'alternate') || {}).href;
                const cleanUrl = url ? url.split('?')[0].split('#')[0] : "";
                return {
                    "@type": "ListItem",
                    "position": index + 1,
                    "name": entry.title.$t,
                    "url": cleanUrl
                };
            });

            const schema = {
                "@context": "https://schema.org",
                "@type": "ItemList",
                "name": displayName,
                "description": finalDescription,
                "numberOfItems": items.length,
                "itemListElement": items
            };

            const script = document.createElement('script');
            script.type = 'application/ld+json';
            script.text = JSON.stringify(schema);
            document.head.appendChild(script);

            console.log("✅ ItemList Created for: " + displayName);
            delete window.processItemList;
        };

        const scriptTag = document.createElement('script');
        scriptTag.src = feedUrl + "&callback=processItemList";
        document.body.appendChild(scriptTag);
    }

    window.addEventListener('load', function() {
        setTimeout(initItemListSchema, 1500);
    });
})();

/* === SEOTurbo Module 34: 34-سيو-سكيما-معرض-الصور.js === */

document.addEventListener('DOMContentLoaded', function() {
    const vault = document.getElementById('homepage-identity-vault');
    const CONFIG = {
        siteName: (vault && vault.getAttribute('data-name')) ? vault.getAttribute('data-name') : document.title,
        blogURL: window.location.origin.replace(/\/+$/, "")
    };

    function addSchemaScript(schemaData, scriptId) {
        const script = document.createElement('script');
        script.type = 'application/ld+json';
        script.id = scriptId;
        script.textContent = JSON.stringify(schemaData);
        document.head.appendChild(script);
    }

    function getImageMetaData(rawUrl) {
        let finalUrl = rawUrl;
        let format = "image/jpeg";
        if (rawUrl && (rawUrl.includes('bp.blogspot.com') || rawUrl.includes('googleusercontent.com'))) {
            finalUrl = rawUrl.replace(/\/(s\d+|w\d+-h\d+|w\d+)(-[^/]*)*\//, '/w1200-h630-p-k-no-nu-rw-l50/');
            format = "image/webp";
        } else if (rawUrl.endsWith('.webp')) {
            format = "image/webp";
        }
        return { url: finalUrl, format: format, width: 1200, height: 630 };
    }

    function createImageSchema(imgUrl, postTitle, postUrl, pubDate) {
        const imgMeta = getImageMetaData(imgUrl);
        const year = pubDate ? new Date(pubDate).getFullYear() : new Date().getFullYear();
        let schema = {
            "@type": "ImageObject",
            "contentUrl": imgMeta.url,
            "thumbnail": imgMeta.url,
            "width": imgMeta.width,
            "height": imgMeta.height,
            "encodingFormat": imgMeta.format,
            "datePublished": pubDate || new Date().toISOString(),
            "url": postUrl,
            "name": postTitle,
            "description": "صورة من مقالة: " + postTitle,
            "creditText": CONFIG.siteName,
            "copyrightNotice": "جميع الحقوق محفوظة © " + CONFIG.siteName + " " + year,
            "license": CONFIG.blogURL + "/p/terms-of-use.html",
            "acquireLicensePage": CONFIG.blogURL + "/p/contact-us.html",
            "creator": {
                "@type": "Organization",
                "name": CONFIG.siteName,
                "url": CONFIG.blogURL
            }
        };
        return schema;
    }

    const currentPath = window.location.pathname;

    if (currentPath === '/' || currentPath.includes('sitemap-images.html')) {
        window.parseImgSchema = function(json) {
            let schemaGraph = [{"@context": "https://schema.org", "@type": "ImageGallery", "name": "معرض صور " + CONFIG.siteName, "url": window.location.href}];
            if (json.feed && json.feed.entry) {
                json.feed.entry.forEach(post => {
                    let pTitle = post.title.$t;
                    let pUrl = post.link.find(l => l.rel === 'alternate').href;
                    let pDate = post.published.$t;
                    let thumb = post.media$thumbnail ? post.media$thumbnail.url : null;
                    if (thumb) schemaGraph.push(createImageSchema(thumb, pTitle, pUrl, pDate));
                });
                addSchemaScript({"@context": "https://schema.org", "@graph": schemaGraph}, 'gallery-schema');
            }
        };
        const script = document.createElement('script');
        script.src = CONFIG.blogURL + "/feeds/posts/default?alt=json-in-script&max-results=24&callback=parseImgSchema";
        document.body.appendChild(script);
    } else if (document.querySelector('.post-body')) {
        const pTitle = document.querySelector('.seoterbo-title-main-headline')?.textContent.trim() || document.title;
        const pUrl = window.location.href.split(/[?#]/)[0];
        const pDate = document.getElementById('seoturbo-data-vault')?.getAttribute('data-pub');
        let schemaGraph = [{"@context": "https://schema.org", "@type": "ImageGallery", "name": "ألبوم صور: " + pTitle, "url": pUrl}];

        const imgs = Array.from(document.querySelectorAll('.post-body img:not(.author-img):not(.seoterbo-frame-logo img)')).filter(img => {
            const src = img.src.toLowerCase();
            const isUIIcon = /favicon|icon|logo|badge|social|button/i.test(src) || /favicon|icon|logo|badge|social|button/i.test(img.className);
            const isSmall = (img.naturalWidth > 0 && img.naturalWidth < 200) || (img.width > 0 && img.width < 200);
            return !isUIIcon && !isSmall;
        });

        imgs.forEach(img => {
            if (img.src && img.src.startsWith('http')) {
                schemaGraph.push(createImageSchema(img.src, pTitle, pUrl, pDate));
            }
        });
        if (schemaGraph.length > 1) {
            addSchemaScript({"@context": "https://schema.org", "@graph": schemaGraph}, 'post-imgs-schema');
        }
    }
});

/* === SEOTurbo Module 40: 40-ترجمة-قاموس-التصنيفات.js === */

(function() {
    'use strict';

    if (window.seoturbo_translation_loaded) return;
    window.seoturbo_translation_loaded = true;

    window.seoturbo_label_dictionary = window.seoturbo_label_dictionary || {};
    window.seoturbo_dictionary_ready = false;

    function sanitizeText(html) {
        if (!html) return '';
        var div = document.createElement('div');
        div.innerHTML = html.replace(/^_/, '').trim();
        div.querySelectorAll('i, svg, img, style, script, span').forEach(function(el) { el.remove(); });
        return div.textContent.replace(/\s+/g, ' ').trim();
    }

    function buildDictionary() {
        if (window.seoturbo_dictionary_ready) return;

        var links = document.querySelectorAll('#main-menu a[href*="/search/label/"], .main-menu a[href*="/search/label/"]');
        if (!links.length) return;

        links.forEach(function(link) {
            try {
                var href = decodeURIComponent(link.getAttribute('href'));
                var match = href.match(/\/search\/label\/([^\/?#]+)/);
                if (match) {
                    var slug = match[1].toLowerCase().trim();
                    var fullHTML = link.innerHTML.replace(/^_/, '').trim();
                    if (slug && fullHTML && !window.seoturbo_label_dictionary[slug]) {
                        window.seoturbo_label_dictionary[slug] = sanitizeText(fullHTML);
                    }
                }
            } catch(e) {}
        });

        window.seoturbo_dictionary_ready = true;
        translatePageTitle();
    }

    window.seoturbo_translate_label = function(englishLabel) {
        if (!englishLabel) return englishLabel;
        var searchKey = englishLabel.toLowerCase().trim();
        return window.seoturbo_label_dictionary[searchKey] || englishLabel;
    };

    function translatePageTitle() {
        if (!window.seoturbo_dictionary_ready) return;
        if (!window.location.pathname.includes('/search/label/')) return;

        var labelSlug = decodeURIComponent(window.location.pathname.split('/search/label/')[1] || '').split(/[?#]/)[0].toLowerCase().trim();
        var translatedLabel = window.seoturbo_label_dictionary[labelSlug];
        if (!translatedLabel || translatedLabel === labelSlug) return;

        var siteTitle = document.querySelector('title')?.textContent.split(' - ')[1] || 
                       document.querySelector('meta[property="og:site_name"]')?.getAttribute('content') || '';

        if (siteTitle) {
            document.title = translatedLabel + ' - ' + siteTitle;
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', buildDictionary);
    } else {
        buildDictionary();
    }

})();

/* === SEOTurbo Module 41: 41-ترجمة-أيقونات-التصنيفات.js === */

(function() {
    'use strict';

    var categoryData = {};
    var blogColor = getComputedStyle(document.documentElement).getPropertyValue('--blogcolor').trim() || '#6366f1';
    var colorList = Array(16).fill(blogColor);
    var colorIndex = 0;

    document.querySelectorAll('#main-menu a[href*="/search/label/"], .main-menu a[href*="/search/label/"]').forEach(function(link) {
        try {
            var href = decodeURIComponent(link.getAttribute('href'));
            var match = href.match(/\/search\/label\/([^\/?#]+)/);
            if (match) {
                var slug = match[1].toLowerCase().trim();
                var fullHTML = link.innerHTML.replace(/^_/, '').trim();

                var iconHTML = '';
                var iconTag = link.querySelector('i, svg');
                if (iconTag) {
                    iconHTML = iconTag.outerHTML.replace(/fill="[^"]*"/g, "").replace(/style="[^"]*"/g, "");
                }

                var tempDiv = document.createElement('div');
                tempDiv.innerHTML = fullHTML;
                tempDiv.querySelectorAll('i, svg, img').forEach(function(el) { el.remove(); });
                var cleanText = tempDiv.textContent.trim();

                if (slug && cleanText) {
                    categoryData[slug] = {
                        name: cleanText,
                        icon: iconHTML,
                        color: colorList[colorIndex % colorList.length]
                    };
                    colorIndex++;
                }
            }
        } catch(e) {}
    });

    function applyCategoryStyles() {
        var categoryButtons = document.querySelectorAll('.postcat');

        categoryButtons.forEach(function(btn) {
            var btnText = btn.textContent.trim();
            var matchedData = null;

            for (var slug in categoryData) {
                if (categoryData[slug].name === btnText) {
                    matchedData = categoryData[slug];
                    break;
                }
            }

            if (matchedData) {
                btn.style.backgroundColor = matchedData.color;

                if (!btn.querySelector('i, svg') && matchedData.icon) {
                    var tempSpan = document.createElement('span');
                    tempSpan.innerHTML = matchedData.icon;
                    var iconElement = tempSpan.firstChild;
                    if (iconElement) {
                        iconElement.style.marginLeft = '6px';
                        iconElement.style.fontSize = '11px';
                        iconElement.style.fill = 'currentColor'; 
                        btn.insertBefore(iconElement, btn.firstChild);
                    }
                }
            }
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            setTimeout(applyCategoryStyles, 500);
            setTimeout(applyCategoryStyles, 1500);
        });
    } else {
        setTimeout(applyCategoryStyles, 500);
        setTimeout(applyCategoryStyles, 1500);
    }

    if (window.MutationObserver) {
        var observer = new MutationObserver(function(mutations) {
            mutations.forEach(function(mutation) {
                if (mutation.addedNodes.length) {
                    var hasNewCategory = false;
                    mutation.addedNodes.forEach(function(node) {
                        if (node.nodeType === 1 && (node.classList?.contains('postcat') || node.querySelectorAll?.('.postcat').length > 0)) {
                            hasNewCategory = true;
                        }
                    });
                    if (hasNewCategory) {
                        setTimeout(applyCategoryStyles, 200);
                    }
                }
            });
        });
        observer.observe(document.body, { childList: true, subtree: true });
    }
})();

/* === SEOTurbo Module 42: 42-ترجمة-محرك-ذكي.js === */

(function() {
    'use strict';
    const vault = document.getElementById('homepage-identity-vault');
    const blogName = (vault && vault.getAttribute('data-name')) ? vault.getAttribute('data-name') : "";
    let isProcessing = false;

    function sanitize(text) {
        if (!text) return '';
        return text.replace(/^_+/, '').replace(/\s+/g, ' ').trim();
    }
    function applyCategoryColors() {
        if (!window.seoturbo_label_dictionary) return;
        var blogColor = getComputedStyle(document.documentElement).getPropertyValue('--blogcolor').trim() || '#6366f1';
        document.querySelectorAll('.postcat').forEach(function(el) {
            el.style.backgroundColor = blogColor;
        });
    }
    function buildSmartMenu(container) {
        let html = '';
        const socials = document.querySelectorAll('.seoturbo-topbar-social-icons a');
        if (socials.length > 0) {
            html += `<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:20px;padding-bottom:20px;border-bottom:1px solid rgba(0,0,0,0.05);">`;
            const platforms = [
                'facebook', 'twitter', 'x', 'instagram', 'youtube', 'whatsapp', 'telegram', 
                'linkedin', 'pinterest', 'tiktok', 'messenger', 'snapchat', 'reddit', 
                'threads', 'discord', 'twitch', 'behance', 'github', 'rss', 'mailto:', 'tel:',
                'medium', 'mastodon', 'wattpad', 'forumotion'
            ];
            socials.forEach(s => { 
                let iconId = 'link'; 
                let href = s.href.toLowerCase();
                for (let p of platforms) { 
                    if (href.includes(p)) { 
                        iconId = p.replace(':', ''); 
                        if (iconId === 'mailto') iconId = 'email'; 
                        if (iconId === 'tel') iconId = 'phone'; 
                        break; 
                    } 
                }
                html += `<a href="${s.href}" target="_blank" class="social-circle" aria-label="Social Link"><svg width="18" height="18"><use href="#icon-${iconId}"/></svg></a>`; 
            });
            html += `</div>`;
        }
        const sourceMenu = document.getElementById('main-menu');
        if (sourceMenu) {
            html += '<div class="seoturbo-hamburger-section-title"><svg width="14" height="14" viewBox="0 0 512 512" style="fill: currentColor;"><use href="#icon-list"/></svg> الأقسام</div>';
            Array.from(sourceMenu.children).filter(el => el.tagName === 'LI').forEach(li => {
                const parentLink = li.querySelector('a');
                if (!parentLink) return;
                let iconHtml = parentLink.querySelector('svg')?.outerHTML || '<svg width="12" height="12" viewBox="0 0 320 512" style="fill: currentColor;"><use href="#icon-chevron-left"/></svg>';
                const text = sanitize(parentLink.textContent);
                const href = parentLink.getAttribute('href');
                const isRealLink = (href && href !== '#' && !href.includes('javascript'));
                if (li.classList.contains('has-sub')) {
                    const subMenuUl = li.querySelector('ul.sub-menu');
                    if (subMenuUl) {
                        html += `<div class="seoturbo-hamburger-parent"><div class="seoturbo-hamburger-parent-title" data-trigger="drop" role="button"><span>${iconHtml} ${text}</span><span class="arrow">▼</span></div><div class="seoturbo-hamburger-submenu">`;
                        subMenuUl.querySelectorAll('li > a').forEach(subA => {
                            let subIconHtml = subA.querySelector('svg')?.outerHTML || '<svg width="8" height="8" viewBox="0 0 448 512" style="fill: currentColor;"><use href="#icon-minus"/></svg>';
                            html += `<a class="seoturbo-hamburger-link" href="${subA.getAttribute('href')}">${subIconHtml} ${sanitize(subA.textContent)}</a>`;
                        });
                        html += `</div></div>`;
                    }
                } else { html += isRealLink ? `<a class="seoturbo-hamburger-link" href="${href}">${iconHtml} ${text}</a>` : `<span class="seoturbo-hamburger-link" role="button">${iconHtml} ${text}</span>`; }
            });
        }
        const staticLinks = document.querySelectorAll('.seoturbo-compact-nav a:not([onclick])');
        if (staticLinks.length > 0) {
            html += '<div class="seoturbo-hamburger-section" style="margin-top:20px;"><div class="seoturbo-hamburger-section-title"><svg width="14" height="14" viewBox="0 0 576 512" style="fill: currentColor;"><use href="#icon-file-alt"/></svg> معلومات</div>';
            staticLinks.forEach(page => { 
                let pageIconHtml = page.querySelector('svg')?.outerHTML || '<svg width="12" height="12" viewBox="0 0 576 512" style="fill: currentColor;"><use href="#icon-file-alt"/></svg>';
                html += `<a class="seoturbo-hamburger-link" href="${page.getAttribute('href')}">${pageIconHtml} ${sanitize(page.textContent)}</a>`; 
            });
            html += '</div>';
        }
        container.innerHTML = html;
        container.querySelectorAll('[data-trigger="drop"]').forEach(btn => {
            btn.onclick = (e) => {
                const submenu = btn.nextElementSibling;
                const isOpen = btn.classList.toggle('is-active-drop');
                submenu.style.display = isOpen ? 'flex' : 'none';
            };
        });
    }
    function runTurboEngine() {
        if (isProcessing) return;
        isProcessing = true;
        if (!window.seoturbo_dictionary_ready && (!window.seoturbo_label_dictionary || Object.keys(window.seoturbo_label_dictionary).length === 0)) {
            setTimeout(function() { isProcessing = false; runTurboEngine(); }, 300);
            return;
        }
        document.querySelectorAll('.postcat, .label-to-map, .seoterbo-frame-category-button span, .seoterbo-title-keyword-badge, .seoturbo-breadcrumbs-current, .bc-target, .section-header, .section-footer a').forEach(el => {
            let rawText = el.getAttribute('data-label') || el.textContent;
            let slug = rawText.replace(/^_+/, '').toLowerCase().trim();
            if (window.seoturbo_label_dictionary && window.seoturbo_label_dictionary[slug]) {
                const translated = window.seoturbo_label_dictionary[slug];
                for (let node of el.childNodes) {
                    if (node.nodeType === 3 && node.nodeValue.trim() !== "") {
                        node.nodeValue = translated;
                    }
                }
            } else {
                for (let node of el.childNodes) {
                    if (node.nodeType === 3 && node.nodeValue.includes('_')) {
                        node.nodeValue = node.nodeValue.replace(/^_+/, '');
                    }
                }
            }
        });
        document.querySelectorAll('a').forEach(link => {
            let pureText = (link.innerText || "").replace(/^_+/, '').replace(/\s+/g, ' ').trim();
            if (pureText) {
                if (link.href.includes('/search/label/')) {
                    link.setAttribute('title', "تصفح جميع موضوعات قسم " + pureText);
                } else if (link.classList.contains('PostEdit')) {
                    link.setAttribute('title', "تعديل هذا المقال");
                } else {
                    link.setAttribute('title', pureText);
                }
            }
        });
        applyCategoryColors();
        isProcessing = false;
    }
    runTurboEngine();
    if (window.MutationObserver) {
        let timer;
        new MutationObserver(() => { 
            if (!isProcessing) { clearTimeout(timer); timer = setTimeout(runTurboEngine, 300); }
        }).observe(document.body, { childList: true, subtree: true, characterData: true });
    }
    setTimeout(runTurboEngine, 1500);
})();

/* === SEOTurbo Module 43: 43-تفاعل-أزرار-التحكم.js === */

(function() {
    'use strict';

    const body = document.body;
    const darkModeIcons = {
        moon: '<svg class="icon icon-moon" style="width:18px;height:18px;"><use href="#icon-moon"/></svg>',
        sun: '<svg class="icon icon-sun" style="width:18px;height:18px;"><use href="#icon-sun"/></svg>'
    };

    const updateAllDarkIcons = (isDark) => {
        const icon = isDark ? darkModeIcons.sun : darkModeIcons.moon;
        ['seoturbo-dark-mode', 'seoturbo-darkModeHamburgerBtn', 'seoturbo-sticky-dark-mode-btn'].forEach(id => {
            const btn = document.getElementById(id);
            if (btn) btn.innerHTML = icon;
        });
    };

    const toggleDarkMode = () => {
        const isDark = body.classList.toggle('dark-mode');
        localStorage.setItem('seoturbo_theme', isDark ? 'dark' : 'light');
        updateAllDarkIcons(isDark);
    };

    const toggleSearch = (show) => {
        const overlay = document.getElementById('seoturbo-search-overlay');
        const input = document.getElementById('seoturbo-search-input');
        if (!overlay) return;
        if (show) {
            document.getElementById('seoturbo-closeMenuBtn')?.click();
            overlay.classList.add('is-active');
            if (input) setTimeout(() => input.focus(), 100);
            body.style.overflow = 'hidden';
        } else {
            overlay.classList.remove('is-active');
            body.style.overflow = '';
        }
    };

    const executeShare = () => {
        const url = window.location.href;
        if (navigator.share) {
            navigator.share({ title: document.title, url: url }).catch(() => {});
        } else {
            const temp = document.createElement('input');
            body.appendChild(temp);
            temp.value = url; temp.select();
            document.execCommand('copy');
            body.removeChild(temp);
            const toast = document.createElement('div');
            toast.className = 'seoturbo-share-toast';
            toast.innerHTML = '<svg width="14" height="14" viewBox="0 0 512 512" style="fill:currentColor;margin-left:5px;"><use href="#icon-check-circle"/></svg> تم نسخ الرابط بنجاح';
            toast.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:var(--blogcolor);color:#fff;padding:12px 25px;border-radius:40px;font-size:14px;z-index:1000001;display:flex;align-items:center;gap:8px;opacity:0;transition:opacity 0.3s;';
            body.appendChild(toast);
            requestAnimationFrame(() => {
                toast.style.opacity = '1';
                setTimeout(() => {
                    toast.style.opacity = '0';
                    setTimeout(() => toast.remove(), 300);
                }, 2000);
            });
        }
    };

    document.addEventListener('click', function(e) {
        const target = e.target;

        const darkBtn = target.closest('#seoturbo-dark-mode, #seoturbo-darkModeHamburgerBtn, #seoturbo-sticky-dark-mode-btn');
        if (darkBtn) {
            e.preventDefault();
            toggleDarkMode();
            return;
        }

        const searchBtn = target.closest('#seoturbo-search, #seoturbo-searchHamburgerBtn, #seoturbo-sticky-search-btn');
        if (searchBtn) {
            e.preventDefault();
            toggleSearch(true);
            return;
        }

        const shareBtn = target.closest('#seoturbo-share, #seoturbo-shareHamburgerBtn, #seoturbo-sticky-share-btn');
        if (shareBtn) {
            e.preventDefault();
            executeShare();
            return;
        }

        const homeBtn = target.closest('#seoturbo-home, #seoturbo-sticky-home-btn');
        if (homeBtn) {
            e.preventDefault();
            window.location.href = '/';
            return;
        }

        const closeSearch = target.closest('#seoturbo-search-close-btn');
        if (closeSearch || (target.id === 'seoturbo-search-overlay')) {
            toggleSearch(false);
        }
    });

    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') toggleSearch(false);
    });

    const savedTheme = localStorage.getItem('seoturbo_theme');
    if (savedTheme === 'dark') {
        body.classList.add('dark-mode');
        requestAnimationFrame(() => updateAllDarkIcons(true));
    }
})();

/* === SEOTurbo Module 44: 44-تفاعل-شريط-الكوكيز.js === */

(function(){
    'use strict';
    var cookieTriggered = false;
    var COOKIE_KEY = 'seoturbo_cookie_consent';
    var THREE_DAYS = 3 * 24 * 60 * 60 * 1000;

    function shouldShowBar() {
        var saved = localStorage.getItem(COOKIE_KEY);
        if (!saved) return true;
        var ts = parseInt(saved, 10);
        if (isNaN(ts)) return true;
        return (Date.now() - ts) >= THREE_DAYS;
    }

    function showCookieBar() {
        if (cookieTriggered) return;
        if (!shouldShowBar()) return;
        var bar = document.getElementById('cookieConsent');
        if (bar) {
            bar.classList.add('show');
            cookieTriggered = true;

            var acceptBtn = document.getElementById('acceptCookies');
            var rejectBtn = document.getElementById('rejectCookies');
            if (acceptBtn) acceptBtn.onclick = function(e) { 
                e.preventDefault(); 
                localStorage.setItem(COOKIE_KEY, Date.now().toString());
                hideCookieBar(); 
            };
            if (rejectBtn) rejectBtn.onclick = function(e) { 
                e.preventDefault(); 
                hideCookieBar(); 
            };
        }
    }

    function hideCookieBar() {
        var bar = document.getElementById('cookieConsent');
        if (bar) {
            bar.classList.remove('show');
        }
    }

    window.addEventListener('load', function() {
        setTimeout(showCookieBar, 8000); 
    });

    var userInteractions = ['mouseover', 'keydown', 'touchstart', 'scroll'];
    userInteractions.forEach(function(event) {
        window.addEventListener(event, showCookieBar, {once: true, passive: true});
    });

})();

/* === SEOTurbo Module 45: 45-تفاعل-غلق-الإعلانات-الجانبية.js  
<script>
function closeSideAd(side) {
  document.getElementById(side + &#39;-side-ads-container&#39;).style.display = &#39;none&#39;;
}
</script>       

46-تفاعل-ترقيم-الصفحات.js === */

(function() {
    'use strict';

    const config = {
        postperpage: window.ST_PP || 8, 
        numshowpage: 3, 
        upPageWord: "السابق",
        downPageWord: "التالي",
        home_page: window.location.origin
    };

    let targetPageNum = 1;
    let isInitialized = false;

    window.hitungtotaldata = function(json) {
        if (!json || !json.feed) return;
        const total = parseInt(json.feed.openSearch$totalResults.$t, 10);
        buildPagination(total);
    };

    function buildPagination(totaldata) {
        const thisUrl = window.location.href;
        let currentPage = 1;
        if (thisUrl.indexOf("#PageNo=") != -1) {
            currentPage = parseInt(thisUrl.substring(thisUrl.indexOf("#PageNo=") + 8));
        }

        let html = "";
        const halfShow = Math.floor(config.numshowpage / 2);
        let start = currentPage - halfShow;
        if (start < 1) start = 1;
        const maxPages = Math.ceil(totaldata / config.postperpage);
        let end = start + config.numshowpage - 1;
        if (end > maxPages) end = maxPages;

        if (currentPage > 1) {
            html += `<span class="showpage"><a href="#" onclick="goToPage(${currentPage - 1});return false" title="العودة إلى الصفحة السابقة (صفحة رقم ${currentPage - 1})">${config.upPageWord}</a></span>`;
        }

        for (let i = start; i <= end; i++) {
            if (currentPage == i) {
                html += `<span class="showpagePoint" title="أنت حالياً في الصفحة رقم ${i}">${i}</span>`;
            } else {
                html += `<span class="showpageNum"><a href="#" onclick="goToPage(${i});return false" title="الانتقال إلى الصفحة رقم ${i}">${i}</a></span>`;
            }
        }

        if (currentPage < maxPages) {
            html += `<span class="showpage"><a href="#" onclick="goToPage(${currentPage + 1});return false" title="الانتقال إلى الصفحة التالية (صفحة رقم ${currentPage + 1})">${config.downPageWord}</a></span>`;
        }

        const pagerContainer = document.getElementById("blog-pager");
        if (pagerContainer) {
            pagerContainer.innerHTML = html;
            pagerContainer.setAttribute('title', `مركز التنقل - إجمالي الصفحات: ${maxPages}`);
        }
    }

    window.goToPage = function(num) {
        targetPageNum = num; 
        const startIndex = (num - 1) * config.postperpage + 1;
        const labelPath = window.location.pathname.includes('/search/label/') ? '/-/' + window.location.pathname.split('/search/label/')[1].split('?')[0] : '';
        const fetchUrl = `${config.home_page}/feeds/posts/summary${labelPath}?start-index=${startIndex}&max-results=1&alt=json-in-script&callback=redirectWithTimestamp`;

        const script = document.createElement('script');
        script.src = fetchUrl;
        script.title = "جاري الانتقال...";
        document.body.appendChild(script);
    };

    window.redirectWithTimestamp = function(json) {
        if (!json.feed.entry) return;
        const entry = json.feed.entry[0];
        const publishedDate = entry.published.$t.substring(0, 19) + entry.published.$t.substring(23, 29);
        const timestamp = encodeURIComponent(publishedDate);
        const path = window.location.pathname.includes('/search/label/') ? '/search/label/' + window.location.pathname.split('/search/label/')[1].split('?')[0] : '/search';
        window.location.href = `${path}?updated-max=${timestamp}&max-results=${config.postperpage}#PageNo=${targetPageNum}`;
    };

    function runPaginationEngine() {
        if (isInitialized) return;
        isInitialized = true;

        const isHomepage = window.location.pathname === '/';

        if (isHomepage && window.ST_MASTER_PROMISE) {
            window.ST_MASTER_PROMISE.then(data => { 
                if(data) {
                    console.log('🚀 SEOTurbo: Pagination initialized via Global Engine (Zero Request)');
                    hitungtotaldata(data); 
                }
            });
        } else {
            const label = window.location.pathname.includes('/search/label/') ? '/-/' + window.location.pathname.split('/search/label/')[1].split('?')[0] : '';
            fetch(`${config.home_page}/feeds/posts/summary${label}?alt=json&max-results=1`)
                .then(r => r.json()).then(d => hitungtotaldata(d));
        }
    }

    const pagerTarget = document.getElementById('blog-pager');
    if (pagerTarget) {
        const observer = new IntersectionObserver((entries) => {
            if (entries[0].isIntersecting) {
                runPaginationEngine();
                observer.disconnect();
            }
        }, { rootMargin: '600px' });
        observer.observe(pagerTarget);
    }

})();

/* === SEOTurbo Module 47: 47-تفاعل-أزرار-حجم-خط-المقال.js === */

(function() {
    'use strict';
    let currentFontSize = 18;
    const storageKey = 'seoturbo_post_font_size';

    function initFontSizeControl() {
        const increaseBtn = document.querySelector('.increaseFont');
        const decreaseBtn = document.querySelector('.decreaseFont');
        const postBody = document.querySelector('.post-body.entry-content');

        if (!increaseBtn || !decreaseBtn || !postBody) return;

        const step = 2;
        const minSize = 14;
        const maxSize = 32;

        const savedSize = localStorage.getItem(storageKey);
        if (savedSize) {
            currentFontSize = parseInt(savedSize);
            postBody.style.fontSize = currentFontSize + 'px';
        }

        const updateFontSize = (direction) => {
            currentFontSize = Math.max(minSize, Math.min(maxSize, currentFontSize + (direction * step)));
            requestAnimationFrame(() => {
                postBody.style.fontSize = currentFontSize + 'px';
                localStorage.setItem(storageKey, currentFontSize);
            });
        };

        increaseBtn.onclick = (e) => { e.preventDefault(); updateFontSize(1); };
        decreaseBtn.onclick = (e) => { e.preventDefault(); updateFontSize(-1); };
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initFontSizeControl);
    } else {
        initFontSizeControl();
    }
})();

/* === SEOTurbo Module 48: 48-تفاعل-عداد-وسائل-التواصل-سايدبار.js === */

(function() {
    'use strict';
    function buildSTSocial() {
        document.querySelectorAll('.social-sidebar-inner a').forEach(link => {
            let data = link.getAttribute('title') || link.innerText || '';
            if (data.includes('[') && data.includes(']')) {
                const parts = data.split('[');
                const brand = parts[0].trim();
                const count = parts[1].replace(']', '').trim();
                const cleanBrand = brand.charAt(0).toUpperCase() + brand.slice(1);
                link.title = cleanBrand + ' - ' + count; 
                link.setAttribute('aria-label', cleanBrand + ' ' + count);
                link.setAttribute('data-count', count);
                const iconId = brand.toLowerCase();
                link.innerHTML = `<svg class="st-svg-icon"><use href="#icon-${iconId}"/></svg>`;
                link.classList.add('st-stacked-btn', iconId);
            }
        });
    }
    buildSTSocial();
    window.addEventListener('load', buildSTSocial);
})();

/* === SEOTurbo Module 49: 49-تفاعل-محرر-التعليقات.js === */

(function() {
    'use strict';

    var freeContainer = document.getElementById('seoturbo-comments-placeholder');
    var originalContainer = document.getElementById('comments-section-original');

    if (freeContainer) freeContainer.style.display = 'none';
    if (originalContainer) originalContainer.style.display = 'block';

    let commentsLoaded = false;

    function loadBloggerComments() {
        if (commentsLoaded) return;

        const editor = document.getElementById('comment-editor');
        const source = document.getElementById('comment-editor-src');
        const container = document.getElementById('seoturbo-dynamic-js-comments');

        if (editor && source && source.href) {
            editor.setAttribute('src', source.href);

            if (container) {
                const bloggerJS = document.createElement('script');
                bloggerJS.src = 'https://www.blogger.com/static/v1/jsbin/2836230691-comment_from_post_iframe.js';
                bloggerJS.async = true;
                container.appendChild(bloggerJS);
            }

            commentsLoaded = true;
            console.log('✅ SEOTurbo: تم كسر سلسلة طلبات التعليقات وتحميلها بنجاح');
        }
    }

    function initLazyComments() {
        const target = document.querySelector('.commentsection');
        if (!target) return;

        if ('IntersectionObserver' in window) {
            const observer = new IntersectionObserver((entries) => {
                if (entries[0].isIntersecting) {
                    loadBloggerComments();
                    observer.disconnect();
                }
            }, { rootMargin: '500px' });
            observer.observe(target);
        } else {
            window.addEventListener('load', () => setTimeout(loadBloggerComments, 5000));
        }
    }

    initLazyComments();
})();

/* === SEOTurbo Module 50: 50-تفاعل-مزامنة-دور-الكاتب.js === */

(function() {
    'use strict';

    var freeContainer = document.getElementById('seoturbo-author-role-placeholder');
    if(freeContainer) freeContainer.remove();

    function syncAuthorRole() {
        const authorDescEl = document.querySelector('.author-desc');
        const roleTarget = document.querySelector('.seoterbo-title-writer-role');
        if (authorDescEl && roleTarget) {
            const fullText = authorDescEl.textContent.trim();
            if (fullText.includes('|')) {
                const dynamicRole = fullText.split('|')[0].trim();
                if (dynamicRole.length > 0) {
                    roleTarget.textContent = dynamicRole;
                }
            }
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', syncAuthorRole);
    } else {
        syncAuthorRole();
    }
    setTimeout(syncAuthorRole, 500);
})();

/* === SEOTurbo Module 51: 51-تفاعل-القائمة-الجانبية.js === */

(function() {
    'use strict';

    var freePopup = document.getElementById('seoturbo-side-nav-free-popup');
    if (freePopup) freePopup.remove();

    const sideNavBtn = document.getElementById('openSideNavBtn');
    const stickySideNavBtn = document.getElementById('stickySideNavBtn');
    const sideNav = document.getElementById('seoturboSideNav');
    const closeBtn = document.getElementById('closeSideNavBtn');
    const overlay = document.getElementById('sideNavOverlay');

    if (!sideNav || !closeBtn || !overlay) return;

    function syncSocialFromSidebar() {
        const sideNavSocialContainer = document.querySelector('.seoturbo-side-nav-social');
        const sidebarSocialSource = document.querySelector('.social-sidebar-inner');
        if (sideNavSocialContainer && sidebarSocialSource) {
            sideNavSocialContainer.innerHTML = '';
            Array.from(sidebarSocialSource.children).forEach(item => {
                const clone = item.cloneNode(true);
                clone.classList.remove('st-stacked-btn');
                clone.removeAttribute('data-count');
                sideNavSocialContainer.appendChild(clone);
            });
        } else if (sideNavSocialContainer) {
            const headerSocial = document.querySelector('.seoturbo-topbar-social-icons');
            if (headerSocial) sideNavSocialContainer.innerHTML = headerSocial.innerHTML;
        }
    }

    function openSideNav() {
        sideNav.classList.add('open');
        overlay.classList.add('active');
        document.body.style.overflow = 'hidden';
        syncSocialFromSidebar();
    }

    function closeSideNav() {
        sideNav.classList.remove('open');
        overlay.classList.remove('active');
        document.body.style.overflow = '';
    }

    if (sideNavBtn) sideNavBtn.addEventListener('click', openSideNav);
    if (stickySideNavBtn) stickySideNavBtn.addEventListener('click', openSideNav);

    closeBtn.addEventListener('click', closeSideNav);
    overlay.addEventListener('click', closeSideNav);

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && sideNav.classList.contains('open')) closeSideNav();
    });

    function buildSideMenu() {
        const menuContainer = document.getElementById('sideNavMenuContent');
        if (!menuContainer) return;
        let html = '';
        const sourceMenu = document.getElementById('main-menu');
        if (sourceMenu) {
            Array.from(sourceMenu.children).forEach(li => {
                if (li.tagName !== 'LI') return;
                const parentLink = li.querySelector('a');
                if (!parentLink) return;
                let iconHtml = parentLink.querySelector('svg') ? parentLink.querySelector('svg').outerHTML : '<svg width="16" height="16" viewBox="0 0 320 512" style="fill: currentColor;"><use href="#icon-chevron-left"/></svg>';
                const text = parentLink.textContent.trim();
                const href = parentLink.getAttribute('href');
                if (li.classList.contains('has-sub')) {
                    const subMenuUl = li.querySelector('ul.sub-menu');
                    if (subMenuUl) {
                        html += `<div class="seoturbo-hamburger-parent"><div class="seoturbo-hamburger-parent-title" data-trigger="drop"><span>${iconHtml} ${text}</span><span class="arrow">▼</span></div><div class="seoturbo-hamburger-submenu">`;
                        subMenuUl.querySelectorAll('li > a').forEach(subA => {
                            let subIconHtml = subA.querySelector('svg') ? subA.querySelector('svg').outerHTML : '<svg width="12" height="12" viewBox="0 0 448 512" style="fill: currentColor;"><use href="#icon-minus"/></svg>';
                            html += `<a class="seoturbo-hamburger-link" href="${subA.getAttribute('href')}">${subIconHtml} ${subA.textContent.trim()}</a>`;
                        });
                        html += `</div></div>`;
                    }
                } else {
                    html += `<a class="seoturbo-hamburger-link" href="${href}">${iconHtml} ${text}</a>`;
                }
            });
        }
        menuContainer.innerHTML = html;
        menuContainer.querySelectorAll('[data-trigger="drop"]').forEach(btn => {
            btn.onclick = (e) => {
                e.preventDefault();
                const submenu = btn.nextElementSibling;
                const isOpen = btn.classList.toggle('is-open');
                submenu.style.display = isOpen ? 'block' : 'none';
            };
        });
    }

    const popularContainer = document.getElementById('sideNavPopularPosts');
    if (popularContainer && window.ST_MASTER_PROMISE) {
        window.ST_MASTER_PROMISE.then(data => {
            if (data && data.feed && data.feed.entry) {
                let html = '';
                const months = ['يناير', 'فبراير', 'مارس', 'إبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'];
                data.feed.entry.slice(0, 5).forEach(post => {
                    const title = post.title.$t;
                    const link = post.link.find(l => l.rel === 'alternate').href;
                    const img = window.optimizeImage ? window.optimizeImage(post.media$thumbnail ? post.media$thumbnail.url : '', 'related') : 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEi7Ml848_trMe4J1co6ImpiKh7XcXn2ZsRTk85hy4oWOlBvvOIyHTSxoC1nvNwlZ0-PvMwjQFVEcqhA0H2dGcz-fWO9il9RlsmpXX8I7RLYt6y7kPb9cE2fKnBqdD7gvbSTfLfoSjCZs_brqPRiw335YfX5qGHS8iNYIHCBNUo1npNK3o8Oxtob-KxZeBk/s16000-rw/rbka-news300-100.webp';
                    const date = new Date(post.published.$t);
                    const dateStr = date.getDate() + ' ' + months[date.getMonth()] + ' ' + date.getFullYear();
                    html += `
                        <a class='seoturbo-side-nav-popular-item' href='${link}'>
                            <div class='seoturbo-side-nav-popular-thumb'><img src='${img}' alt='${title.replace(/"/g, '&quot;')}' loading='lazy'></div>
                            <div class='seoturbo-side-nav-popular-info'>
                                <div class='seoturbo-side-nav-popular-title'>${title}</div>
                                <div class='seoturbo-side-nav-popular-date'><svg height='10' viewBox='0 0 512 512' width='10'><use href='#icon-clock'/></svg> <span>${dateStr}</span></div>
                            </div>
                        </a>`;
                });
                popularContainer.innerHTML = html;
            }
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            buildSideMenu();
            syncSocialFromSidebar();
        });
    } else {
        buildSideMenu();
        syncSocialFromSidebar();
    }
})();

/* === SEOTurbo Module 52: 52-تفاعل-المفضلة.js === */

(function() {
    'use strict';

    var freePopup = document.getElementById('favFreePopup');
    var freeBtn = document.getElementById('favFreeBtn');
    var originalFav = document.getElementById('fav-original-box');

    if (freePopup) freePopup.style.display = 'none';
    if (freeBtn) freeBtn.style.display = 'none';
    if (originalFav) originalFav.style.display = 'block';

    const SEOTURBO_STORAGE_KEY = 'seoturbo_favorites_v11';

    function getFavs() {
        return JSON.parse(localStorage.getItem(SEOTURBO_STORAGE_KEY) || '[]');
    }

    function saveFavs(favs) {
        localStorage.setItem(SEOTURBO_STORAGE_KEY, JSON.stringify(favs));
        updateAllFavButtons();
        updateFavCounters();
    }

    function updateAllFavButtons() {
        const favs = getFavs();

        const postActionBtn = document.getElementById('seoturbo-postFavAction');
        if (postActionBtn) {
            const isSaved = favs.some(f => f.id === postActionBtn.dataset.id);
            postActionBtn.classList.toggle('is-saved', isSaved);
            const svgUse = postActionBtn.querySelector('use');
            if (svgUse) svgUse.setAttribute('href', isSaved ? '#icon-fav-full' : '#icon-fav-empty');
            const textSpan = postActionBtn.querySelector('.seoturbo-fav-text');
            if (textSpan) textSpan.textContent = isSaved ? 'تم الحفظ في مفضلتك' : 'حفظ في المفضلة';
        }

        document.querySelectorAll('.Posts-byCategory .seoturbo-post-add-fav').forEach(btn => {
            const isSaved = favs.some(f => f.id === btn.dataset.id);
            btn.classList.toggle('is-saved', isSaved);
            const svgUse = btn.querySelector('use');
            if (svgUse) svgUse.setAttribute('href', isSaved ? '#icon-fav-full' : '#icon-fav-empty');
            const textSpan = btn.querySelector('.seoturbo-fav-text');
            if (textSpan) textSpan.textContent = isSaved ? 'تم الحفظ في مفضلتك' : 'حفظ في المفضلة';
        });

        document.querySelectorAll('#seoturbo-leadership-slider .seoturbo-post-add-fav').forEach(btn => {
            const isSaved = favs.some(f => f.id === btn.dataset.id);
            btn.classList.toggle('is-saved', isSaved);
            const svgUse = btn.querySelector('use');
            if (svgUse) svgUse.setAttribute('href', isSaved ? '#icon-fav-full' : '#icon-fav-empty');
            const textSpan = btn.querySelector('.seoturbo-fav-text');
            if (textSpan) textSpan.textContent = isSaved ? 'تم الحفظ' : 'حفظ';
        });

        document.querySelectorAll('.seoturbo-main-tool-grid .seoturbo-post-add-fav').forEach(btn => {
            const isSaved = favs.some(f => f.id === btn.dataset.id);
            btn.classList.toggle('is-saved', isSaved);
            const svgUse = btn.querySelector('use');
            if (svgUse) svgUse.setAttribute('href', isSaved ? '#icon-fav-full' : '#icon-fav-empty');
        });
    }

    function updateFavCounters() {
        const favs = getFavs();
        document.querySelectorAll('#seoturbo-favCount, #seoturbo-favCountSticky').forEach(b => {
            b.textContent = favs.length;
            b.style.display = 'flex';
        });

        const stickyIcon = document.querySelector('#seoturbo-openFavBtnSticky use');
        if (stickyIcon) stickyIcon.setAttribute('href', favs.length > 0 ? '#icon-fav-full' : '#icon-fav-empty');
    }

    function toggleFav(data, btnElement) {
        let favs = getFavs();
        const exists = favs.some(f => f.id === data.id);

        if (exists) {
            favs = favs.filter(f => f.id !== data.id);
            showToast('❌ تمت الإزالة من المفضلة');
        } else {
            favs.push(data);
            showToast('✅ تم الحفظ في المفضلة');
        }

        saveFavs(favs);

        if (btnElement) {
            const isSaved = !exists;
            btnElement.classList.toggle('is-saved', isSaved);
            const svgUse = btnElement.querySelector('use');
            if (svgUse) svgUse.setAttribute('href', isSaved ? '#icon-fav-full' : '#icon-fav-empty');
            const textSpan = btnElement.querySelector('.seoturbo-fav-text');
            if (textSpan) {
                const isInSlider = btnElement.closest('#seoturbo-leadership-slider') !== null;
                if (isInSlider) {
                    textSpan.textContent = isSaved ? 'تم الحفظ' : 'حفظ';
                } else {
                    textSpan.textContent = isSaved ? 'تم الحفظ في مفضلتك' : 'حفظ في المفضلة';
                }
            }
        }
    }

    function renderFavList() {
        const container = document.getElementById('seoturbo-favListContainer');
        if (!container) return;

        const favs = getFavs();
        if (favs.length === 0) {
            container.innerHTML = '<div class="seoturbo-fav-empty-msg">✨ قائمة المفضلة فارغة حالياً</div>';
            return;
        }

        container.innerHTML = favs.map(f => `
            <div class="seoturbo-fav-item">
                <img src="${f.img}" alt="${f.title}" loading="lazy">
                <div class="seoturbo-fav-item-info">
                    <a href="${f.url}" class="seoturbo-fav-item-title">${f.title}</a>
                </div>
                <div class="seoturbo-fav-item-remove" onclick="window.removeSeoturboFav('${f.id}')" title="إزالة من المفضلة">
                    <svg width="14" height="14" viewBox="0 0 448 512" fill="currentColor"><path d="M432 32H312l-9.4-18.7A24 24 0 0 0 281.1 0H166.8a23.7 23.7 0 0 0-21.4 13.3L136 32H16A16 16 0 0 0 0 48v32a16 16 0 0 0 16 16h416a16 16 0 0 0 16-16V48a16 16 0 0 0-16-16zM53.2 467a48 48 0 0 0 47.9 45h245.8a48 48 0 0 0 47.9-45L416 128H32z"/></svg>
                </div>
            </div>
        `).join('');
    }

    window.removeSeoturboFav = function(id) {
        let favs = getFavs();
        favs = favs.filter(f => f.id !== id);
        saveFavs(favs);
        renderFavList();
        showToast('❌ تمت الإزالة من المفضلة');
    };

    function showToast(msg) {
        const oldToast = document.querySelector('.seoturbo-fav-toast');
        if (oldToast) oldToast.remove();

        const toast = document.createElement('div');
        toast.className = 'seoturbo-fav-toast';
        toast.style.cssText = 'position:fixed;bottom:80px;right:30px;background:var(--blogcolor);color:#fff;padding:12px 25px;border-radius:12px;z-index:10000001;box-shadow:0 10px 20px rgba(0,0,0,0.2);font-weight:bold;';
        toast.textContent = msg;
        document.body.appendChild(toast);
        setTimeout(() => { 
            toast.style.opacity = '0'; 
            toast.style.transition = 'opacity 0.3s';
            setTimeout(() => toast.remove(), 500); 
        }, 2500);
    }

    document.addEventListener('click', function(e) {
        const favBtn = e.target.closest('.seoturbo-post-add-fav');
        if (favBtn && favBtn.dataset.id) {
            e.preventDefault();
            const data = {
                id: favBtn.dataset.id,
                title: favBtn.dataset.title,
                url: favBtn.dataset.url,
                img: favBtn.dataset.img || 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEi7Ml848_trMe4J1co6ImpiKh7XcXn2ZsRTk85hy4oWOlBvvOIyHTSxoC1nvNwlZ0-PvMwjQFVEcqhA0H2dGcz-fWO9il9RlsmpXX8I7RLYt6y7kPb9cE2fKnBqdD7gvbSTfLfoSjCZs_brqPRiw335YfX5qGHS8iNYIHCBNUo1npNK3o8Oxtob-KxZeBk/s16000-rw/rbka-news300-100.webp'
            };
            toggleFav(data, favBtn);
        }

        if (e.target.closest('#seoturbo-openFavBtn') || e.target.closest('#seoturbo-openFavBtnSticky')) {
            e.preventDefault();
            renderFavList();
            const modal = document.getElementById('seoturbo-favModal');
            if (modal) {
                modal.classList.add('active');
                document.body.style.overflow = 'hidden';
            }
        }

        if (e.target.id === 'seoturbo-favModal' || e.target.id === 'seoturbo-closeFavModal') {
            const modal = document.getElementById('seoturbo-favModal');
            if (modal) {
                modal.classList.remove('active');
                document.body.style.overflow = '';
            }
        }

        if (e.target.id === 'seoturbo-clearAllFavs') {
            if (confirm('⚠️ هل أنت متأكد من مسح قائمة المفضلة بالكامل؟')) {
                saveFavs([]);
                renderFavList();
                showToast('🗑️ تم مسح قائمة المفضلة بالكامل');
            }
        }
    });

    updateAllFavButtons();
    updateFavCounters();
})();

/* === SEOTurbo Module 53: 53-تفاعل-الإشعارات.js === */

(function() {
    'use strict';

    var freePopup = document.getElementById('seoturbo-notif-free-popup');
    if (freePopup) freePopup.remove();

    const NOTIF_CONFIG = {
        storageKey: 'seoturbo_last_visit'
    };

    async function checkNotifications() {
        try {
            if (!window.ST_MASTER_PROMISE) return;
            const data = await window.ST_MASTER_PROMISE;
            if(!data||!data.feed||!data.feed.entry) return;

            const entries = data.feed.entry.slice(0, 5);
            const lastVisit = localStorage.getItem(NOTIF_CONFIG.storageKey) || 0;

            let newCount = 0;
            let listHtml = '';

            entries.forEach(post => {
                const postDate = new Date(post.published.$t).getTime();
                if (postDate > lastVisit) newCount++;

                const title = post.title.$t;
                const link = post.link.find(l => l.rel === 'alternate').href;
                const rawImg = post.media$thumbnail ? post.media$thumbnail.url : 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEi7Ml848_trMe4J1co6ImpiKh7XcXn2ZsRTk85hy4oWOlBvvOIyHTSxoC1nvNwlZ0-PvMwjQFVEcqhA0H2dGcz-fWO9il9RlsmpXX8I7RLYt6y7kPb9cE2fKnBqdD7gvbSTfLfoSjCZs_brqPRiw335YfX5qGHS8iNYIHCBNUo1npNK3o8Oxtob-KxZeBk/s16000-rw/rbka-news300-100.webp';
                const img = window.optimizeImage ? window.optimizeImage(rawImg, 'related') : rawImg;
                const dateText = new Date(post.published.$t).toLocaleDateString('ar-EG', {day:'numeric', month:'long'});

                listHtml += `
                    <a href="${link}" class="seoturbo-notif-item">
                        <img src="${img}" class="seoturbo-notif-img" loading="lazy">
                        <div class="seoturbo-notif-info">
                            <span class="seoturbo-notif-title">${title}</span>
                            <div class="seoturbo-notif-meta">
                                <span>📅 ${dateText}</span>
                                ${postDate > lastVisit ? '<span style="color:var(--google-red)">● جديد</span>' : ''}
                            </div>
                        </div>
                    </a>`;
            });

            const badges = document.querySelectorAll('.seoturbo-notif-badge');
            badges.forEach(b => {
                b.textContent = newCount;
                b.style.display = 'flex';
            });

            const container = document.getElementById('seoturbo-notifContainer');
            if (container) container.innerHTML = listHtml || '<div class="seoturbo-notif-empty">لا توجد تحديثات حالياً</div>';

        } catch (e) { console.warn('Notif Error:', e); }
    }

    function markAsRead() {
        localStorage.setItem(NOTIF_CONFIG.storageKey, Date.now());
        const badges = document.querySelectorAll('.seoturbo-notif-badge');
        badges.forEach(b => b.style.display = 'none');
    }

    document.addEventListener('click', function(e) {
        if (e.target.closest('.seoturbo-notif-btn')) {
            document.getElementById('seoturbo-notifModal').classList.add('active');
            document.body.style.overflow = 'hidden';
            markAsRead();
        }

        if (e.target.closest('#seoturboNotifMoveBtn')) {
            e.preventDefault();
            document.getElementById('seoturbo-notifModal').classList.add('active');
            document.body.style.overflow = 'hidden';
            markAsRead();
        }

        if (e.target.id === 'seoturbo-notifModal' || e.target.id === 'seoturbo-notifClose') {
            document.getElementById('seoturbo-notifModal').classList.remove('active');
            document.body.style.overflow = '';
        }
    });

    checkNotifications();
})();

/* === SEOTurbo Module 54: 54-تفاعل-السابق-التالى-نهاية-المقال.js === */

(function() {
    'use strict';

    var freeContainer = document.getElementById('seoturbo-postnav-placeholder');
    var originalContainer = document.getElementById('seoturbo-postnav-original');

    if (freeContainer) freeContainer.style.display = 'none';
    if (originalContainer) originalContainer.style.display = 'block';

    (async function() {
        if (!window.ST_MASTER_PROMISE) return;
        const currentUrl = window.location.href;
        const data = await window.ST_MASTER_PROMISE;
        if (!data || !data.feed.entry) return;

        const posts = data.feed.entry;

        let currentIndex = -1;
        for (let i = 0; i < posts.length; i++) {
            const postUrl = posts[i].link.find(l => l.rel === 'alternate').href;
            if (postUrl === currentUrl || currentUrl.includes(postUrl.split('?')[0])) {
                currentIndex = i;
                break;
            }
        }

        if (currentIndex === -1) return;

        const prevPost = posts[currentIndex - 1];
        const nextPost = posts[currentIndex + 1];

        function getSiteFavicon() {
            const faviconLink = document.querySelector('link[rel="icon"], link[rel="shortcut icon"]');
            if (faviconLink && faviconLink.href) return faviconLink.href;
            return window.location.origin + '/favicon.ico';
        }

        const siteFavicon = getSiteFavicon();

        function fillNavData(containerId, post) {
            const container = document.getElementById(containerId);
            if (!container) return;

            if (!post) {
                container.style.display = 'none';
                return;
            }

            const link = container.querySelector('a');
            const titleEl = container.querySelector('.seoturbo-article-nav-title');
            const imgContainer = container.querySelector('.seoturbo-article-nav-img');

            if (link) {
                link.href = post.link.find(l => l.rel === 'alternate').href;
                link.style.cursor = 'pointer';
                link.style.opacity = '1';
                link.style.pointerEvents = 'auto';
            }
            if (titleEl) titleEl.textContent = post.title.$t;

            if (imgContainer) {
                let rawImg = post.media$thumbnail ? post.media$thumbnail.url : siteFavicon;
                const optimizedImg = window.optimizeImage ? window.optimizeImage(rawImg, 'related') : rawImg;
                imgContainer.innerHTML = '<img src="' + optimizedImg + '" alt="' + post.title.$t.replace(/"/g, '&quot;') + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">';
            }
        }

        fillNavData('seoturbo-prev-loader', prevPost);
        fillNavData('seoturbo-next-loader', nextPost);
    })();
})();

/* === SEOTurbo Module 55: 55-تفاعل-شاهد-أيضا.js === */

(function() {
    'use strict';

    var freeCapsule = document.getElementById('seoturbo-capsule-placeholder');
    if (freeCapsule) freeCapsule.remove();

    const capsule = document.getElementById('seoturbo-see-more-capsule');
    if (!capsule) return;
    const isPostPage = document.body.classList.contains('post-page');
    let isClosed = false;
    let isMinimized = false;
    const triggerPoint = isPostPage ? 0.35 : 0.8;
    const contentContainer = document.getElementById('capsule-content-container');
    async function populateCapsule() {
        if (contentContainer.hasAttribute('data-loaded')) return;
        try {
            if (!window.ST_MASTER_PROMISE) return;
            const data = await window.ST_MASTER_PROMISE;
            if (!data || !data.feed.entry) return;
            const currentUrl = window.location.href.split(/[?#]/)[0];
            const posts = data.feed.entry.filter(post => {
                const postUrl = (post.link.find(l => l.rel === 'alternate') || {}).href;
                return postUrl && postUrl.split(/[?#]/)[0] !== currentUrl;
            }).slice(0, 4);
            if (posts.length > 0) {
                let html = '';
                posts.forEach(post => {
                    const title = post.title.$t;
                    const link = (post.link.find(l => l.rel === 'alternate') || {}).href;
                    const rawImg = post.media$thumbnail ? post.media$thumbnail.url : 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEi7Ml848_trMe4J1co6ImpiKh7XcXn2ZsRTk85hy4oWOlBvvOIyHTSxoC1nvNwlZ0-PvMwjQFVEcqhA0H2dGcz-fWO9il9RlsmpXX8I7RLYt6y7kPb9cE2fKnBqdD7gvbSTfLfoSjCZs_brqPRiw335YfX5qGHS8iNYIHCBNUo1npNK3o8Oxtob-KxZeBk/s16000-rw/rbka-news300-100.webp';
                    const img = window.optimizeImage ? window.optimizeImage(rawImg, 'related') : rawImg;
                    html += `<a class="capsule-post" href="${link}" title="${title.replace(/"/g, '&quot;')}"><div class="capsule-post-thumb"><img src="${img}" alt="${title.replace(/"/g, '&quot;')}" loading="lazy"></div><div class="capsule-post-info"><h4 class="capsule-post-title">${title}</h4></div></a>`;
                });
                contentContainer.innerHTML = html;
                contentContainer.setAttribute('data-loaded', 'true');
            }
        } catch (error) { console.error('Capsule Error:', error); }
    }
    function handleScroll() {
        if (isClosed) return;
        let shouldShow = false;
        if (isPostPage) {
            const postBody = document.querySelector('.post-body');
            if (postBody) {
                const rect = postBody.getBoundingClientRect();
                const scrollPosition = window.innerHeight - rect.top;
                const bodyHeight = rect.height;
                if (scrollPosition > (bodyHeight * triggerPoint)) shouldShow = true;
            }
        } else {
            if (window.scrollY > 1000) shouldShow = true;
        }
        if (shouldShow) {
            capsule.style.display = 'block';
            requestAnimationFrame(() => {
                capsule.classList.add('visible');
                populateCapsule();
            });
        } else {
            capsule.classList.remove('visible');
        }
    }
    document.getElementById('capsule-close').onclick = () => {
        isClosed = true;
        capsule.classList.remove('visible');
        setTimeout(() => { capsule.style.display = 'none'; }, 500);
    };
    const minBtn = document.getElementById('capsule-minimize');
    minBtn.onclick = () => {
        isMinimized = !isMinimized;
        capsule.classList.toggle('minimized', isMinimized);
        minBtn.innerHTML = isMinimized ? '&#43;' : '&#8722;';
        minBtn.title = isMinimized ? 'تكبير' : 'تصغير';
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    document.addEventListener('seoturbo-cp-apply', function() {
        if (!isClosed) {
            requestAnimationFrame(function() {
                capsule.classList.add('visible');
                capsule.style.display = 'block';
                populateCapsule();
            });
        }
    });
})();

/* === SEOTurbo Module 56: 56-تفاعل-تقرير-جودة-محتوى-مقالات.js === */

(function() {
    'use strict';

    var freePopup = document.getElementById('seoturbo-quality-free-popup');
    var freeBtn = document.getElementById('seoturbo-quality-free-btn');
    var originalQuality = document.getElementById('quality-report-original');

    if (freePopup) freePopup.style.display = 'none';
    if (freeBtn) freeBtn.style.display = 'none';
    if (originalQuality) originalQuality.style.display = 'block';

    if (!document.querySelector('.post-body')) return;
    if (window.seoturboQualityLoaded) return;

    function getSecretPassword() {
        var metaTag = document.querySelector('meta[name="seoturbo-quality-password"]');
        if (metaTag && metaTag.getAttribute('content')) {
            return metaTag.getAttribute('content');
        }
        return '1234';
    }

    function analyzeContentQuality() {
        var postBody = document.querySelector('.post-body.entry-content') || document.querySelector('.post-body');
        if (!postBody) return null;

        var text = postBody.innerText || postBody.textContent;
        var wordCount = text.split(/\s+/).length;
        var paragraphs = postBody.querySelectorAll('p');
        var images = postBody.querySelectorAll('img:not(.author-img)');
        var allLinks = postBody.querySelectorAll('a[href*="/"]');

        var score = 0;
        var maxScore = 0;
        var details = [];

        var check = function(name, val, target, weight) {
            maxScore += weight;
            var isPass = val >= target;
            var s = isPass ? weight : (val > 0 ? Math.floor(weight/2) : 0);
            score += s;
            details.push({
                name: name,
                score: s,
                max: weight,
                status: isPass ? 'pass' : (val > 0 ? 'warning' : 'fail')
            });
        };

        check('بيانات Schema المنظمة', !!document.querySelector('script[type="application/ld+json"]'), 1, 5);
        check('طول المقال (كلمات)', wordCount, 800, 10);
        check('العناوين الفرعية H2-H4', postBody.querySelectorAll('h2, h3, h4').length, 3, 7);
        check('وسوم الكلمات المفتاحية', document.querySelectorAll('.post-tags-container a').length, 3, 5);
        check('وصف الميتا (Description)', (document.querySelector('meta[name="description"]')?.content.length || 0), 100, 4);
        check('روابط ذكية (Auto Links)', document.querySelectorAll('.auto-internal-link').length, 1, 3);

        var intLinks = Array.from(allLinks).filter(function(l) { return l.href.includes(window.location.hostname); }).length;
        check('الروابط الداخلية', intLinks, 3, 6);

        var highTrust = ['.gov', '.edu', 'wikipedia.org', 'google.com', 'who.int'];
        var extLinks = Array.from(allLinks).filter(function(l) { return !l.href.includes(window.location.hostname) && l.href.startsWith('http'); });
        var hasTrust = extLinks.some(function(l) { return highTrust.some(function(d) { return l.href.includes(d); }); });
        check('مصادر خارجية موثوقة', hasTrust ? 1 : 0, 1, 5);

        check('الاستشهادات والمراجع', postBody.querySelectorAll('a[id^="cite"], .reference').length, 1, 4);
        check('توثيق هوية الكاتب', !!document.getElementById('author-box-fixed'), 1, 3);
        check('ارتباط سياسة الخصوصية', document.querySelectorAll('a[href*="privacy"], a[href*="policy"]').length, 1, 3);
        check('تاريخ التحديث الأخير', (document.getElementById('seoturbo-data-vault')?.getAttribute('data-mod') ? 1 : 0), 1, 3);

        check('جدول المحتويات (TOC)', !!document.getElementById('tocDiv'), 1, 6);
        check('تأطير الصورة الرئيسية', !!document.querySelector('.seoterbo-frame-root-container'), 1, 5);

        var imgsWithAlt = Array.from(images).filter(function(img) { return img.alt && img.alt.length > 5; }).length;
        check('نصوص الصور البديلة (Alt)', images.length > 0 ? (imgsWithAlt / images.length) : 1, 0.8, 6);

        check('توازن النص والوسائط', (images.length >= 1 && wordCount > 400 ? 1 : 0), 1, 4);
        check('المحتوى المرئي (فيديو)', (postBody.querySelector('iframe[src*="youtube"], video') ? 1 : 0), 1, 4);
        check('صورة المشاركة (OG)', !!document.querySelector('meta[property="og:image"]'), 1, 3);

        check('سهولة القراءة (فقرات)', (text.length / (paragraphs.length || 1) < 500 ? 1 : 0), 1, 4);
        check('قوة الفقرة الاستهلالية', (paragraphs[0]?.innerText.length > 80 ? 1 : 0), 1, 3);

        var hasConclusion = /ختاماً|الخلاصة|في النهاية|نتمنى/.test(text);
        check('خاتمة الموضوع', hasConclusion ? 1 : 0, 1, 3);

        check('استخدام القوائم (Lists)', postBody.querySelectorAll('ul, ol').length, 1, 3);
        check('اقتباسات مرجعية', postBody.querySelectorAll('blockquote').length, 1, 2);
        check('الأسئلة الشائعة (FAQ)', (document.querySelector('#qa-section-placeholder') ? 1 : 0), 1, 3);

        var finalPercentage = Math.round((score / maxScore) * 100);
        var sealID = finalPercentage.toString(16).toUpperCase() + Date.now().toString(36).toUpperCase().slice(-3);

        return { 
            score: finalPercentage, passed: finalPercentage >= 60, sealID: sealID, 
            wordCount: wordCount, imageCount: images.length, intLinks: intLinks, extLinks: extLinks.length,
            details: details, title: document.querySelector('h1.seoterbo-title-main-headline')?.textContent.trim()
        };
    }

    function getQualityLevel(score) {
        if (score >= 90) return { level: 'إمبراطوري', color: '#4caf50', icon: '🏆' };
        if (score >= 75) return { level: 'احترافي', color: '#8bc34a', icon: '✅' };
        if (score >= 60) return { level: 'جيد', color: '#ffc107', icon: '✓' };
        return { level: 'ضعيف', color: '#f44336', icon: '⚠️' };
    }

    function updateQualitySystem() {
        var res = analyzeContentQuality();
        if (!res) return;

        var level = getQualityLevel(res.score);

        var container = document.getElementById('seoturboQualityContainer');
        if (container) {
            container.style.display = res.passed ? 'block' : 'none';
            var certIdEl = document.getElementById('qualityCertId');
            if (certIdEl) certIdEl.innerHTML = 'شهادة-رقم مرجعي: ST-' + res.sealID;
        }

        var authorSealIdEl = document.getElementById('authorSealId');
        if (authorSealIdEl) {
            authorSealIdEl.innerHTML = 'ST-' + res.sealID;
        }

        var modal = document.getElementById('qualityReportModal');
        var overlay = document.getElementById('qualityReportOverlay');

        var closeReport = function() {
            modal.classList.remove('active');
            overlay.classList.remove('active');
            document.body.style.overflow = '';
        };

        var openReport = function() {
            document.getElementById('reportIcon').innerHTML = level.icon;
            document.getElementById('reportScore').innerHTML = res.score + '%';
            document.getElementById('reportScore').style.color = level.color;
            document.getElementById('reportPostTitle').textContent = res.title;
            document.getElementById('reportSeal').innerHTML = 'شهادة توثيق رقمية: ST-' + res.sealID;

            document.getElementById('reportStats').innerHTML = 
                '<div class="quality-report-stat"><span>📝</span>' + res.wordCount + ' كلمة</div>' +
                '<div class="quality-report-stat"><span>🖼️</span>' + res.imageCount + ' صورة</div>' +
                '<div class="quality-report-stat"><span>🔗</span>' + res.intLinks + ' روابط</div>' +
                '<div class="quality-report-stat"><span>🌐</span>' + res.extLinks + ' مصادر</div>' +
                '<div class="quality-report-stat"><span>⭐</span>' + level.level + '</div>';

            document.getElementById('reportDetails').innerHTML = res.details.map(function(d) {
                return '<div class="quality-report-detail">' +
                    '<span class="quality-report-detail-name">' + d.name + '</span>' +
                    '<div class="quality-report-detail-status">' +
                        '<span class="quality-report-detail-score">' + d.score + '/' + d.max + '</span>' +
                        '<span class="quality-report-detail-badge ' + (d.status === 'pass' ? 'badge-pass' : (d.status === 'warning' ? 'badge-warning' : 'badge-fail')) + '">' +
                            (d.status === 'pass' ? '✓ ناجح' : (d.status === 'warning' ? '⚠️ متوسط' : '✗ ضعيف')) +
                        '</span>' +
                    '</div>' +
                '</div>';
            }).join('');

            document.getElementById('reportFooter').innerHTML = res.passed ? '✅ تم التصديق على جودة المحتوى' : '⚠️ المقال بحاجة إلى تحسين SEO تقني';

            modal.classList.add('active');
            overlay.classList.add('active');
            document.body.style.overflow = 'hidden';
        };

        var analyzeBtn = document.getElementById('qualityAnalyzeBtn');
        if (!analyzeBtn) return;

        var SECRET_PASSWORD = getSecretPassword();
        var isUnlocked = sessionStorage.getItem('quality_unlocked') === 'true';

        var openReportWithCheck = function() {
            if (isUnlocked) {
                openReport();
            } else {
                var pwd = prompt('🔒 هذه الميزة مقيدة للمدير فقط\n\nأدخل كلمة المرور:');
                if (pwd === SECRET_PASSWORD) {
                    isUnlocked = true;
                    sessionStorage.setItem('quality_unlocked', 'true');
                    openReport();
                } else if (pwd !== null) {
                    alert('❌ كلمة المرور غير صحيحة');
                }
            }
        };

        analyzeBtn.onclick = function(e) { 
            e.stopPropagation(); 
            openReportWithCheck(); 
        };

        if (overlay) overlay.onclick = closeReport;
        var closeBtn = document.getElementById('closeReportBtn');
        if (closeBtn) closeBtn.onclick = closeReport;

        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && modal && modal.classList.contains('active')) closeReport();
        });

        window.seoturboQualityLoaded = true;
    }

    if (document.readyState === 'complete') {
        setTimeout(updateQualitySystem, 1500);
    } else {
        window.addEventListener('load', function() { setTimeout(updateQualitySystem, 1500); });
    }

})();

/* === SEOTurbo Module 57: 57-تفاعل-شات-بوت-سيوتربو-الذكي === */

window._defer(function() {
    'use strict';

    var freePopup = document.getElementById('seoturbo-chatbot-free-popup');
    var freeBtn = document.getElementById('seoturbo-chatbot-free-btn');
    var originalChatbot = document.getElementById('chatbot-original');

    if (freePopup) freePopup.style.display = 'none';
    if (freeBtn) freeBtn.style.display = 'none';
    if (originalChatbot) originalChatbot.style.display = 'block';

    let siteNameForChat = '';

    function removeArabicDiacritics(text) {
        if (typeof text !== 'string') return text;
        text = text.replace(/&#\d+;/g, function(match) {
            try {
                var tempDiv = document.createElement('div');
                tempDiv.innerHTML = match;
                return tempDiv.textContent || tempDiv.innerText || "";
            } catch(e) { return ""; }
        });
        text = text.replace(/[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED]/g, '');
        text = text.replace(/[!"#$%&'()*+,\-.\/:;<=>?@\[\\\]^_`{|}~]/g, '');
        text = text.replace(/\s+/g, ' ').trim();
        return text;
    }

    let qaFromSchema = [];  
    function loadQAFromSchema() {
        qaFromSchema = [];
        var schemaScript = document.getElementById('qaData');
        if (schemaScript && schemaScript.textContent) {
            try {
                var schemaData = JSON.parse(schemaScript.textContent);
                if (schemaData.mainEntity && schemaData.mainEntity.text && schemaData.mainEntity.acceptedAnswer) {
                    qaFromSchema.push({
                        q: schemaData.mainEntity.text,
                        a: schemaData.mainEntity.acceptedAnswer.text || "لم يتم العثور على إجابة"
                    });
                }
                if (schemaData.hasPart && Array.isArray(schemaData.hasPart)) {
                    for (var i = 0; i < schemaData.hasPart.length; i++) {
                        var part = schemaData.hasPart[i];
                        if (part.text && part.acceptedAnswer && part.acceptedAnswer.text) {
                            qaFromSchema.push({
                                q: part.text,
                                a: part.acceptedAnswer.text
                            });
                        }
                    }
                }
                if (qaFromSchema.length > 0) {
                    console.log('✅ تم تحميل ' + qaFromSchema.length + ' سؤال من سكيما المقال');
                    return true;
                }
            } catch(e) { console.warn('خطأ في قراءة سكيما:', e); }
        }
        qaFromSchema = [
            { q: "ما هو الموضوع الرئيسي؟", a: "SEOTurbo Blogger Template - قالب بلوجر احترافي متقدم" },
            { q: "كم يستغرق القراءة؟", a: "حوالي 1-2 دقائق" },
            { q: "كيف أجد مقالات مشابهة؟", a: "استخدم مربع البحث أعلى الموقع أو تصفح الأقسام من القائمة الرئيسية" },
            { q: "ما هو التصنيف؟", a: "الموثوقية الرقمية" }
        ];
        console.log('📌 تم استخدام الأسئلة الافتراضية');
        return false;
    }

    function getRealArticleCategory() {
        var vault = document.getElementById('seoturbo-data-vault');
        if (vault && vault.getAttribute('data-label')) {
            var vaultLabel = vault.getAttribute('data-label');
            if (vaultLabel && vaultLabel !== '' && vaultLabel !== 'وصفات') {
                return vaultLabel;
            }
        }
        if (window.postLabels && window.postLabels.length > 0) {
            var firstLabel = window.postLabels[0];
            if (firstLabel && firstLabel !== '') {
                return firstLabel;
            }
        }
        var postcat = document.querySelector('.postcat, .seoturbo-title-keyword-badge');
        if (postcat && postcat.textContent.trim() !== '') {
            var catText = postcat.textContent.trim();
            if (catText !== 'موضوعات' && catText !== 'عام') {
                return catText;
            }
        }
        var breadcrumb = document.querySelector('.seoturbo-breadcrumbs-current.bc-target');
        if (breadcrumb && breadcrumb.textContent.trim() !== '') {
            var bcText = breadcrumb.textContent.trim();
            if (bcText !== 'موضوعات' && bcText !== 'عام') {
                return bcText;
            }
        }
        var urlPath = window.location.pathname;
        if (urlPath.includes('/search/label/')) {
            var labelFromUrl = decodeURIComponent(urlPath.split('/search/label/')[1].split(/[?#]/)[0]);
            if (labelFromUrl && labelFromUrl !== '') {
                return labelFromUrl;
            }
        }
        return 'عام';
    }

    function getPostContent() {
        var postBody = document.querySelector('.post-body.entry-content') || 
                       document.querySelector('.post-body') ||
                       document.querySelector('article .entry-content') ||
                       document.querySelector('.hentry .entry-content');
        if (postBody) {
            var clone = postBody.cloneNode(true);
            var removeSelectors = ['script', 'style', 'iframe', '.separator', '.tr-caption-container', '.main-table', 'section', 'footer'];
            for (var i = 0; i < removeSelectors.length; i++) {
                var elements = clone.querySelectorAll(removeSelectors[i]);
                for (var j = 0; j < elements.length; j++) {
                    elements[j].remove();
                }
            }
            var text = clone.innerText || clone.textContent || '';
            text = text.replace(/\s+/g, ' ').trim();
            return text;
        }
        return '';
    }

    function getCurrentArticleContext() {
        var titleElem = document.querySelector('.seoturbo-title-main-headline, h1, .post-title, .entry-title');
        var title = titleElem ? titleElem.textContent.trim() : document.title.split(' - ')[0] || 'مقال';
        var content = getPostContent();
        var category = getRealArticleCategory();
        var wordCount = content.split(/\s+/).filter(function(w) { return w.length > 0; }).length;
        var readTime = Math.ceil(wordCount / 250);
        return { title: title, content: content, category: category, wordCount: wordCount, readTime: readTime };
    }

    function findAnswerFromQA(question) {
        if (!question || question.length < 3) return null;
        var normalizedQuestion = question.toLowerCase().trim();
        for (var i = 0; i < qaFromSchema.length; i++) {
            var item = qaFromSchema[i];
            if (normalizedQuestion.includes(item.q.toLowerCase().slice(0, 15)) ||
                item.q.toLowerCase().includes(normalizedQuestion.slice(0, 15))) {
                return item.a;
            }
        }
        return null;
    }

    function summarizeContent(content, maxSentences) {
        maxSentences = maxSentences || 6;
        if (!content || content.length < 100) return null;
        var sentences = content.split(/[.!?؟!]\s+/);
        var validSentences = [];
        for (var i = 0; i < sentences.length; i++) {
            var sentence = sentences[i].trim();
            if (sentence.length > 30 && sentence.length < 300) {
                validSentences.push(sentence);
            }
        }
        if (validSentences.length === 0) return content.substring(0, 300) + '...';
        var summary = validSentences.slice(0, maxSentences).join('. ') + '.';
        if (summary.length > 600) summary = summary.substring(0, 600) + '...';
        return summary;
    }

    function extractKeyPoints(content, maxPoints) {
        maxPoints = maxPoints || 6;
        if (!content || content.length < 100) return null;
        var points = [];
        var paragraphs = content.split(/\n+/);
        for (var i = 0; i < paragraphs.length && points.length < maxPoints; i++) {
            var para = paragraphs[i].trim();
            if (para.length > 40 && para.length < 350) {
                points.push("• " + para.substring(0, 120) + (para.length > 120 ? '...' : ''));
            }
        }
        if (points.length === 0 && content.length > 0) {
            points.push("• " + content.substring(0, 150) + "...");
        }
        return points;
    }

    function formatFAQWithColors() {
        if (!qaFromSchema || qaFromSchema.length === 0) return null;    
        var html = '<div style="direction: rtl;">';
        html += '<div style="font-size: 16px; font-weight: bold; margin-bottom: 15px; text-align: center;">❓ أسئلة وأجوبة عن الموضوع</div>';
        html += '<div style="border-right: 3px solid var(--blogcolor); padding-right: 10px;">';    
        for (var i = 0; i < qaFromSchema.length; i++) {
            var num = i + 1;
            html += '<div style="margin-bottom: 15px;">';
            html += '<div style="display: flex; align-items: center; gap: 8px; margin-bottom: 5px;">';
            html += '<span style="background: var(--blogcolor); color: white; width: 24px; height: 24px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 12px; font-weight: bold;">' + num + '</span>';
            html += '<span style="font-weight: bold; color: var(--blogcolor);">سؤال:</span>';
            html += '<span style="font-weight: bold;">' + qaFromSchema[i].q + '</span>';
            html += '</div>';
            html += '<div style="display: flex; align-items: flex-start; gap: 8px; margin-right: 32px;">';
            html += '<span style="color: #27ae60; font-weight: bold;">✓</span>';
            html += '<span style="color: #fff;">الإجابة: ' + qaFromSchema[i].a + '</span>';
            html += '</div>';
            html += '</div>';
        }    
        html += '</div></div>';
        return html;
    }

    function getWelcomeMessage() {
        var context = getCurrentArticleContext();
        return "✨ **مرحباً بك في شات بوت سيوتربو الذكي لـ " + siteNameForChat + "** ✨\n\n" +
               "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n" +
               "🤖 **أنا هنا لمساعدتك في استكشاف هذا المقال بشكل أعمق!**\n\n" +
               "📌 **يمكنك أن تطلب مني:**\n\n" +
               "📝 **لخص المقال** - سأقدم لك ملخصاً شاملاً للمحتوى\n" +
               "💡 **أهم النقاط** - سأستخرج لك النقاط الرئيسية من المقال\n" +
               "ℹ️ **معلومات المقال** - سأعرض لك تفاصيل (عدد الكلمات، وقت القراءة، التصنيف)\n" +
               "❓ **أسئلة وأجوبة** - سأعرض لك الأسئلة الشائعة حسب محتوى المقال\n" +
               "📊 **تحليل المحتوى** - سأحلل لك جودة المحتوى ومدى فائدته\n\n" +
               "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n" +
               "💬 **فقط اضغط على أي زر من الأزرار الملونة أعلاه**\n" +
               "📖 **أو اكتب سؤالك مباشرة وسأجيبك بناءً على محتوى المقال**\n\n" +
               "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n" +
               "📁 **التصنيف الحالي:** " + context.category + "\n" +
               "⏱️ **وقت القراءة المقدر:** " + context.readTime + " دقائق";
    }

    function generateResponse(userMessage, actionType) {
        var context = getCurrentArticleContext();
        var lowerMsg = userMessage.toLowerCase();

        if (actionType === 'faq' || lowerMsg.includes('اسئلة') || lowerMsg.includes('أجوبة') || lowerMsg.includes('faq') || lowerMsg.includes('سؤال')) {
            var formattedFaq = formatFAQWithColors();
            if (formattedFaq) {
                return formattedFaq;
            }
            return "❓ **أسئلة شائعة**\n\n1️⃣ **سؤال:** ما هو الموضوع الرئيسي؟\n   ✓ الإجابة: " + (context.title || "هذا المقال يناقش موضوعاً مهماً") + "\n\n2️⃣ **سؤال:** كم يستغرق القراءة؟\n   ✓ الإجابة: حوالي " + context.readTime + " دقائق\n\n3️⃣ **سؤال:** كيف أجد مقالات مشابهة؟\n   ✓ الإجابة: استخدم مربع البحث أو الأزرار أعلاه";
        }

        if (userMessage && userMessage.length > 3 && !lowerMsg.includes('مرحب') && !lowerMsg.includes('اهلا')) {
            var qaAnswer = findAnswerFromQA(userMessage);
            if (qaAnswer) {
                return "📖 **إجابة سؤالك:**\n\n✓ " + qaAnswer;
            }
        }    
        if (actionType === 'summary' || lowerMsg.includes('لخص') || lowerMsg.includes('ملخص') || lowerMsg.includes('خلاصة')) {
            if (!context.content || context.content.length < 100) {
                return "📝 **عذراً**\n\nلا يوجد محتوى كافٍ في هذا المقال لتلخيصه.";
            }
            var summary = summarizeContent(context.content, 6);
            if (!summary) {
                return "📝 **عذراً**\n\nتعذر تلخيص المقال.";
            }
            return "📝 **ملخص المقال**\n\n" + summary + "\n\n📊 **إحصائيات:** " + context.wordCount + " كلمة | " + context.readTime + " دقائق قراءة\n\n📁 **التصنيف:** " + context.category;
        }    
        if (actionType === 'keypoints' || lowerMsg.includes('نقاط') || lowerMsg.includes('أهم') || lowerMsg.includes('مفاتيح')) {
            if (!context.content || context.content.length < 100) {
                return "💡 **عذراً**\n\nلا يوجد محتوى كافٍ لاستخراج النقاط المهمة.";
            }
            var points = extractKeyPoints(context.content, 6);
            if (!points || points.length === 0) {
                return "💡 **عذراً**\n\nتعذر استخراج النقاط الرئيسية.";
            }
            return "💡 **أهم النقاط في المقال**\n\n" + points.join('\n\n') + "\n\n📁 **التصنيف:** " + context.category;
        }    
        if (actionType === 'info' || lowerMsg.includes('معلومات') || lowerMsg.includes('عن المقال') || lowerMsg.includes('تفاصيل')) {
            return "ℹ️ **معلومات المقال**\n\n• **العنوان:** " + (context.title || 'غير محدد') + "\n• **التصنيف:** " + (context.category || 'عام') + "\n• **عدد الكلمات:** " + context.wordCount + "\n• **وقت القراءة:** " + context.readTime + " دقائق";
        }    
        if (actionType === 'opinion' || lowerMsg.includes('رأي') || lowerMsg.includes('تقييم') || lowerMsg.includes('تحليل')) {
            if (context.wordCount > 1000) return "📊 **تحليل المحتوى:**\n\nهذا المقال طويل ومفصل (" + context.wordCount + " كلمة)، يغطي الموضوع بشكل شامل.\n\n✅ إيجابيات: تغطية كاملة، معلومات غنية\n💡 اقتراح: يمكن إضافة جدول محتويات\n\n📁 **التصنيف:** " + context.category;
            if (context.wordCount > 400) return "📊 **تحليل المحتوى:**\n\nهذا المقال متوسط الطول (" + context.wordCount + " كلمة)، يغطي النقاط الرئيسية بشكل جيد.\n\n✅ إيجابيات: معلومات مركزة، سهل القراءة\n\n📁 **التصنيف:** " + context.category;
            return "📊 **تحليل المحتوى:**\n\nهذا المقال قصير (" + context.wordCount + " كلمة)، مناسب كمقدمة للموضوع.\n\n⚠️ يمكن توسيع المحتوى لإضافة قيمة أكبر.\n\n📁 **التصنيف:** " + context.category;
        }   
        return getWelcomeMessage();
    }

    window.seoturboChatbot = {
        open: function() {
            var c = document.getElementById('seoturbo_chatbot_container');
            if (c) c.style.display = 'flex';
        },
        close: function() {
            var container = document.getElementById('seoturbo_chatbot_container');
            if (container) container.style.display = 'none';
        },
        init: function() {
            loadQAFromSchema();
            this.bindEvents();
            this.sendWelcome();
            this.buildQuickActions();
        },
        buildQuickActions: function() {
            var actionsContainer = document.getElementById('seoturbo_chatbot_quick_actions');
            if (!actionsContainer) return;
            var actions = [
                { icon: "📝", text: "لخص المقال", action: "summary" },
                { icon: "💡", text: "أهم النقاط", action: "keypoints" },
                { icon: "ℹ️", text: "معلومات المقال", action: "info" },
                { icon: "❓", text: "أسئلة وأجوبة", action: "faq" },
                { icon: "📊", text: "تحليل المحتوى", action: "opinion" }
            ];
            var html = '';
            for (var i = 0; i < actions.length; i++) {
                html += '<button class="seoturbo_chatbot_action_btn" data-action="' + actions[i].action + '">' + actions[i].icon + ' ' + actions[i].text + '</button>';
            }
            actionsContainer.innerHTML = html;
            var btns = actionsContainer.querySelectorAll('.seoturbo_chatbot_action_btn');
            for (var j = 0; j < btns.length; j++) {
                btns[j].addEventListener('click', function() {
                    var action = this.getAttribute('data-action');
                    window.seoturboChatbot.handleAction(action);
                });
            }
        },
        handleAction: function(action) {
            var self = this;
            var actionMap = {
                'summary': 'لخص لي هذا المقال',
                'keypoints': 'ما هي أهم النقاط في هذا المقال؟',
                'info': 'أعطني معلومات عن هذا المقال',
                'faq': 'أسئلة وأجوبة عن هذا الموضوع',
                'opinion': 'ما هو تحليلك لهذا المقال؟'
            };
            var message = actionMap[action] || action;

            if (action === 'faq') {
                this.addMsg(message, 'user');
                var thinkingMsg = this.addMsg('🤔 جاري تحميل الأسئلة والأجوبة...', 'bot', true);
                setTimeout(function() {
                    var messagesArea = document.getElementById('seoturbo_chatbot_messages');
                    if (messagesArea && thinkingMsg && messagesArea.contains(thinkingMsg)) {
                        messagesArea.removeChild(thinkingMsg);
                    }
                    var response = generateResponse(message, 'faq');
                    if (response.indexOf('<div') === 0) {
                        var msgDiv = document.createElement('div');
                        msgDiv.className = 'seoturbo_chatbot_message seoturbo_chatbot_bot_msg';
                        msgDiv.innerHTML = response;
                        messagesArea.appendChild(msgDiv);
                        messagesArea.scrollTop = messagesArea.scrollHeight;
                    } else {
                        self.addMsg(response, 'bot');
                    }
                }, 400);
                return;
            }      
            this.handleUserInput(message);
        },
        bindEvents: function() {
            var inputField = document.getElementById('seoturbo_chatbot_input');
            var sendButton = document.getElementById('seoturbo_chatbot_send');
            var toggleBtn = document.getElementById('seoturbo_chatbot_toggle_btn');
            var closeBtn = document.getElementById('seoturbo_chatbot_close_btn');      
            if (toggleBtn) {
                toggleBtn.onclick = function(e) {
                    e.stopPropagation();
                    window.seoturboChatbot.open();
                };
            }
            if (closeBtn) {
                closeBtn.onclick = function() {
                    window.seoturboChatbot.close();
                };
            }

            if (inputField) {
                inputField.addEventListener('keypress', function(e) {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        var input = document.getElementById('seoturbo_chatbot_input');
                        window.seoturboChatbot.handleUserInput(input.value);
                    }
                });
            }
            if (sendButton) {
                sendButton.addEventListener('click', function() {
                    var input = document.getElementById('seoturbo_chatbot_input');
                    window.seoturboChatbot.handleUserInput(input.value);
                });
            }
        },
        sendWelcome: function() {
            var welcomeMsg = getWelcomeMessage();
            this.addMsg(welcomeMsg, 'bot');
        },
        handleUserInput: function(message) {
            var input = document.getElementById('seoturbo_chatbot_input');
            if (!message || message.trim() === '') return;
            this.addMsg(message, 'user');
            if (input) input.value = '';      
            var self = this;
            var thinkingMsg = this.addMsg('🤔 جاري التفكير...', 'bot', true);      
            setTimeout(function() {
                var messagesArea = document.getElementById('seoturbo_chatbot_messages');
                if (messagesArea && thinkingMsg && messagesArea.contains(thinkingMsg)) {
                    messagesArea.removeChild(thinkingMsg);
                }
                var response = generateResponse(message, '');

                if (response.indexOf('<div') === 0) {
                    var msgDiv = document.createElement('div');
                    msgDiv.className = 'seoturbo_chatbot_message seoturbo_chatbot_bot_msg';
                    msgDiv.innerHTML = response;
                    messagesArea.appendChild(msgDiv);
                    messagesArea.scrollTop = messagesArea.scrollHeight;
                } else {
                    self.addMsg(response, 'bot');
                }
            }, 400);
        },
        addMsg: function(text, type, isTemp) {
            var messagesArea = document.getElementById('seoturbo_chatbot_messages');
            if (!messagesArea) return null;
            var processedText = removeArabicDiacritics(text);
            var messageDiv = document.createElement('div');
            messageDiv.className = 'seoturbo_chatbot_message ' + (type === 'user' ? 'seoturbo_chatbot_user_msg' : 'seoturbo_chatbot_bot_msg');
            var lines = processedText.split('\n');
            for (var i = 0; i < lines.length; i++) {
                messageDiv.appendChild(document.createTextNode(lines[i]));
                if (i < lines.length - 1) {
                    messageDiv.appendChild(document.createElement('br'));
                }
            }
            messagesArea.appendChild(messageDiv);
            messagesArea.scrollTop = messagesArea.scrollHeight;
            if (isTemp) return messageDiv;
            return null;
        }
    };

    document.addEventListener('DOMContentLoaded', function() {
        var vault = document.getElementById('homepage-identity-vault');
        if (vault && vault.getAttribute('data-name')) {
            siteNameForChat = removeArabicDiacritics(vault.getAttribute('data-name'));
        } else {
            var siteTitle = document.querySelector('.site-title a, .site-title');
            if (siteTitle) {
                siteNameForChat = removeArabicDiacritics(siteTitle.textContent.trim());
            } else {
                siteNameForChat = removeArabicDiacritics(document.title.split(' - ')[0] || 'الموقع');
            }
        }    
        var headerLogo = document.querySelector('#Header1_headerimg, .header-widget img, .seoturbo-site-logo img');
        var siteImageForChat = headerLogo ? headerLogo.src : '';    
        var siteNameInHeader = document.getElementById('seoturbo_chatbot_site_name_in_header');
        if (siteNameInHeader) siteNameInHeader.textContent = siteNameForChat;
        var dynamicSiteName = document.getElementById('seoturbo_chatbot_dynamic_site_name');
        if (dynamicSiteName) dynamicSiteName.textContent = siteNameForChat;    
        var rectTitle = document.getElementById('seoturbo_chatbot_rect_title');
        if (rectTitle) rectTitle.innerText = removeArabicDiacritics(rectTitle.innerText);
        var rectAsk = document.getElementById('seoturbo_chatbot_rect_ask');
        if (rectAsk) rectAsk.innerText = removeArabicDiacritics(rectAsk.innerText);
        var headerTitle = document.getElementById('seoturbo_chatbot_header_title');
        if (headerTitle) headerTitle.innerText = removeArabicDiacritics(headerTitle.innerText);    
        var sendBtn = document.getElementById('seoturbo_chatbot_send');
        if (sendBtn) sendBtn.textContent = removeArabicDiacritics(sendBtn.textContent);    
        var inputElem = document.getElementById('seoturbo_chatbot_input');
        if (inputElem) inputElem.placeholder = removeArabicDiacritics(inputElem.placeholder);    
        if (siteImageForChat) {
            var buttonTextDiv = document.querySelector('.seoturbo_chatbot_button_text');
            var dynamicSiteNameSpan = document.getElementById('seoturbo_chatbot_dynamic_site_name');
            if (buttonTextDiv && dynamicSiteNameSpan) {
                var existingImg = buttonTextDiv.querySelector('.seoturbo_chatbot_logo');
                if (!existingImg) {
                    var imgRectangular = document.createElement('img');
                    imgRectangular.src = siteImageForChat;
                    imgRectangular.alt = siteNameForChat;
                    imgRectangular.className = 'seoturbo_chatbot_logo';
                    buttonTextDiv.insertBefore(imgRectangular, dynamicSiteNameSpan);
                }
            }
            var logoContainer = document.getElementById('seoturbo_chatbot_logo_container');
            if (logoContainer && !logoContainer.querySelector('img')) {
                var imgContainer = document.createElement('img');
                imgContainer.src = siteImageForChat;
                imgContainer.alt = siteNameForChat;
                logoContainer.appendChild(imgContainer);
            }
        }    
        var container = document.getElementById('seoturbo_chatbot_container');
        if (container) container.style.display = 'none';

        window.seoturboChatbot.init();
    });
});

/* === SEOTurbo Module 58: 58-تفاعل-تلخيص-المقال === */

(function() {
    'use strict';

    var freePopup = document.getElementById('seoturbo-summary-free-popup');
    var freeBtn = document.getElementById('seoturbo-summary-free-btn');
    var originalSummary = document.getElementById('summary-original');

    if (freePopup) freePopup.style.display = 'none';
    if (freeBtn) freeBtn.style.display = 'none';
    if (originalSummary) originalSummary.style.display = 'block';

    function seoturboExtractKeySentences(text, maxSentences) {
        maxSentences = maxSentences || 5;
        var sentences = text.split(/[.!?؟!]\s+/);
        var importantWords = ['مهم', 'أساسي', 'خلاصة', 'ختاماً', 'لذلك', 'بالتالي', 'أخيراً', 'نستنتج', 'تعتبر', 'يهدف', 'يجب'];
        var scored = [];
        for (var i = 0; i < sentences.length; i++) {
            var sentence = sentences[i];
            var score = sentence.length;
            for (var j = 0; j < importantWords.length; j++) {
                if (sentence.indexOf(importantWords[j]) !== -1) score += 40;
            }
            scored.push({ text: sentence, score: score });
        }
        scored.sort(function(a, b) { return b.score - a.score; });
        var topSentences = scored.slice(0, maxSentences);
        topSentences.sort(function(a, b) { return sentences.indexOf(a.text) - sentences.indexOf(b.text); });
        var result = [];
        for (var k = 0; k < topSentences.length; k++) {
            var trimmed = topSentences[k].text.trim();
            if (trimmed.length > 25) result.push(trimmed);
        }
        return result;
    }

    function seoturboExtractKeywords(text, maxKeywords) {
        maxKeywords = maxKeywords || 6;
        var stopWords = ['في', 'من', 'إلى', 'على', 'عن', 'مع', 'هذا', 'هذه', 'ذلك', 'هناك', 'كان', 'يكون', 'التي', 'الذي'];
        var words = text.split(/\s+/);
        var freq = {};
        for (var i = 0; i < words.length; i++) {
            var clean = words[i].replace(/[^\u0600-\u06FF\w]/g, '').toLowerCase();
            if (clean.length > 3 && stopWords.indexOf(clean) === -1) {
                freq[clean] = (freq[clean] || 0) + 1;
            }
        }
        var entries = [];
        for (var key in freq) {
            if (freq.hasOwnProperty(key)) {
                entries.push([key, freq[key]]);
            }
        }
        entries.sort(function(a, b) { return b[1] - a[1]; });
        var top = entries.slice(0, maxKeywords);
        var result = [];
        for (var j = 0; j < top.length; j++) {
            result.push(top[j][0]);
        }
        return result;
    }

    function seoturboGenerateRichSummary() {
        var postBody = document.querySelector('.post-body.entry-content, .post-body');
        if (!postBody) return 'تعذر العثور على محتوى المقال.';
        var clone = postBody.cloneNode(true);
        var removeSelectors = ['script', 'style', 'iframe', '.seoterbo-frame-root-container', '.topcs7v', '.post-share-section', '.commentsection', '.trust-container', '.post-tags-container'];
        for (var i = 0; i < removeSelectors.length; i++) {
            var elements = clone.querySelectorAll(removeSelectors[i]);
            for (var j = 0; j < elements.length; j++) {
                elements[j].remove();
            }
        }
        var text = clone.textContent || clone.innerText || '';
        text = text.replace(/\s+/g, ' ').trim();
        if (text.length < 250) return 'المحتوى قصير جداً للتلخيص.';

        var keySentences = seoturboExtractKeySentences(text, 4);
        var keywords = seoturboExtractKeywords(text, 6);
        var wordCount = text.split(/\s+/).length;
        var readTime = Math.ceil(wordCount / 200);

        var html = '<div style="direction:rtl; text-align:right;">';        
        html += '<div style="margin-bottom:20px;"><strong>📌 النقاط الرئيسية:</strong><br><br>';
        if (keySentences.length > 0) {
            for (var k = 0; k < keySentences.length; k++) {
                html += '• ' + keySentences[k] + '.<br><br>';
            }
        } else {
            html += '• ' + text.substring(0, 300) + '...';
        }
        html += '</div>';
        if (keywords.length > 0) {
            html += '<div style="margin-bottom:20px;"><strong>🔑 محاور التركيز:</strong><br><br>';
            html += '<div style="display:flex; flex-wrap:wrap; gap:8px;">';
            for (var kw = 0; kw < keywords.length; kw++) {
                html += '<span style="background:var(--blogcolor); color:#fff; padding:4px 12px; border-radius:20px; font-size:12px; font-weight:700;">#' + keywords[kw] + '</span>';
            }
            html += '</div></div>';
        }
        html += '<div style="margin-top:15px; padding-top:10px; border-top:1px dashed #333; font-size:12px; color:#aaa;">📊 ' + readTime + ' دقائق قراءة | ' + wordCount + ' كلمة</div></div>';
        return html;
    }

    function seoturboInitSummaryAction() {
        var btn = document.getElementById('seoturboSummaryBtn');
        var popup = document.getElementById('seoturboSummaryPopup');
        var content = document.getElementById('seoturboSummaryContent');
        var close = document.getElementById('seoturboSummaryClose');
        if (!btn || !popup || !content) return;

        btn.onclick = function(e) {
            e.stopPropagation();
            if (popup.style.display !== 'flex') {
                popup.style.display = 'flex';
                content.innerHTML = '<div style="text-align:center;padding:30px;">⏳ جاري التلخيص...</div>';
                setTimeout(function() { 
                    content.innerHTML = seoturboGenerateRichSummary(); 
                }, 600);
            } else {
                popup.style.display = 'none';
            }
        };
        if (close) {
            close.onclick = function() { popup.style.display = 'none'; };
        }
        document.addEventListener('click', function(e) {
            if (popup && popup.style.display === 'flex' && !popup.contains(e.target) && e.target !== btn) {
                popup.style.display = 'none';
            }
        });
    }

    if (window.requestIdleCallback) {
        requestIdleCallback(seoturboInitSummaryAction);
    } else {
        setTimeout(seoturboInitSummaryAction, 500);
    }
})();

/* === SEOTurbo Module 59: 59-تفاعل-نافذة-الهوية-والموثوقية.js === */

(function() {
    'use strict';    
    var trustBadges = document.querySelectorAll('.seoturbo-trust-badge-pill');    
    trustBadges.forEach(function(badge) {
        var newBadge = badge.cloneNode(true);
        badge.parentNode.replaceChild(newBadge, badge);        
        newBadge.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();            
            var panel = this.querySelector('.mega-trust-panel');
            if (!panel) return;            
            document.querySelectorAll('.mega-trust-panel').forEach(function(p) {
                if (p !== panel) {
                    p.style.opacity = '0';
                    p.style.visibility = 'hidden';
                    p.style.pointerEvents = 'none';
                }
            });            
            var isVisible = panel.style.opacity === '1';
            panel.style.opacity = isVisible ? '0' : '1';
            panel.style.visibility = isVisible ? 'hidden' : 'visible';
            panel.style.pointerEvents = isVisible ? 'none' : 'auto';
        });
    });    
    document.addEventListener('click', function(e) {
        if (!e.target.closest('.seoturbo-trust-badge-pill')) {
            document.querySelectorAll('.mega-trust-panel').forEach(function(panel) {
                panel.style.opacity = '0';
                panel.style.visibility = 'hidden';
                panel.style.pointerEvents = 'none';
            });
        }
    });

})();

/* === SEOTurbo Module 60: 60-شريط-علوي-أساسي.js) === */

(function() {
    'use strict';
    function initSiteIdentityElements() {
        var sloganMeta = document.querySelector('meta[name="siteSlogan"]');
        var sloganTarget = document.getElementById('mega-dynamic-slogan') || document.getElementById('sticky-mega-slogan');
        if (sloganTarget && sloganMeta) {
            var currentYear = new Date().getFullYear();
            sloganTarget.textContent = sloganMeta.content + " - " + currentYear;
        }
        var linkInput = document.getElementById('siteLinkInput');
        if (linkInput) {
            linkInput.value = window.location.origin.replace('https://', '').replace(/\/$/, '');
        }
        window.seoturboCopyText = function(text) {
            if (!text) return;
            navigator.clipboard.writeText(text);
        };
    }
    function updateTotalPostsCounter() {
        if (window.ST_MASTER_PROMISE) {
            window.ST_MASTER_PROMISE.then(function(data) {
                if (data && data.feed && data.feed.openSearch$totalResults) {
                    var total = data.feed.openSearch$totalResults.$t;
                    var targets = ['tb-posts-count-mega', 'sticky-posts-count-mega'];

                    var totalStr = String(total);
                    while (totalStr.length < 10) { totalStr = '0' + totalStr; }

                    var digitsHTML = '<div class="digit-wrapper" style="display: flex; justify-content: center; gap: 2px; direction: ltr !important; flex-wrap: nowrap !important;">';
                    totalStr.split('').forEach(function(digit) {
                        digitsHTML += '<span class="digit-box" style="flex-shrink: 0;">' + digit + '</span>';
                    });
                    digitsHTML += '</div>';

                    targets.forEach(function(id) {
                        var el = document.getElementById(id);
                        if (el) { el.innerHTML = digitsHTML; }
                    });
                }
            });
        }
    }
    if (document.readyState === 'complete') {
        initSiteIdentityElements();
        updateTotalPostsCounter();
    } else {
        window.addEventListener('load', function() {
            initSiteIdentityElements();
            updateTotalPostsCounter();
        });
    }
})();

/* === SEOTurbo Module 61: 61-تفاعل-مؤشر-القراءة-وتوثيق-النسخ.js === */

(function() {
    'use strict';    
    const uxBar = document.getElementById('seoturbo-progress-bar');
    const uxQuote = document.getElementById('seoturbo-quote-btn');
    const uxToast = document.getElementById('seoturbo-ux-toast');
    const isPost = document.body.classList.contains('post-page') || document.querySelector('.post-body') !== null;
    let cachedScrollHeight = 0;
    let cachedWinHeight = 0;
    let ticking = false;
    function updateLayoutCache() {
        cachedScrollHeight = document.documentElement.scrollHeight;
        cachedWinHeight = window.innerHeight;
    }
    function showUxToast(msg) {
        if (!uxToast) return;
        requestAnimationFrame(() => {
            uxToast.textContent = msg;
            uxToast.classList.add('seoturbo-show');
            setTimeout(() => uxToast.classList.remove('seoturbo-show'), 2500);
        });
    }
    function interceptCopy(e) {
        const selection = window.getSelection();
        const selectedText = selection.toString();
        if (selectedText.length < 30) return;
        const siteName = document.title.split(' - ')[0];
        const pageUrl = window.location.href;
        const copyrightMsg = `\n\n— تمت الاستعانة بمحتوى من: ${siteName}\n— الرابط الأصلي: ${pageUrl}`;
        const finalContent = selectedText + copyrightMsg;
        if (e.clipboardData) {
            e.clipboardData.setData('text/plain', finalContent);
            e.preventDefault();
            showUxToast('✅ تم النسخ مع إضافة حقوق المصدر تلقائياً');
        }
    }
    function updateProgress(scrollT) {
        if (!uxBar || cachedScrollHeight <= cachedWinHeight) {
            ticking = false;
            return;
        }
        if (scrollT === undefined) { scrollT = window.pageYOffset || document.documentElement.scrollTop; }
        var progress = (scrollT / (cachedScrollHeight - cachedWinHeight)) * 100;        
        uxBar.style.width = Math.min(100, Math.max(0, progress)) + '%';
        ticking = false;
    }
    function handleFloatingButton() {
        if (!uxQuote || !isPost) return;
        const sel = window.getSelection();
        const text = sel.toString().trim();
        if (text.length > 10) {
            const range = sel.getRangeAt(0);
            const currentScrollY = window.pageYOffset || document.documentElement.scrollTop;
            const rect = range.getBoundingClientRect();
            const topPos = rect.top + currentScrollY - 55;
            const leftPos = rect.left + rect.width / 2;
            requestAnimationFrame(() => {
                uxQuote.style.display = 'flex';
                uxQuote.style.top = topPos + 'px';
                uxQuote.style.left = leftPos + 'px';
                uxQuote.style.transform = 'translateX(-50%)';
            });           
            uxQuote.onclick = (event) => {
                event.preventDefault();
                document.execCommand('copy'); 
                requestAnimationFrame(() => {
                    uxQuote.style.display = 'none';
                    sel.removeAllRanges();
                });
            };
        } else {
            if (uxQuote.style.display !== 'none') {
                requestAnimationFrame(() => { uxQuote.style.display = 'none'; });
            }
        }
    }
    if (isPost) {
        const postContent = document.querySelector('.post-body');
        if (postContent) {
            postContent.addEventListener('copy', interceptCopy);
        }
        window.addEventListener('load', () => {
            updateLayoutCache();
            var st = window.pageYOffset || document.documentElement.scrollTop;
            requestAnimationFrame(function() { updateProgress(st); });
        });
        window.addEventListener('resize', () => {
            updateLayoutCache();
        }, { passive: true });

        window.addEventListener('scroll', () => {
            if (!ticking) {
                var st = window.pageYOffset || document.documentElement.scrollTop;
                requestAnimationFrame(function() { updateProgress(st); });
                ticking = true;
            }
        }, { passive: true });        
        document.addEventListener('selectionchange', () => {
            clearTimeout(window.stSelectionT);
            window.stSelectionT = setTimeout(handleFloatingButton, 200);
        });
    }
})();

