(function() {
    'use strict';    
    const SEOTURBO_MASTER_KEY = document.querySelector('meta[name="seoturbo-quality-password"]')?.content || '1234';
    function runSeoturboPostLocker() {
        const lockTrigger = document.getElementById('seoturbo-lock-trigger');
        const postBody = document.querySelector('.post-body.entry-content') || document.querySelector('.post-body');        
        if (!lockTrigger || !postBody) return;
        const originalHtml = postBody.innerHTML;
        postBody.innerHTML = '';
        postBody.style.display = 'block'; // التأكد من أنه ليس مخفي بالـ CSS
        const lockUI = `
            <div class="seoturbo-lock-container">
                <div class="seoturbo-lock-icon">
                    <svg viewBox="0 0 24 24"><path d="M12 17a2 2 0 0 0 2-2 2 2 0 0 0-2-2 2 2 0 0 0-2 2 2 2 0 0 0 2 2m6-9a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V10a2 2 0 0 1 2-2h1V6a5 5 0 0 1 5-5 5 5 0 0 1 5 5v2h1m-6-5a3 3 0 0 0-3 3v2h6V6a3 3 0 0 0-3-3z"/></svg>
                </div>
                <h2 class="seoturbo-lock-title">محتوى مقفل برمجياً</h2>
                <p class="seoturbo-lock-text">هذا المقال يحتوي على بيانات خاصة محمية بكلمة مرور. يرجى إدخال رمز الوصول للمتابعة.</p>
                <div class="seoturbo-lock-form">
                    <input type="password" class="seoturbo-lock-input" id="seoturbo-pwd-field" placeholder="رمز الدخول..." autocomplete="off">
                    <button class="seoturbo-lock-btn" id="seoturbo-unlock-action">
                        فتح المحتوى الآن
                    </button>
                    <div id="seoturbo-error-msg" class="seoturbo-lock-error">⚠️ الرمز غير صحيح، حاول مرة أخرى!</div>
                </div>
            </div>
        `;
        postBody.innerHTML = lockUI;
        const btn = document.getElementById('seoturbo-unlock-action');
        const input = document.getElementById('seoturbo-pwd-field');
        const error = document.getElementById('seoturbo-error-msg');
        const handleUnlock = () => {
            if (input.value === SEOTURBO_MASTER_KEY) {
                postBody.style.opacity = '0';
                setTimeout(() => {
                    postBody.innerHTML = originalHtml;
                    postBody.style.opacity = '1';
                    postBody.style.transition = 'opacity 0.6s ease';
                    if (typeof initTOC === 'function') initTOC();
                }, 200);
            } else {
                error.style.display = 'block';
                input.style.borderColor = 'var(--google-red)';
                input.classList.add('seoturbo-shake');
                setTimeout(() => input.classList.remove('seoturbo-shake'), 500);
            }
        };
        btn.onclick = handleUnlock;
        input.onkeypress = (e) => { if (e.key === 'Enter') handleUnlock(); };
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', runSeoturboPostLocker);
    } else {
        runSeoturboPostLocker();
    }
})();

