        var c = seoturboHealthData.css || {}, a = seoturboHealthData.accessibility || {}, sec = seoturboHealthData.security || {};
        var an = seoturboHealthData.analytics || {};
        var speed = seoturboGetSpeedStatus(p.loadTime);

        var total = 0, max = 0;
        if (p.loadTime && p.loadTime < 1000) total += 10; else if (p.loadTime < 2000) total += 7; else if (p.loadTime < 3000) total += 4; else total += 1; max += 10;
        if (s.hasTitle) total += 5; max += 5;
        if (s.hasDescription) total += 5; max += 5;
        if (s.schemaCount > 0) total += 10; max += 10;
        if (s.hasSSL) total += 10; max += 10;
